window.SOURCES = window.SOURCES || {};
function source(fichier, nom, langage, code) {
  window.SOURCES[fichier + "\n" + nom] = { langage: langage, code: code, fichier: fichier };
}
source("admin/routes.py", "_admin_only", "python", "def _admin_only():\n    \"\"\"Compte connecté, puis contrôle du rôle admin.\"\"\"\n    user, error = require_user()\n    if error:\n        return None, error\n    refused = require_roles(user, (\"admin\", \"owner\"))\n    if refused:\n        return None, refused\n    return user, None\n");
source("admin/routes.py", "dashboard", "python", "@admin_bp.route(\"/dashboard\", methods=[\"GET\"])\n@jwt_required()\ndef dashboard():\n    \"\"\"Page pour parcourir les cours et modérer les fiches.\"\"\"\n    user, error = _admin_only()\n    if error:\n        return error\n    return render_template(\n        \"staff_dashboard.html\",\n        profil=public_profile(user),\n        prefix=\"/admin\",\n        comptes_url=\"/admin/comptes-page\",\n        titre=\"Espace administration\",\n    )\n");
source("admin/routes.py", "comptes_page", "python", "@admin_bp.route(\"/comptes-page\", methods=[\"GET\"])\n@jwt_required()\ndef comptes_page():\n    \"\"\"Liste des comptes, avec changement de rôle et suspension.\"\"\"\n    user, error = _admin_only()\n    if error:\n        return error\n    return render_template(\n        \"comptes.html\",\n        profil=public_profile(user),\n        comptes=list_profiles(),\n        prefix=\"/admin\",\n        peut_roles=True,\n        titre=\"Comptes\",\n    )\n");
source("admin/routes.py", "recherche_comptes", "python", "@admin_bp.route(\"/comptes/recherche\", methods=[\"GET\"])\n@jwt_required()\ndef recherche_comptes():\n    \"\"\"Comptes selon le nom, le rôle ou l'état. Réservé à l'administration et au propriétaire.\"\"\"\n    _user, error = _admin_only()\n    if error:\n        return error\n    resultat, erreur = chercher_comptes(request.args)\n    if erreur:\n        return jsonify({\"error\": erreur[0]}), erreur[1]\n    return jsonify(resultat), 200\n");
source("admin/routes.py", "modify_file", "python", "@admin_bp.route(\"/dashboard/modify/<file_id>\", methods=[\"GET\"])\n@jwt_required()\ndef modify_file(file_id):\n    \"\"\"Formulaire de modification d'une fiche, quel qu'en soit l'auteur.\"\"\"\n    user, error = _admin_only()\n    if error:\n        return error\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    metadata = read_metadata(find_metadata_path(file_id))\n    if metadata is None:\n        return error_response(\"Fiche introuvable\", 404)\n    return render_template(\n        \"modifier.html\",\n        metadata=public_metadata(metadata),\n        save_url=f\"/admin/dashboard/modify/save/{file_id}\",\n        retour_url=\"/admin/dashboard\",\n        titre=\"Modérer une fiche\",\n    )\n");
source("admin/routes.py", "save_modified_file", "python", "@admin_bp.route(\"/dashboard/modify/save/<file_id>\", methods=[\"POST\"])\n@jwt_required()\ndef save_modified_file(file_id):\n    \"\"\"Enregistre la modération. L'auteur d'origine est conservé.\"\"\"\n    _user, error = _admin_only()\n    if error:\n        return error\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    return update_file(owner, file_id, request.form, request.files.get(\"file\"), acteur=_user)\n");
source("admin/routes.py", "delete_file", "python", "@admin_bp.route(\"/dashboard/delete/<file_id>\", methods=[\"DELETE\"])\n@jwt_required()\ndef delete_file(file_id):\n    \"\"\"Supprime une fiche et la retire du compte de son auteur.\"\"\"\n    _user, error = _admin_only()\n    if error:\n        return error\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    return remove_file(owner, file_id)\n");
source("admin/routes.py", "ban_user", "python", "@admin_bp.route(\"/dashboard/ban/<user_id>\", methods=[\"POST\"])\n@jwt_required()\ndef ban_user(user_id):\n    \"\"\"Suspend un élève ou un modérateur. Le jeton déjà émis devient inutilisable.\"\"\"\n    user, error = _admin_only()\n    if error:\n        return error\n    return set_ban(user, user_id, True)\n");
source("admin/routes.py", "unban_user", "python", "@admin_bp.route(\"/dashboard/unban/<user_id>\", methods=[\"POST\"])\n@jwt_required()\ndef unban_user(user_id):\n    \"\"\"Réactive un compte suspendu.\"\"\"\n    user, error = _admin_only()\n    if error:\n        return error\n    return set_ban(user, user_id, False)\n");
source("admin/routes.py", "change_role", "python", "@admin_bp.route(\"/dashboard/role/<user_id>\", methods=[\"POST\"])\n@jwt_required()\ndef change_role(user_id):\n    \"\"\"Donne le rôle élève, modérateur ou administrateur.\"\"\"\n    user, error = _admin_only()\n    if error:\n        return error\n    data = request.get_json(silent=True)\n    if not isinstance(data, dict):\n        return jsonify({\"error\": \"Un objet JSON est requis\"}), 400\n    return set_role(user, user_id, data.get(\"role\"))\n");
source("app.py", "_load_secret", "python", "def _load_secret():\n    \"\"\"Clé de signature des jetons.\n\n    Elle vient de l'environnement en production. En local, elle est créée une\n    fois dans instance/jwt_secret (dossier ignoré par git) pour que les\n    sessions survivent à un redémarrage.\n    \"\"\"\n    from_env = os.environ.get(\"JWT_SECRET_KEY\")\n    if from_env:\n        return from_env\n\n    folder = Path(\"instance\")\n    folder.mkdir(exist_ok=True)\n    secret_file = folder / \"jwt_secret\"\n    if secret_file.is_file():\n        saved = secret_file.read_text(encoding=\"utf-8\").strip()\n        if saved:\n            return saved\n\n    generated = secrets.token_urlsafe(64)\n    secret_file.write_text(generated, encoding=\"utf-8\")\n    try:\n        os.chmod(secret_file, 0o600)\n    except OSError:\n        pass\n    return generated\n");
source("app.py", "create_app", "python", "def create_app():\n    \"\"\"Construit l'application Flask, la base et les protections HTTP.\"\"\"\n    app = Flask(__name__, static_folder=\"static\", template_folder=\"templates\")\n    secret = _load_secret()\n\n    # 100 Mo, aligné sur la limite Nginx (client_max_body_size).\n    app.config[\"MAX_CONTENT_LENGTH\"] = 100 * 1024 * 1024\n    app.secret_key = secret\n    app.config[\"JWT_SECRET_KEY\"] = secret\n    app.config[\"JWT_ALGORITHM\"] = \"HS256\"\n    # Une séance de révision tient dans la journée, sans cookie éternel.\n    app.config[\"JWT_ACCESS_TOKEN_EXPIRES\"] = timedelta(hours=8)\n    app.config[\"JWT_TOKEN_LOCATION\"] = [\"cookies\"]\n    # False en HTTP local. Mettre JWT_COOKIE_SECURE=1 derrière HTTPS.\n    app.config[\"JWT_COOKIE_SECURE\"] = os.environ.get(\"JWT_COOKIE_SECURE\", \"0\") == \"1\"\n    app.config[\"JWT_COOKIE_SAMESITE\"] = \"Lax\"\n    app.config[\"JWT_COOKIE_CSRF_PROTECT\"] = True\n    app.config[\"SQLALCHEMY_DATABASE_URI\"] = os.environ.get(\"DATABASE_URI\", \"sqlite:///users.db\")\n    app.config[\"SQLALCHEMY_TRACK_MODIFICATIONS\"] = False\n    app.json.ensure_ascii = False\n\n    jwt = JWTManager(app)\n    db.init_app(app)\n    Path(\"uploads\").mkdir(exist_ok=True)\n\n    with app.app_context():\n        db.create_all()\n        # Les colonnes nouvelles d'abord : la requête des propriétaires\n        # lit toute la ligne, y compris must_change_password.\n        _colonne_mot_de_passe()\n        _colonne_commentaire_corrigee()\n        _un_seul_proprietaire()\n\n    @jwt.token_in_blocklist_loader\n    def token_revoked(_header, payload):\n        \"\"\"Un ban, une déconnexion, ou un compte supprimé, invalide le cookie déjà émis.\"\"\"\n        from utils.presence import est_revoquee\n\n        user = db.session.get(User, payload.get(\"sub\"))\n        if user is None or user.is_ban:\n            return True\n        return est_revoquee(payload.get(\"jti\"))\n\n    @app.before_request\n    def site_en_pause():\n        \"\"\"Le propriétaire peut couper le site. Lui seul continue de passer.\"\"\"\n        from utils.site_gate import bloquer_si_suspendu\n\n        return bloquer_si_suspendu()\n\n    @app.before_request\n    def mot_de_passe_a_choisir():\n        \"\"\"À la première connexion, rien d'autre n'est ouvert que le choix du mot de passe.\"\"\"\n        from utils.access import forcer_mot_de_passe\n\n        return forcer_mot_de_passe()\n\n    @jwt.unauthorized_loader\n    def missing_token(reason):\n        if wants_html():\n            return redirect_to_login()\n        if \"csrf\" in str(reason).lower():\n            return jsonify({\"error\": \"Jeton de sécurité manquant. Recharge la page.\"}), 401\n        return jsonify({\"error\": \"Connexion requise\"}), 401\n\n    @jwt.invalid_token_loader\n    def invalid_token(_reason):\n        if wants_html():\n            return redirect_to_login()\n        return jsonify({\"error\": \"Session invalide\"}), 401\n\n    @jwt.expired_token_loader\n    def expired_token(_header, _payload):\n        if wants_html():\n            return redirect_to_login()\n        return jsonify({\"error\": \"Session expirée\"}), 401\n\n    @jwt.revoked_token_loader\n    def revoked_token(_header, _payload):\n        if wants_html():\n            return redirect_to_login()\n        return jsonify({\"error\": \"Compte suspendu ou indisponible\"}), 401\n\n    @app.after_request\n    def security_headers(response):\n        \"\"\"En-têtes qui limitent le sniffing, l'intégration dans une iframe et les fuites.\"\"\"\n        _noter_presence()\n        response.headers[\"X-Content-Type-Options\"] = \"nosniff\"\n        response.headers[\"X-Frame-Options\"] = \"DENY\"\n        response.headers[\"Referrer-Policy\"] = \"same-origin\"\n        response.headers[\"Content-Security-Policy\"] = (\n            \"default-src 'self'; img-src 'self' data:; style-src 'self'; \"\n            \"script-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'\"\n        )\n        if request.path.startswith((\"/users\", \"/admin\", \"/moderator\", \"/auth\", \"/owner\", \"/fiches\")):\n            response.headers[\"Cache-Control\"] = \"no-store\"\n        return response\n\n    @app.errorhandler(404)\n    def not_found(_error):\n        return error_response(\"Page introuvable\", 404)\n\n    @app.errorhandler(413)\n    def too_large(_error):\n        return error_response(\"Fichier trop volumineux (100 Mo maximum).\", 413)\n\n    @app.errorhandler(Exception)\n    def unexpected(error):\n        # Les erreurs HTTP (404, 413...) ont déjà leur traitement.\n        # Celles du jeton aussi : Flask choisit le gestionnaire le plus précis.\n        if isinstance(error, JWTExtendedException):\n            # Filet de sécurité si le gestionnaire précis du jeton n'a pas répondu.\n            if wants_html():\n                return redirect_to_login()\n            if \"csrf\" in str(error).lower():\n                return jsonify({\"error\": \"Jeton de sécurité manquant. Recharge la page.\"}), 401\n            return jsonify({\"error\": \"Session invalide\"}), 401\n        if isinstance(error, HTTPException):\n            return error_response(error.description or \"Erreur\", error.code or 500)\n        app.logger.exception(\"Erreur interne\")\n        return error_response(\"Erreur interne\", 500)\n\n    @app.route(\"/\")\n    def root():\n        \"\"\"L'adresse nue ouvre l'accueil.\"\"\"\n        return redirect(\"/accueil\")\n\n    @app.route(\"/accueil\")\n    def accueil():\n        \"\"\"Page principale : choisir un cours, lire ou publier.\"\"\"\n        return render_template(\"index.html\")\n\n    @app.route(\"/upload/<matiere>/<classe>/<specialite>\", methods=[\"POST\"])\n    @jwt_required()\n    def upload_file(matiere, classe, specialite):\n        \"\"\"Publie une fiche. L'auteur enregistré est le compte connecté.\"\"\"\n        user = db.session.get(User, get_jwt_identity())\n        if user is None:\n            return jsonify({\"error\": \"Compte introuvable\"}), 404\n        if user.is_ban:\n            return jsonify({\"error\": \"Compte suspendu\"}), 403\n        return store_upload(\n            user,\n            matiere,\n            classe,\n            specialite,\n            request.files.get(\"file\"),\n            request.form.get(\"title\"),\n            request.form.get(\"desc\"),\n        )\n\n    @app.route(\"/download/<matiere>/<classe>/<specialite>/<file_id>\", methods=[\"GET\"])\n    @jwt_required(optional=True)\n    def download_file(matiere, classe, specialite, file_id):\n        \"\"\"Envoie le fichier en téléchargement. La consultation reste ouverte sans compte.\n\n        Le nom d'origine est nettoyé, et le type annoncé est neutre, pour que le\n        navigateur n'exécute pas un document comme une page.\n        \"\"\"\n        found, error = resolve_download(matiere, classe, specialite, file_id)\n        if error:\n            return error\n\n        stored_filename, original_filename, cache = found\n        identity = get_jwt_identity()\n        if identity:\n            user = db.session.get(User, identity)\n            if user is not None and not user.is_ban:\n                remember_download(user, file_id, cache)\n\n        response = send_from_directory(\n            \"uploads\",\n            stored_filename,\n            as_attachment=True,\n            download_name=original_filename,\n            mimetype=\"application/octet-stream\",\n        )\n        response.headers[\"X-Content-Type-Options\"] = \"nosniff\"\n        return response\n\n    app.register_blueprint(info_bp)\n    app.register_blueprint(users_bp)\n    app.register_blueprint(auth_bp)\n    app.register_blueprint(moderator_bp)\n    app.register_blueprint(admin_bp)\n    app.register_blueprint(owner_bp)\n    app.register_blueprint(fiches_bp)\n    app.register_blueprint(legal_bp)\n    return app\n");
