source("app.py", "upload_file", "python", "    @app.route(\"/upload/<matiere>/<classe>/<specialite>\", methods=[\"POST\"])\n    @jwt_required()\n    def upload_file(matiere, classe, specialite):\n        \"\"\"Publie une fiche. L'auteur enregistré est le compte connecté.\"\"\"\n        user = db.session.get(User, get_jwt_identity())\n        if user is None:\n            return jsonify({\"error\": \"Compte introuvable\"}), 404\n        if user.is_ban:\n            return jsonify({\"error\": \"Compte suspendu\"}), 403\n        return store_upload(\n            user,\n            matiere,\n            classe,\n            specialite,\n            request.files.get(\"file\"),\n            request.form.get(\"title\"),\n            request.form.get(\"desc\"),\n        )\n");
source("app.py", "download_file", "python", "    @app.route(\"/download/<matiere>/<classe>/<specialite>/<file_id>\", methods=[\"GET\"])\n    @jwt_required(optional=True)\n    def download_file(matiere, classe, specialite, file_id):\n        \"\"\"Envoie le fichier en téléchargement. La consultation reste ouverte sans compte.\n\n        Le nom d'origine est nettoyé, et le type annoncé est neutre, pour que le\n        navigateur n'exécute pas un document comme une page.\n        \"\"\"\n        found, error = resolve_download(matiere, classe, specialite, file_id)\n        if error:\n            return error\n\n        stored_filename, original_filename, cache = found\n        identity = get_jwt_identity()\n        if identity:\n            user = db.session.get(User, identity)\n            if user is not None and not user.is_ban:\n                remember_download(user, file_id, cache)\n\n        response = send_from_directory(\n            \"uploads\",\n            stored_filename,\n            as_attachment=True,\n            download_name=original_filename,\n            mimetype=\"application/octet-stream\",\n        )\n        response.headers[\"X-Content-Type-Options\"] = \"nosniff\"\n        return response\n");
source("app.py", "_un_seul_proprietaire", "python", "def _un_seul_proprietaire():\n    \"\"\"Garde le propriétaire le plus ancien et interdit d'en créer un second.\n\n    L'index n'existe que pour SQLite, la base utilisée par le site.\n    La colonne du mot de passe est posée avant la lecture : une base\n    ancienne n'a pas encore must_change_password, et la requête la demande.\n    \"\"\"\n    _colonne_mot_de_passe()\n    proprietaires = (\n        User.query.filter_by(role=\"owner\")\n        .order_by(User.created_at.asc(), User.id.asc())\n        .all()\n    )\n    for extra in proprietaires[1:]:\n        extra.role = \"admin\"\n    if len(proprietaires) > 1:\n        db.session.commit()\n    if db.engine.url.get_backend_name() != \"sqlite\":\n        return\n    db.session.execute(text(\n        \"CREATE UNIQUE INDEX IF NOT EXISTS uq_un_seul_proprietaire \"\n        \"ON users (role) WHERE role = 'owner'\"\n    ))\n    db.session.commit()\n");
source("app.py", "_colonne_commentaire_corrigee", "python", "def _colonne_commentaire_corrigee():\n    \"\"\"Ajoute la colonne corrected aux bases déjà créées avant ce suivi.\"\"\"\n    if db.engine.url.get_backend_name() != \"sqlite\":\n        return\n    lignes = db.session.execute(text(\"PRAGMA table_info(comments)\")).all()\n    if not lignes or any(ligne[1] == \"corrected\" for ligne in lignes):\n        return\n    db.session.execute(text(\n        \"ALTER TABLE comments ADD COLUMN corrected BOOLEAN NOT NULL DEFAULT 0\"\n    ))\n    db.session.commit()\n");
source("app.py", "_colonne_mot_de_passe", "python", "def _colonne_mot_de_passe():\n    \"\"\"Ajoute le drapeau de premier mot de passe aux bases déjà créées.\n\n    Les comptes déjà là ne sont pas forcés : ils ont déjà un mot de passe en usage.\n    Les nouveaux comptes, eux, doivent le changer à la première connexion.\n    \"\"\"\n    if db.engine.url.get_backend_name() != \"sqlite\":\n        return\n    lignes = db.session.execute(text(\"PRAGMA table_info(users)\")).all()\n    if not lignes or any(ligne[1] == \"must_change_password\" for ligne in lignes):\n        return\n    db.session.execute(text(\n        \"ALTER TABLE users ADD COLUMN must_change_password BOOLEAN NOT NULL DEFAULT 0\"\n    ))\n    db.session.commit()\n");
source("app.py", "_noter_presence", "python", "def _noter_presence():\n    \"\"\"Dernière activité de la session, si la requête a déjà vérifié un jeton.\"\"\"\n    from flask_jwt_extended import get_jwt\n\n    from utils.presence import toucher_presence\n\n    try:\n        claims = get_jwt()\n    except Exception:\n        return\n    jti = claims.get(\"jti\") if claims else None\n    if not jti or request.endpoint in (\"static\", \"auth.static\"):\n        return\n    try:\n        toucher_presence(jti)\n    except Exception:\n        app.logger.exception(\"Suivi de présence impossible\")\n");
source("auth/routes.py", "_max_attempts", "python", "def _max_attempts():\n    \"\"\"Nombre d'échecs acceptés par identifiant sur 10 minutes. Réglable pour les tests.\"\"\"\n    import os\n\n    try:\n        return max(1, int(os.environ.get(\"LOGIN_MAX_ATTEMPTS\", \"8\")))\n    except ValueError:\n        return 8\n");
source("auth/routes.py", "_attempt_key", "python", "def _attempt_key(username):\n    return (username or \"\").strip().lower()[:80]\n");
source("auth/routes.py", "login_blocked", "python", "def login_blocked(username):\n    \"\"\"Vrai si cet identifiant a déjà trop échoué récemment.\n\n    On limite par identifiant, pas par adresse IP : derrière Nginx, toute\n    l'école peut partager la même IP, et un plafond global bloquerait tout le monde.\n    \"\"\"\n    now = time.time()\n    key = _attempt_key(username)\n    with _ATTEMPTS_LOCK:\n        recent = [moment for moment in _ATTEMPTS.get(key, []) if now - moment < _WINDOW_SECONDS]\n        _ATTEMPTS[key] = recent\n        return len(recent) >= _max_attempts()\n");
source("auth/routes.py", "login_failed", "python", "def login_failed(username):\n    \"\"\"Mémorise un échec de mot de passe.\"\"\"\n    key = _attempt_key(username)\n    with _ATTEMPTS_LOCK:\n        _ATTEMPTS.setdefault(key, []).append(time.time())\n");
source("auth/routes.py", "login_succeeded", "python", "def login_succeeded(username):\n    \"\"\"Oublie les échecs après une connexion valide.\"\"\"\n    with _ATTEMPTS_LOCK:\n        _ATTEMPTS.pop(_attempt_key(username), None)\n");
source("auth/routes.py", "etat_tentatives", "python", "def etat_tentatives():\n    \"\"\"Identifiants encore suivis, et ceux qui ont atteint le plafond.\"\"\"\n    now = time.time()\n    plafond = _max_attempts()\n    bloques = []\n    suivis = 0\n    with _ATTEMPTS_LOCK:\n        for key, moments in _ATTEMPTS.items():\n            recents = [moment for moment in moments if now - moment < _WINDOW_SECONDS]\n            if not recents:\n                continue\n            suivis += 1\n            if len(recents) >= plafond:\n                bloques.append(key)\n    bloques.sort()\n    return {\"bloques\": bloques, \"suivis\": suivis}\n");
source("auth/routes.py", "login", "python", "@auth_bp.route(\"/login\", methods=[\"POST\"])\ndef login():\n    \"\"\"Vérifie l'identifiant et pose le cookie de session.\"\"\"\n    data = request.get_json(silent=True) or {}\n    if not isinstance(data, dict):\n        return jsonify({\"error\": \"Un objet JSON est requis\"}), 400\n\n    username = data.get(\"username\")\n    password = data.get(\"password\")\n    if not isinstance(username, str) or not isinstance(password, str):\n        return jsonify({\"error\": \"Identifiant ou mot de passe incorrect\"}), 401\n\n    username = username.strip()\n    # Un mot de passe énorme sert surtout à ralentir le serveur. On le refuse tôt.\n    if not username or len(username) > 80 or not password or len(password) > 200:\n        return jsonify({\"error\": \"Identifiant ou mot de passe incorrect\"}), 401\n\n    if login_blocked(username):\n        return jsonify({\"error\": \"Trop de tentatives. Réessaie dans quelques minutes.\"}), 429\n\n    user = User.query.filter_by(username=username).first()\n    password_ok = check_password_hash(user.password if user else _DUMMY_HASH, password)\n    if user is None or not password_ok:\n        login_failed(username)\n        return jsonify({\"error\": \"Identifiant ou mot de passe incorrect\"}), 401\n\n    if user.is_ban:\n        return jsonify({\"error\": \"Compte suspendu\"}), 403\n\n    if lire_etat()[\"suspended\"] and user.role != \"owner\":\n        return jsonify({\"error\": \"Le site est suspendu.\"}), 503\n\n    login_succeeded(username)\n    token = create_access_token(identity=user.id)\n    agent = request.headers.get(\"User-Agent\") or \"\"\n    ouvrir_presence(user.id, token, agent)\n    accueil = \"/auth/mot-de-passe\" if user.must_change_password else home_for_role(user.role)\n    response = jsonify({\n        \"message\": \"Connexion réussie\",\n        \"role\": user.role,\n        \"username\": user.username,\n        \"home\": accueil,\n        \"must_change_password\": bool(user.must_change_password),\n    })\n    set_access_cookies(response, token)\n    return response, 200\n");
source("auth/routes.py", "me", "python", "@auth_bp.route(\"/me\", methods=[\"GET\"])\n@jwt_required()\ndef me():\n    \"\"\"Identité du compte connecté, pour construire le menu.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return jsonify(public_profile(user)), 200\n");
source("auth/routes.py", "login_page", "python", "@auth_bp.route(\"/login-page\", methods=[\"GET\"])\ndef login_page():\n    \"\"\"Formulaire de connexion. Le paramètre next est nettoyé avant d'être renvoyé au script.\"\"\"\n    next_url = safe_next_url(request.args.get(\"next\"), \"/accueil\")\n    return render_template(\n        \"login/login.html\",\n        next_url=next_url,\n        site_suspendu=lire_etat()[\"suspended\"],\n    )\n");
source("auth/routes.py", "logout_page", "python", "@auth_bp.route(\"/logout-page\", methods=[\"GET\"])\n@jwt_required()\ndef logout_page():\n    \"\"\"Page de confirmation avant de quitter la session.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return render_template(\n        \"logout/logout.html\",\n        user=public_profile(user),\n        retour=home_for_role(user.role),\n    )\n");
source("auth/routes.py", "_refus_mot_de_passe", "python", "def _refus_mot_de_passe(user, actuel, nouveau, confirmation):\n    \"\"\"None si le nouveau mot de passe peut remplacer l'ancien.\"\"\"\n    if not isinstance(actuel, str) or not isinstance(nouveau, str) or not isinstance(confirmation, str):\n        return \"Indique le mot de passe actuel et le nouveau.\", 400\n    if len(actuel) > 200 or len(nouveau) > 200 or \"\\x00\" in nouveau:\n        return \"Mot de passe invalide.\", 400\n    if login_blocked(user.username):\n        return \"Trop de tentatives. Réessaie dans quelques minutes.\", 429\n    if not check_password_hash(user.password, actuel):\n        login_failed(user.username)\n        return \"Mot de passe actuel incorrect.\", 401\n    if nouveau != confirmation:\n        return \"Les deux nouveaux mots de passe ne sont pas identiques.\", 400\n    if len(nouveau) < 10:\n        return \"Le nouveau mot de passe doit faire au moins 10 caractères.\", 400\n    if nouveau == actuel:\n        return \"Choisis un mot de passe différent de l'actuel.\", 400\n    if nouveau.casefold() == user.username.casefold():\n        return \"Le mot de passe ne peut pas être l'identifiant.\", 400\n    return None\n");
source("auth/routes.py", "mot_de_passe_page", "python", "@auth_bp.route(\"/mot-de-passe\", methods=[\"GET\"])\n@jwt_required()\ndef mot_de_passe_page():\n    \"\"\"Formulaire : obligatoire à la première connexion, disponible ensuite à tout moment.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return render_template(\n        \"mot-de-passe/mot-de-passe.html\",\n        obligatoire=bool(user.must_change_password),\n        retour=home_for_role(user.role),\n    )\n");
source("auth/routes.py", "changer_mot_de_passe", "python", "@auth_bp.route(\"/mot-de-passe\", methods=[\"POST\"])\n@jwt_required()\ndef changer_mot_de_passe():\n    \"\"\"Remplace le mot de passe après vérification de l'ancien.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    data = request.get_json(silent=True)\n    if not isinstance(data, dict):\n        return jsonify({\"error\": \"Un objet JSON est requis\"}), 400\n    refus = _refus_mot_de_passe(\n        user,\n        data.get(\"actuel\"),\n        data.get(\"nouveau\"),\n        data.get(\"confirmation\"),\n    )\n    if refus:\n        message, code = refus\n        return jsonify({\"error\": message}), code\n    user.password = generate_password_hash(data.get(\"nouveau\"))\n    user.must_change_password = False\n    db.session.commit()\n    login_succeeded(user.username)\n    return jsonify({\n        \"message\": \"Mot de passe mis à jour\",\n        \"home\": home_for_role(user.role),\n        \"must_change_password\": False,\n    }), 200\n");
source("auth/routes.py", "logout", "python", "@auth_bp.route(\"/logout\", methods=[\"POST\"])\n@jwt_required()\ndef logout():\n    \"\"\"Efface les cookies du jeton et du CSRF, et ferme la session suivie.\"\"\"\n    get_jwt_identity()\n    try:\n        fermer_presence(get_jwt().get(\"jti\"))\n    except Exception:\n        current_app.logger.exception(\"Fermeture de session impossible\")\n    response = jsonify({\"message\": \"Déconnexion réussie\"})\n    unset_jwt_cookies(response)\n    return response, 200\n");
source("database/model.py", "generate_uuid", "python", "def generate_uuid():\n    \"\"\"Identifiant de compte, distinct de l'identifiant d'une fiche.\"\"\"\n    return str(uuid.uuid4())\n");
source("database/model.py", "User", "python", "class User(db.Model):\n    \"\"\"Un élève, un modérateur, un administrateur ou le propriétaire.\"\"\"\n\n    __tablename__ = \"users\"\n\n    id = db.Column(db.String(36), primary_key=True, default=generate_uuid)\n    name = db.Column(db.String(100), nullable=False)\n    surname = db.Column(db.String(100), nullable=False)\n    username = db.Column(db.String(80), unique=True, nullable=False)\n    # Hash Werkzeug, jamais le mot de passe en clair.\n    password = db.Column(db.String(200), nullable=False)\n    # user, moderator, admin ou owner. La valeur est relue à chaque requête.\n    # Un index unique empêche d'enregistrer deux propriétaires.\n    role = db.Column(db.String(20), nullable=False, default=\"user\")\n    is_ban = db.Column(db.Boolean, nullable=False, default=False)\n    # Vrai tant que le compte n'a pas choisi son mot de passe lui-même.\n    must_change_password = db.Column(db.Boolean, nullable=False, default=True)\n    # Listes JSON : SQLAlchemy appelle list() et dict() pour chaque nouvelle ligne.\n    download_ids = db.Column(db.JSON, nullable=True, default=list)\n    download_metadatas = db.Column(db.JSON, nullable=True, default=dict)\n    uploaded_files = db.Column(db.JSON, nullable=True, default=list)\n    uploaded_metadatas = db.Column(db.JSON, nullable=True, default=dict)\n    created_at = db.Column(db.DateTime, server_default=db.func.now())\n    updated_at = db.Column(db.DateTime, server_default=db.func.now(), onupdate=db.func.now())\n\n    def __repr__(self):\n        return f\"<User {self.username}>\"\n");
source("database/model.py", "__repr__", "python", "    def __repr__(self):\n        return f\"<User {self.username}>\"\n");
source("database/model.py", "Presence", "python", "class Presence(db.Model):\n    \"\"\"Session ouverte : un jeton émis à la connexion, jusqu'à expiration ou déconnexion.\n\n    Sert à l'audit du propriétaire. Le jti est celui du JWT, pas un second secret.\n    \"\"\"\n\n    __tablename__ = \"presences\"\n\n    jti = db.Column(db.String(36), primary_key=True)\n    user_id = db.Column(db.String(36), nullable=False, index=True)\n    created_at = db.Column(db.DateTime, nullable=False)\n    last_seen = db.Column(db.DateTime, nullable=False)\n    expires_at = db.Column(db.DateTime, nullable=False, index=True)\n    user_agent = db.Column(db.String(240), nullable=False, default=\"\")\n    revoked = db.Column(db.Boolean, nullable=False, default=False)\n");
source("database/model.py", "Star", "python", "class Star(db.Model):\n    \"\"\"Une étoile d'un compte sur une fiche. Une seule par couple compte/fiche.\"\"\"\n\n    __tablename__ = \"stars\"\n    __table_args__ = (\n        db.UniqueConstraint(\"user_id\", \"file_id\", name=\"uq_etoile_compte_fiche\"),\n    )\n\n    id = db.Column(db.String(36), primary_key=True, default=generate_uuid)\n    user_id = db.Column(db.String(36), nullable=False, index=True)\n    file_id = db.Column(db.String(36), nullable=False, index=True)\n    created_at = db.Column(db.DateTime, nullable=False)\n");
source("database/model.py", "Comment", "python", "class Comment(db.Model):\n    \"\"\"Retour sur une fiche.\n\n    audience : auteur (tous les élèves), equipe (modération), les_deux.\n    status : ouvert, puis pris par une seule personne, puis valide.\n    \"\"\"\n\n    __tablename__ = \"comments\"\n    __table_args__ = (\n        db.CheckConstraint(\n            \"audience IN ('auteur', 'equipe', 'les_deux')\",\n            name=\"ck_commentaire_audience\",\n        ),\n        db.CheckConstraint(\n            \"status IN ('ouvert', 'pris', 'valide')\",\n            name=\"ck_commentaire_statut\",\n        ),\n    )\n\n    id = db.Column(db.String(36), primary_key=True, default=generate_uuid)\n    file_id = db.Column(db.String(36), nullable=False, index=True)\n    author_id = db.Column(db.String(36), nullable=False, index=True)\n    audience = db.Column(db.String(20), nullable=False)\n    body = db.Column(db.String(2000), nullable=False)\n    status = db.Column(db.String(20), nullable=False, default=\"ouvert\")\n    handler_id = db.Column(db.String(36), nullable=True, index=True)\n    # Vrai quand la personne qui suit le commentaire a ensuite modifié la fiche.\n    corrected = db.Column(db.Boolean, nullable=False, default=False)\n    created_at = db.Column(db.DateTime, nullable=False)\n    updated_at = db.Column(db.DateTime, nullable=False)\n");
source("fiches/routes.py", "_connecte", "python", "def _connecte():\n    return require_user()\n");
source("fiches/routes.py", "_id_invalide", "python", "def _id_invalide(file_id):\n    if is_uuid(file_id):\n        return None\n    return jsonify({\"error\": \"Identifiant de fiche invalide\"}), 400\n");
source("fiches/routes.py", "_reponse", "python", "def _reponse(resultat, erreur, code=200):\n    if erreur:\n        return jsonify({\"error\": erreur[0]}), erreur[1]\n    return jsonify(resultat), code\n");
source("fiches/routes.py", "etoile", "python", "@fiches_bp.route(\"/<file_id>/etoile\", methods=[\"POST\"])\n@jwt_required()\ndef etoile(file_id):\n    \"\"\"Pose l'étoile de ce compte, ou la retire si elle était déjà posée.\"\"\"\n    user, error = _connecte()\n    if error:\n        return error\n    invalide = _id_invalide(file_id)\n    if invalide:\n        return invalide\n    return _reponse(*basculer(user, file_id))\n");
source("fiches/routes.py", "commentaires", "python", "@fiches_bp.route(\"/<file_id>/commentaires\", methods=[\"GET\"])\n@jwt_required()\ndef commentaires(file_id):\n    \"\"\"Commentaires de cette fiche que le compte a le droit de lire.\"\"\"\n    user, error = _connecte()\n    if error:\n        return error\n    invalide = _id_invalide(file_id)\n    if invalide:\n        return invalide\n    return _reponse(*lister(user, file_id))\n");
source("fiches/routes.py", "ajouter_commentaire", "python", "@fiches_bp.route(\"/<file_id>/commentaires\", methods=[\"POST\"])\n@jwt_required()\ndef ajouter_commentaire(file_id):\n    \"\"\"Publie un commentaire. Le corps est {\"texte\", \"audience\"}.\"\"\"\n    user, error = _connecte()\n    if error:\n        return error\n    invalide = _id_invalide(file_id)\n    if invalide:\n        return invalide\n    if request.content_length is not None and request.content_length > 16_000:\n        return jsonify({\"error\": \"Commentaire trop volumineux\"}), 413\n    data = request.get_json(silent=True)\n    if not isinstance(data, dict):\n        return jsonify({\"error\": \"Un objet JSON est requis\"}), 400\n    resultat, erreur = publier(user, file_id, data.get(\"texte\"), data.get(\"audience\"))\n    return _reponse(resultat, erreur, 201)\n");
source("fiches/routes.py", "prendre_commentaire", "python", "@fiches_bp.route(\"/<file_id>/commentaires/<comment_id>/prendre\", methods=[\"POST\"])\n@jwt_required()\ndef prendre_commentaire(file_id, comment_id):\n    \"\"\"Le premier membre de l'équipe qui appelle cette adresse s'en charge.\"\"\"\n    user, error = _connecte()\n    if error:\n        return error\n    invalide = _id_invalide(file_id)\n    if invalide:\n        return invalide\n    return _reponse(*prendre(user, file_id, comment_id))\n");
source("fiches/routes.py", "valider_commentaire", "python", "@fiches_bp.route(\"/<file_id>/commentaires/<comment_id>/valider\", methods=[\"POST\"])\n@jwt_required()\ndef valider_commentaire(file_id, comment_id):\n    \"\"\"Marque le commentaire comme traité. Réservé à celui qui s'en charge.\"\"\"\n    user, error = _connecte()\n    if error:\n        return error\n    invalide = _id_invalide(file_id)\n    if invalide:\n        return invalide\n    return _reponse(*valider(user, file_id, comment_id))\n");
source("fiches/routes.py", "retirer_commentaire", "python", "@fiches_bp.route(\"/<file_id>/commentaires/<comment_id>\", methods=[\"DELETE\"])\n@jwt_required()\ndef retirer_commentaire(file_id, comment_id):\n    \"\"\"Retire un commentaire suivi, après une modification de la fiche par le même compte.\"\"\"\n    user, error = _connecte()\n    if error:\n        return error\n    invalide = _id_invalide(file_id)\n    if invalide:\n        return invalide\n    return _reponse(*retirer(user, file_id, comment_id))\n");
source("info/routes.py", "get_matiere", "python", "@info_bp.route(\"/matiere\", methods=[\"GET\"])\ndef get_matiere():\n    \"\"\"Liste des matières présentes sur le disque.\"\"\"\n    return {\"matiere\": list_names(project_dir(\"matiere\"), \"dir\")}, 200\n");
source("info/routes.py", "get_classe", "python", "@info_bp.route(\"/classe/<matiere>\", methods=[\"GET\"])\ndef get_classe(matiere):\n    \"\"\"Classes disponibles pour une matière.\"\"\"\n    subject_dir = child_dir(project_dir(\"matiere\"), matiere)\n    if subject_dir is None:\n        return {\"error\": \"Matière introuvable\"}, 404\n\n    classes = list_names(subject_dir, \"dir\")\n    classes.sort(key=lambda name: (CLASS_ORDER.get(name, 99), name))\n    return {\"classe\": classes}, 200\n");
source("info/routes.py", "get_specialite", "python", "@info_bp.route(\"/specialite/<matiere>/<classe>\", methods=[\"GET\"])\ndef get_specialite(matiere, classe):\n    \"\"\"Spécialités disponibles pour une matière et une classe.\"\"\"\n    subject_dir = child_dir(project_dir(\"matiere\"), matiere)\n    if subject_dir is None:\n        return {\"error\": \"Matière introuvable\"}, 404\n\n    class_dir = child_dir(subject_dir, classe)\n    if class_dir is None:\n        return {\"error\": \"Classe introuvable\"}, 404\n\n    return {\"specialite\": list_names(class_dir, \"dir\")}, 200\n");
source("info/routes.py", "recherche", "python", "@info_bp.route(\"/recherche\", methods=[\"GET\"])\ndef recherche():\n    \"\"\"Fiches qui correspondent à tous les critères renseignés.\"\"\"\n    resultat, erreur = chercher_fiches(request.args, optional_user())\n    if erreur:\n        return {\"error\": erreur[0]}, erreur[1]\n    return resultat, 200\n");
source("info/routes.py", "get_files", "python", "@info_bp.route(\"/files/<matiere>/<classe>/<specialite>\", methods=[\"GET\"])\ndef get_files(matiere, classe, specialite):\n    \"\"\"Descriptifs des fiches d'un cours. Le téléchargement passe par /download.\"\"\"\n    subject_dir = child_dir(project_dir(\"matiere\"), matiere)\n    if subject_dir is None:\n        return {\"error\": \"Matière introuvable\"}, 404\n\n    class_dir = child_dir(subject_dir, classe)\n    if class_dir is None:\n        return {\"error\": \"Classe introuvable\"}, 404\n\n    speciality_dir = child_dir(class_dir, specialite)\n    if speciality_dir is None:\n        return {\"error\": \"Spécialité introuvable\"}, 404\n\n    file_ids = []\n    metadata_list = []\n    for filename in list_names(speciality_dir, \"file\"):\n        if not filename.endswith(\".json\"):\n            continue\n        file_id = filename[: -len(\".json\")]\n        if not is_uuid(file_id):\n            continue\n        metadata = read_metadata(speciality_dir / filename)\n        if metadata is None or metadata.get(\"id\") != file_id:\n            continue\n        # On ignore un JSON dont la catégorie ne correspond pas au dossier où il se trouve.\n        if (\n            metadata.get(\"matiere\") != matiere\n            or metadata.get(\"classe\") != classe\n            or metadata.get(\"specialite\") != specialite\n        ):\n            continue\n        file_ids.append(file_id)\n        # Même forme qu'avant : l'objet complet, pour les pages qui lisent title, author, desc, id.\n        raw = load_json_object(speciality_dir / filename)\n        metadata_list.append(dict(raw) if raw is not None else public_metadata(metadata))\n\n    annoter(metadata_list, optional_user())\n    return {\"files\": file_ids, \"metadata\": metadata_list}, 200\n");
source("init_users.py", "assurer_compte", "python", "def assurer_compte(compte):\n    \"\"\"Crée le compte ou réinitialise son rôle, son mot de passe et son état.\"\"\"\n    # Un seul propriétaire : les autres comptes owner redeviennent administrateurs\n    # avant d'enregistrer celui-ci, sinon l'index unique refuse l'écriture.\n    if compte[\"role\"] == \"owner\":\n        autres = User.query.filter(\n            User.role == \"owner\",\n            User.username != compte[\"username\"],\n        ).all()\n        for autre in autres:\n            autre.role = \"admin\"\n\n    utilisateur = User.query.filter_by(username=compte[\"username\"]).first()\n    cree = utilisateur is None\n    if cree:\n        utilisateur = User(\n            name=compte[\"name\"],\n            surname=compte[\"surname\"],\n            username=compte[\"username\"],\n            password=generate_password_hash(compte[\"password\"]),\n            role=compte[\"role\"],\n            is_ban=False,\n            download_ids=[],\n            download_metadatas={},\n            uploaded_files=[],\n            uploaded_metadatas={},\n            must_change_password=True,\n        )\n        db.session.add(utilisateur)\n    else:\n        utilisateur.name = compte[\"name\"]\n        utilisateur.surname = compte[\"surname\"]\n        utilisateur.password = generate_password_hash(compte[\"password\"])\n        utilisateur.role = compte[\"role\"]\n        utilisateur.is_ban = False\n        utilisateur.must_change_password = True\n    return \"créé\" if cree else \"mis à jour\"\n");
source("init_users.py", "main", "python", "def main():\n    with app.app_context():\n        db.create_all()\n        lignes = [(assurer_compte(compte), compte) for compte in COMPTES]\n        db.session.commit()\n\n    print(\"Comptes de test prêts.\")\n    print(\"Identifiant          Mot de passe       Rôle\")\n    for etat, compte in lignes:\n        print(\n            f\"{compte['username']:<20} {compte['password']:<18} {compte['role']:<12} ({etat})\"\n        )\n");
source("make_structure.py", "make_structure", "python", "def make_structure(structure):\n    \"\"\"Crée l'arborescence à partir de la structure par classe.\n\n    L'ordre des dossiers est matiere / matière / classe / spécialité,\n    le même que celui lu par les routes /info et /upload.\n    \"\"\"\n\n    for classe, matieres in structure.items():\n        for matiere, specialites in matieres.items():\n            for specialite in specialites:\n                # exist_ok : relancer le script n'efface pas les fiches déjà déposées.\n                chemin = os.path.join(\"matiere\", matiere, classe, specialite)\n                os.makedirs(chemin, exist_ok=True)\n");
source("make_structure.py", "main", "python", "def main():\n    make_structure(STRUCTURE)\n    os.makedirs(\"uploads\", exist_ok=True)\n");
source("moderator/routes.py", "_staff_only", "python", "def _staff_only():\n    \"\"\"Compte connecté : modérateur, administrateur ou propriétaire.\"\"\"\n    user, error = require_user()\n    if error:\n        return None, error\n    refused = require_roles(user, (\"admin\", \"moderator\", \"owner\"))\n    if refused:\n        return None, refused\n    return user, None\n");
source("moderator/routes.py", "dashboard", "python", "@moderator_bp.route(\"/dashboard\", methods=[\"GET\"])\n@jwt_required()\ndef dashboard():\n    \"\"\"Page pour parcourir les cours et modérer les fiches.\"\"\"\n    user, error = _staff_only()\n    if error:\n        return error\n    return render_template(\n        \"staff_dashboard.html\",\n        profil=public_profile(user),\n        prefix=\"/moderator\",\n        comptes_url=\"/moderator/comptes-page\",\n        titre=\"Espace modération\",\n    )\n");
source("moderator/routes.py", "comptes_page", "python", "@moderator_bp.route(\"/comptes-page\", methods=[\"GET\"])\n@jwt_required()\ndef comptes_page():\n    \"\"\"Liste des comptes. La suspension d'un élève est la seule action proposée.\"\"\"\n    user, error = _staff_only()\n    if error:\n        return error\n    return render_template(\n        \"comptes.html\",\n        profil=public_profile(user),\n        comptes=list_profiles(),\n        prefix=\"/moderator\",\n        peut_roles=False,\n        titre=\"Comptes\",\n    )\n");
source("moderator/routes.py", "recherche_comptes", "python", "@moderator_bp.route(\"/comptes/recherche\", methods=[\"GET\"])\n@jwt_required()\ndef recherche_comptes():\n    \"\"\"Comptes selon le nom, le rôle ou l'état. Un élève reçoit un refus.\"\"\"\n    _user, error = _staff_only()\n    if error:\n        return error\n    resultat, erreur = chercher_comptes(request.args)\n    if erreur:\n        return jsonify({\"error\": erreur[0]}), erreur[1]\n    return jsonify(resultat), 200\n");
source("moderator/routes.py", "modify_file", "python", "@moderator_bp.route(\"/dashboard/modify/<file_id>\", methods=[\"GET\"])\n@jwt_required()\ndef modify_file(file_id):\n    \"\"\"Formulaire de modification d'une fiche.\"\"\"\n    _user, error = _staff_only()\n    if error:\n        return error\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    metadata = read_metadata(find_metadata_path(file_id))\n    if metadata is None:\n        return error_response(\"Fiche introuvable\", 404)\n    return render_template(\n        \"modifier.html\",\n        metadata=public_metadata(metadata),\n        save_url=f\"/moderator/dashboard/modify/save/{file_id}\",\n        retour_url=\"/moderator/dashboard\",\n        titre=\"Modérer une fiche\",\n    )\n");
source("moderator/routes.py", "save_modified_file", "python", "@moderator_bp.route(\"/dashboard/modify/save/<file_id>\", methods=[\"POST\"])\n@jwt_required()\ndef save_modified_file(file_id):\n    \"\"\"Enregistre la modération sans changer l'auteur.\"\"\"\n    _user, error = _staff_only()\n    if error:\n        return error\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    return update_file(owner, file_id, request.form, request.files.get(\"file\"), acteur=_user)\n");
source("moderator/routes.py", "delete_file", "python", "@moderator_bp.route(\"/dashboard/delete/<file_id>\", methods=[\"DELETE\"])\n@jwt_required()\ndef delete_file(file_id):\n    \"\"\"Supprime une fiche.\"\"\"\n    _user, error = _staff_only()\n    if error:\n        return error\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    return remove_file(owner, file_id)\n");
source("moderator/routes.py", "ban_user", "python", "@moderator_bp.route(\"/dashboard/ban/<user_id>\", methods=[\"POST\"])\n@jwt_required()\ndef ban_user(user_id):\n    \"\"\"Suspend un élève. Un modérateur ou un administrateur est protégé.\"\"\"\n    user, error = _staff_only()\n    if error:\n        return error\n    return set_ban(user, user_id, True)\n");
source("moderator/routes.py", "unban_user", "python", "@moderator_bp.route(\"/dashboard/unban/<user_id>\", methods=[\"POST\"])\n@jwt_required()\ndef unban_user(user_id):\n    \"\"\"Réactive un élève.\"\"\"\n    user, error = _staff_only()\n    if error:\n        return error\n    return set_ban(user, user_id, False)\n");
source("owner/routes.py", "_owner_only", "python", "def _owner_only():\n    user, error = require_user()\n    if error:\n        return None, error\n    refused = require_roles(user, (\"owner\",))\n    if refused:\n        return None, refused\n    return user, None\n");
source("owner/routes.py", "audit_page", "python", "@owner_bp.route(\"/audit\", methods=[\"GET\"])\n@jwt_required()\ndef audit_page():\n    \"\"\"Page d'audit. Les chiffres sont aussi dans la réponse, pour le premier affichage.\"\"\"\n    user, error = _owner_only()\n    if error:\n        return error\n    return render_template(\n        \"audit.html\",\n        profil=public_profile(user),\n        audit=collecter_audit(),\n        titre=\"Audit du site\",\n    )\n");
source("owner/routes.py", "audit_json", "python", "@owner_bp.route(\"/audit.json\", methods=[\"GET\"])\n@jwt_required()\ndef audit_json():\n    \"\"\"Même relevé, pour actualiser la page sans la recharger.\"\"\"\n    _user, error = _owner_only()\n    if error:\n        return error\n    return jsonify(collecter_audit()), 200\n");
source("owner/routes.py", "basculer_site", "python", "@owner_bp.route(\"/site\", methods=[\"POST\"])\n@jwt_required()\ndef basculer_site():\n    \"\"\"Suspend ou réactive le site. Le corps est {\"suspendu\": true|false}.\"\"\"\n    user, error = _owner_only()\n    if error:\n        return error\n    data = request.get_json(silent=True)\n    if not isinstance(data, dict) or not isinstance(data.get(\"suspendu\"), bool):\n        return jsonify({\"error\": \"Indique suspendu avec true ou false.\"}), 400\n    definir_suspension(data[\"suspendu\"], user.username)\n    return jsonify(collecter_audit()), 200\n");
source("tests/test_flows.py", "verifier", "python", "def verifier(condition, message):\n    if not condition:\n        raise AssertionError(message)\n");
source("tests/test_flows.py", "suivre", "python", "def suivre(chemin):\n    RESIDUS.append(Path(chemin))\n");
source("tests/test_flows.py", "nettoyer", "python", "def nettoyer():\n    for chemin in RESIDUS:\n        if chemin.is_file():\n            chemin.unlink()\n    if os.path.exists(_BASE.name):\n        os.remove(_BASE.name)\n    for chemin in (Path(_ETAT.name), Path(_ETAT.name).with_suffix(\".tmp\")):\n        if chemin.is_file():\n            chemin.unlink()\n");
source("tests/test_flows.py", "csrf", "python", "def csrf(client):\n    cookie = client.get_cookie(\"csrf_access_token\")\n    verifier(cookie is not None, \"le cookie CSRF est absent après la connexion\")\n    return {\"X-CSRF-TOKEN\": cookie.value, \"Accept\": \"application/json\"}\n");
source("tests/test_flows.py", "connecter", "python", "def connecter(client, username, password):\n    reponse = client.post(\"/auth/login\", json={\"username\": username, \"password\": password})\n    verifier(reponse.status_code == 200, f\"connexion {username} : {reponse.get_json()}\")\n    return csrf(client)\n");
source("tests/test_flows.py", "creer_compte", "python", "def creer_compte(username, role):\n    compte = User(\n        name=\"Test\",\n        surname=role,\n        username=username,\n        password=generate_password_hash(\"MotDePasse-Test-9\"),\n        role=role,\n        is_ban=False,\n        download_ids=[],\n        download_metadatas={},\n        uploaded_files=[],\n        uploaded_metadatas={},\n        must_change_password=False,\n    )\n    db.session.add(compte)\n    db.session.commit()\n    return compte\n");
source("tests/test_flows.py", "verifier_social", "python", "def verifier_social(client_owner):\n    \"\"\"Étoiles, commentaires, recherches et audit personnel.\n\n    client_owner est déjà le propriétaire. Les autres comptes passent\n    par leurs propres clients pour ne pas fermer sa session.\n    \"\"\"\n    from sqlalchemy.exc import IntegrityError\n\n    from database.model import Comment, Star\n\n    eleve = app.test_client()\n    eleve2 = app.test_client()\n    modo = app.test_client()\n    admin = app.test_client()\n    anonyme = app.test_client()\n    entete_eleve = connecter(eleve, \"eleve\", \"MotDePasse-Test-9\")\n    entete_eleve2 = connecter(eleve2, \"eleve2\", \"MotDePasse-Test-9\")\n    entete_modo = connecter(modo, \"moderateur\", \"MotDePasse-Test-9\")\n    entete_admin = connecter(admin, \"admin\", \"MotDePasse-Test-9\")\n\n    envoi = eleve.post(\n        \"/upload/Mathematiques/1ere/specialite\",\n        data={\n            \"title\": \"Synthese etoilee\",\n            \"desc\": \"Description assez longue pour la recherche\",\n            \"file\": (io.BytesIO(b\"contenu etoile\"), \"synthese.txt\"),\n        },\n        headers=entete_eleve,\n    )\n    verifier(envoi.status_code == 201, f\"fiche sociale refusée : {envoi.get_json()}\")\n    meta = envoi.get_json()[\"metadata\"]\n    file_id = meta[\"id\"]\n    suivre(Path(\"matiere/Mathematiques/1ere/specialite\") / f\"{file_id}.json\")\n    suivre(Path(\"uploads\") / meta[\"filename\"])\n\n    anonyme_etoile = anonyme.post(f\"/fiches/{file_id}/etoile\")\n    verifier(anonyme_etoile.status_code == 401, \"une étoile anonyme a été acceptée\")\n\n    pose = eleve.post(f\"/fiches/{file_id}/etoile\", headers=entete_eleve)\n    verifier(pose.status_code == 200 and pose.get_json()[\"etoile\"] is True, pose.get_json())\n    verifier(pose.get_json()[\"etoiles\"] == 1, \"le compteur d'étoiles est faux\")\n    retire = eleve.post(f\"/fiches/{file_id}/etoile\", headers=entete_eleve)\n    verifier(retire.get_json()[\"etoile\"] is False and retire.get_json()[\"etoiles\"] == 0, retire.get_json())\n    eleve.post(f\"/fiches/{file_id}/etoile\", headers=entete_eleve)\n    deuxieme = eleve2.post(f\"/fiches/{file_id}/etoile\", headers=entete_eleve2)\n    verifier(deuxieme.status_code == 200 and deuxieme.get_json()[\"etoiles\"] == 2, deuxieme.get_json())\n\n    liste = eleve.get(\"/info/files/Mathematiques/1ere/specialite\")\n    fiche_liste = next(item for item in liste.get_json()[\"metadata\"] if item[\"id\"] == file_id)\n    verifier(fiche_liste[\"etoiles\"] == 2 and fiche_liste[\"etoile_moi\"] is True, fiche_liste)\n    publique = anonyme.get(\"/info/files/Mathematiques/1ere/specialite\")\n    fiche_publique = next(item for item in publique.get_json()[\"metadata\"] if item[\"id\"] == file_id)\n    verifier(fiche_publique[\"etoile_moi\"] is False, \"l'étoile d'un autre compte est révélée\")\n\n    vide = anonyme.get(\"/info/recherche\")\n    verifier(vide.status_code == 400, \"une recherche sans critère a répondu\")\n    piege = anonyme.get(\"/info/recherche\", query_string={\"matiere\": \"..\"})\n    verifier(piege.status_code == 400, \"une matière .. a été acceptée\")\n    joker = anonyme.get(\"/info/recherche\", query_string={\"q\": \"%\"})\n    verifier(joker.status_code == 200 and joker.get_json()[\"fiches\"] == [], \"le % a servi de joker\")\n    trouve = anonyme.get(\"/info/recherche\", query_string={\"q\": \"Synthese\", \"etoiles_min\": \"2\", \"auteur\": \"eleve\"})\n    verifier(trouve.status_code == 200, trouve.get_json())\n    verifier(any(item[\"id\"] == file_id for item in trouve.get_json()[\"fiches\"]), \"la fiche étoilée est introuvable\")\n    verifier(\"filename\" not in trouve.get_json()[\"fiches\"][0], \"le nom interne est dans la recherche\")\n    trop = anonyme.get(\"/info/recherche\", query_string={\"q\": \"Synthese\", \"etoiles_min\": \"9\"})\n    verifier(trop.get_json()[\"fiches\"] == [], \"le minimum d'étoiles est ignoré\")\n\n    comptes_eleve = eleve.get(\"/moderator/comptes/recherche\", query_string={\"q\": \"eleve\"})\n    verifier(comptes_eleve.status_code == 403, \"un élève recherche les comptes\")\n    comptes = modo.get(\"/moderator/comptes/recherche\", query_string={\"q\": \"eleve\"})\n    verifier(comptes.status_code == 200, comptes.get_json())\n    noms = [compte[\"username\"] for compte in comptes.get_json()[\"comptes\"]]\n    verifier(\"eleve\" in noms and \"eleve2\" in noms, noms)\n    verifier(all(\"password\" not in compte for compte in comptes.get_json()[\"comptes\"]), \"mot de passe exposé\")\n    pourcent = modo.get(\"/admin/comptes/recherche\", query_string={\"q\": \"%\"})\n    verifier(pourcent.status_code == 403, \"un modérateur utilise la recherche admin\")\n    pourcent_modo = modo.get(\"/moderator/comptes/recherche\", query_string={\"q\": \"%\"})\n    verifier(pourcent_modo.get_json()[\"comptes\"] == [], \"le % sélectionne tous les comptes\")\n    proprietaires = admin.get(\"/admin/comptes/recherche\", query_string={\"role\": \"owner\"})\n    verifier(\n        [compte[\"username\"] for compte in proprietaires.get_json()[\"comptes\"]] == [\"proprietaire\"],\n        proprietaires.get_json(),\n    )\n    role_inconnu = admin.get(\"/admin/comptes/recherche\", query_string={\"role\": \"owner' OR 1=1\"})\n    verifier(role_inconnu.status_code == 400, \"un rôle injecté a été accepté\")\n\n    script = \"<script>alert(1)</script>\"\n    prive = eleve2.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": script, \"audience\": \"auteur\"},\n        headers=entete_eleve2,\n    )\n    verifier(prive.status_code == 201, prive.get_json())\n    id_prive = prive.get_json()[\"commentaire\"][\"id\"]\n    vu_auteur = eleve.get(f\"/fiches/{file_id}/commentaires\", headers=entete_eleve)\n    verifier(any(item[\"id\"] == id_prive for item in vu_auteur.get_json()[\"commentaires\"]), \"l'auteur ne voit pas le retour\")\n    vu_modo = modo.get(f\"/fiches/{file_id}/commentaires\", headers=entete_modo)\n    verifier(all(item[\"id\"] != id_prive for item in vu_modo.get_json()[\"commentaires\"]), \"l'équipe voit un commentaire privé\")\n    prise_cachee = modo.post(\n        f\"/fiches/{file_id}/commentaires/{id_prive}/prendre\",\n        headers=entete_modo,\n    )\n    verifier(prise_cachee.status_code == 404, \"un commentaire privé se laisse réserver\")\n\n    with app.app_context():\n        creer_compte(\"eleve3\", \"user\")\n    tiers = app.test_client()\n    entete_tiers = connecter(tiers, \"eleve3\", \"MotDePasse-Test-9\")\n    sans_compte = anonyme.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"sans session\", \"audience\": \"auteur\"},\n    )\n    verifier(sans_compte.status_code == 401, \"un visiteur anonyme a commenté\")\n    ajout_tiers = tiers.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"Retour d un autre eleve\", \"audience\": \"auteur\"},\n        headers=entete_tiers,\n    )\n    verifier(ajout_tiers.status_code == 201, ajout_tiers.get_json())\n    id_tiers = ajout_tiers.get_json()[\"commentaire\"][\"id\"]\n    vu_tiers = tiers.get(f\"/fiches/{file_id}/commentaires\", headers=entete_tiers)\n    verifier(any(item[\"id\"] == id_prive for item in vu_tiers.get_json()[\"commentaires\"]), \"un autre élève ne voit pas le commentaire\")\n    verifier(any(item[\"id\"] == id_tiers for item in eleve.get(f\"/fiches/{file_id}/commentaires\", headers=entete_eleve).get_json()[\"commentaires\"]), \"l'auteur de la fiche ne voit pas le commentaire d'un autre élève\")\n    verifier(all(item[\"id\"] != id_tiers for item in modo.get(f\"/fiches/{file_id}/commentaires\", headers=entete_modo).get_json()[\"commentaires\"]), \"l'équipe voit un commentaire réservé aux utilisateurs\")\n\n    equipe = eleve2.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"Erreur a corriger par l equipe\", \"audience\": \"equipe\"},\n        headers=entete_eleve2,\n    )\n    verifier(equipe.status_code == 201, equipe.get_json())\n    id_equipe = equipe.get_json()[\"commentaire\"][\"id\"]\n    vu_eleve = eleve.get(f\"/fiches/{file_id}/commentaires\", headers=entete_eleve)\n    verifier(all(item[\"id\"] != id_equipe for item in vu_eleve.get_json()[\"commentaires\"]), \"l'auteur voit un commentaire d'équipe\")\n    verifier(\n        any(item[\"id\"] == id_equipe for item in modo.get(f\"/fiches/{file_id}/commentaires\", headers=entete_modo).get_json()[\"commentaires\"]),\n        \"le modérateur ne voit pas le commentaire d'équipe\",\n    )\n\n    partage = eleve2.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"Visible des deux cotes\", \"audience\": \"les_deux\"},\n        headers=entete_eleve2,\n    )\n    verifier(partage.status_code == 201, partage.get_json())\n    id_partage = partage.get_json()[\"commentaire\"][\"id\"]\n    vu_partage = tiers.get(f\"/fiches/{file_id}/commentaires\", headers=entete_tiers)\n    verifier(any(item[\"id\"] == id_partage for item in vu_partage.get_json()[\"commentaires\"]), \"un élève ne voit pas le commentaire partagé\")\n    verifier(all(item[\"id\"] != id_equipe for item in vu_partage.get_json()[\"commentaires\"]), \"un élève voit un commentaire d'équipe\")\n    eleve_prend = eleve2.post(\n        f\"/fiches/{file_id}/commentaires/{id_partage}/prendre\",\n        headers=entete_eleve2,\n    )\n    verifier(eleve_prend.status_code == 403, \"l'auteur du commentaire s'est réservé le suivi\")\n    pris = modo.post(\n        f\"/fiches/{file_id}/commentaires/{id_partage}/prendre\",\n        headers=entete_modo,\n    )\n    verifier(pris.status_code == 200 and pris.get_json()[\"commentaire\"][\"statut\"] == \"pris\", pris.get_json())\n    verifier(pris.get_json()[\"commentaire\"][\"responsable\"] == \"moderateur\", pris.get_json())\n    conflit = admin.post(\n        f\"/fiches/{file_id}/commentaires/{id_partage}/prendre\",\n        headers=entete_admin,\n    )\n    verifier(conflit.status_code == 409, f\"un second responsable a été accepté : {conflit.get_json()}\")\n    vol_validation = admin.post(\n        f\"/fiches/{file_id}/commentaires/{id_partage}/valider\",\n        headers=entete_admin,\n    )\n    verifier(vol_validation.status_code == 403, \"un autre membre a validé le commentaire\")\n    valide = modo.post(\n        f\"/fiches/{file_id}/commentaires/{id_partage}/valider\",\n        headers=entete_modo,\n    )\n    verifier(valide.status_code == 200 and valide.get_json()[\"commentaire\"][\"statut\"] == \"valide\", valide.get_json())\n\n    def enregistrer(client, entete, prefixe, titre):\n        return client.post(\n            f\"{prefixe}/dashboard/modify/save/{file_id}\",\n            data={\n                \"title\": titre,\n                \"desc\": \"Description corrigee apres suivi\",\n                \"matiere\": \"Mathematiques\",\n                \"classe\": \"1ere\",\n                \"specialite\": \"specialite\",\n            },\n            headers=entete,\n        )\n\n    a_retirer = eleve2.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"A retirer par l auteur\", \"audience\": \"auteur\"},\n        headers=entete_eleve2,\n    )\n    verifier(a_retirer.status_code == 201, a_retirer.get_json())\n    id_retrait = a_retirer.get_json()[\"commentaire\"][\"id\"]\n    suivi_eleve = eleve.post(\n        f\"/fiches/{file_id}/commentaires/{id_retrait}/prendre\",\n        headers=entete_eleve,\n    )\n    verifier(suivi_eleve.status_code == 200, suivi_eleve.get_json())\n    trop_tot = eleve.delete(f\"/fiches/{file_id}/commentaires/{id_retrait}\", headers=entete_eleve)\n    verifier(trop_tot.status_code == 403, \"le commentaire part avant la modification\")\n    correction = enregistrer(eleve, entete_eleve, \"/users\", \"Synthese etoilee\")\n    verifier(correction.status_code == 200, correction.get_json())\n    autre_eleve = eleve2.delete(f\"/fiches/{file_id}/commentaires/{id_retrait}\", headers=entete_eleve2)\n    verifier(autre_eleve.status_code == 403, \"un autre élève retire le commentaire\")\n    retire = eleve.delete(f\"/fiches/{file_id}/commentaires/{id_retrait}\", headers=entete_eleve)\n    verifier(retire.status_code == 200, retire.get_json())\n    encore = eleve.get(f\"/fiches/{file_id}/commentaires\", headers=entete_eleve)\n    verifier(all(item[\"id\"] != id_retrait for item in encore.get_json()[\"commentaires\"]), \"le commentaire retiré est encore listé\")\n\n    pour_modo = eleve2.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"A retirer par la moderation\", \"audience\": \"equipe\"},\n        headers=entete_eleve2,\n    )\n    verifier(pour_modo.status_code == 201, pour_modo.get_json())\n    id_modo = pour_modo.get_json()[\"commentaire\"][\"id\"]\n    verifier(modo.post(f\"/fiches/{file_id}/commentaires/{id_modo}/prendre\", headers=entete_modo).status_code == 200, \"le modérateur ne suit pas\")\n    verifier(\n        modo.delete(f\"/fiches/{file_id}/commentaires/{id_modo}\", headers=entete_modo).status_code == 403,\n        \"le modérateur retire avant d'avoir modifié\",\n    )\n    verifier(enregistrer(eleve, entete_eleve, \"/users\", \"Synthese etoilee\").status_code == 200, \"correction élève\")\n    verifier(\n        modo.delete(f\"/fiches/{file_id}/commentaires/{id_modo}\", headers=entete_modo).status_code == 403,\n        \"la modification d'un autre compte débloque le retrait\",\n    )\n    verifier(\n        admin.delete(f\"/fiches/{file_id}/commentaires/{id_modo}\", headers=entete_admin).status_code == 403,\n        \"un admin retire le commentaire suivi par le modérateur\",\n    )\n    correction_modo = enregistrer(modo, entete_modo, \"/moderator\", \"Synthese etoilee\")\n    verifier(correction_modo.status_code == 200, correction_modo.get_json())\n    verifier(modo.delete(f\"/fiches/{file_id}/commentaires/{id_modo}\", headers=entete_modo).status_code == 200, \"retrait modérateur\")\n\n    pour_owner = eleve2.post(\n        f\"/fiches/{file_id}/commentaires\",\n        json={\"texte\": \"A retirer par le proprietaire\", \"audience\": \"les_deux\"},\n        headers=entete_eleve2,\n    )\n    verifier(pour_owner.status_code == 201, pour_owner.get_json())\n    id_owner = pour_owner.get_json()[\"commentaire\"][\"id\"]\n    entete_owner = csrf(client_owner)\n    verifier(\n        client_owner.post(f\"/fiches/{file_id}/commentaires/{id_owner}/prendre\", headers=entete_owner).status_code == 200,\n        \"le propriétaire ne suit pas\",\n    )\n    verifier(\n        client_owner.delete(f\"/fiches/{file_id}/commentaires/{id_owner}\", headers=entete_owner).status_code == 403,\n        \"le propriétaire retire avant d'avoir modifié\",\n    )\n    correction_owner = enregistrer(client_owner, entete_owner, \"/admin\", \"Synthese etoilee\")\n    verifier(correction_owner.status_code == 200, correction_owner.get_json())\n    verifier(\n        client_owner.delete(f\"/fiches/{file_id}/commentaires/{id_owner}\", headers=entete_owner).status_code == 200,\n        \"retrait propriétaire\",\n    )\n\n    audit_eleve = eleve.get(\"/users/audit\", headers={\"Accept\": \"text/html\"})\n    page_eleve = audit_eleve.get_data(as_text=True)\n    verifier(audit_eleve.status_code == 200 and \"Synthese etoilee\" in page_eleve, \"audit personnel absent\")\n    verifier(\"<script>alert(1)</script>\" not in page_eleve, \"le commentaire n'est pas échappé\")\n    audit_autre = eleve2.get(\"/users/audit.json\")\n    verifier(\"Synthese etoilee\" not in audit_autre.get_data(as_text=True), \"l'audit d'un autre élève contient la fiche\")\n    audit_modo = modo.get(\"/users/audit.json\")\n    verifier(\"Synthese etoilee\" not in audit_modo.get_data(as_text=True), \"l'audit du modérateur mélange les fiches\")\n\n    classement = client_owner.get(\"/owner/audit.json\").get_json()[\"etoiles\"]\n    verifier(classement[\"plus_etoilee\"][\"id\"] == file_id, classement)\n    verifier(classement[\"plus_etoilee\"][\"etoiles\"] == 2, classement)\n    verifier(\n        any(groupe[\"matiere\"] == \"Mathematiques\" and groupe[\"fiches\"][0][\"id\"] == file_id for groupe in classement[\"par_matiere\"]),\n        classement,\n    )\n\n    with app.app_context():\n        try:\n            creer_compte(\"autre-proprio\", \"owner\")\n            raise AssertionError(\"un second propriétaire a été enregistré\")\n        except IntegrityError:\n            db.session.rollback()\n\n    suppression = eleve.delete(f\"/users/dashboard/delete/{file_id}\", headers=entete_eleve)\n    verifier(suppression.status_code == 200, suppression.get_json())\n    verifier(anonyme.get(f\"/download/Mathematiques/1ere/specialite/{file_id}\").status_code == 404, \"la fiche supprimée se télécharge\")\n    with app.app_context():\n        verifier(Star.query.filter_by(file_id=file_id).count() == 0, \"une étoile survit à la fiche\")\n        verifier(Comment.query.filter_by(file_id=file_id).count() == 0, \"un commentaire survit à la fiche\")\n\n    source = Path(\"static/common.js\").read_text(encoding=\"utf-8\")\n    verifier(\"window.location.reload()\" in source, \"la suppression ne recharge pas la page\")\n    script_install = Path(\"init-server.sh\").read_text(encoding=\"utf-8\")\n    for variable in (\"JWT_SECRET_KEY\", \"JWT_COOKIE_SECURE\", \"DATABASE_URI\", \"LOGIN_MAX_ATTEMPTS\", \"SITE_STATUS_PATH\"):\n        verifier(variable in script_install, f\"{variable} absent du script d'installation\")\n");
source("tests/test_flows.py", "enregistrer", "python", "    def enregistrer(client, entete, prefixe, titre):\n        return client.post(\n            f\"{prefixe}/dashboard/modify/save/{file_id}\",\n            data={\n                \"title\": titre,\n                \"desc\": \"Description corrigee apres suivi\",\n                \"matiere\": \"Mathematiques\",\n                \"classe\": \"1ere\",\n                \"specialite\": \"specialite\",\n            },\n            headers=entete,\n        )\n");
source("tests/test_flows.py", "verifier_mot_de_passe", "python", "def verifier_mot_de_passe():\n    \"\"\"Première connexion bloquée tant que le mot de passe n'est pas choisi, puis changement libre.\"\"\"\n    with app.app_context():\n        compte = creer_compte(\"nouveau\", \"user\")\n        compte.must_change_password = True\n        db.session.commit()\n\n    client = app.test_client()\n    entree = client.post(\"/auth/login\", json={\"username\": \"nouveau\", \"password\": \"MotDePasse-Test-9\"})\n    verifier(entree.status_code == 200, entree.get_json())\n    verifier(entree.get_json()[\"must_change_password\"] is True, entree.get_json())\n    verifier(entree.get_json()[\"home\"] == \"/auth/mot-de-passe\", entree.get_json())\n    entete = csrf(client)\n\n    ferme = client.get(\"/users/dashboard\", headers={\"Accept\": \"text/html\"})\n    verifier(ferme.status_code == 302 and ferme.location.endswith(\"/auth/mot-de-passe\"), ferme.location)\n    verifier(client.get(\"/info/matiere\").status_code == 403, \"les fiches restent ouvertes avant le nouveau mot de passe\")\n\n    page = client.get(\"/auth/mot-de-passe\")\n    verifier(page.status_code == 200 and \"première connexion\" in page.get_data(as_text=True), \"formulaire de premier mot de passe absent\")\n\n    sans_csrf = client.post(\n        \"/auth/mot-de-passe\",\n        json={\"actuel\": \"MotDePasse-Test-9\", \"nouveau\": \"Nouveau-Mot-2026\", \"confirmation\": \"Nouveau-Mot-2026\"},\n        headers={\"Accept\": \"application/json\"},\n    )\n    verifier(sans_csrf.status_code == 401, \"le changement sans CSRF a été accepté\")\n\n    court = client.post(\n        \"/auth/mot-de-passe\",\n        json={\"actuel\": \"MotDePasse-Test-9\", \"nouveau\": \"court\", \"confirmation\": \"court\"},\n        headers=entete,\n    )\n    verifier(court.status_code == 400, court.get_json())\n    different = client.post(\n        \"/auth/mot-de-passe\",\n        json={\"actuel\": \"MotDePasse-Test-9\", \"nouveau\": \"Nouveau-Mot-2026\", \"confirmation\": \"Autre-Chose-9\"},\n        headers=entete,\n    )\n    verifier(different.status_code == 400, different.get_json())\n    mauvais = client.post(\n        \"/auth/mot-de-passe\",\n        json={\"actuel\": \"pas-le-bon\", \"nouveau\": \"Nouveau-Mot-2026\", \"confirmation\": \"Nouveau-Mot-2026\"},\n        headers=entete,\n    )\n    verifier(mauvais.status_code == 401, mauvais.get_json())\n    ok = client.post(\n        \"/auth/mot-de-passe\",\n        json={\"actuel\": \"MotDePasse-Test-9\", \"nouveau\": \"Nouveau-Mot-2026\", \"confirmation\": \"Nouveau-Mot-2026\"},\n        headers=entete,\n    )\n    verifier(ok.status_code == 200 and ok.get_json()[\"must_change_password\"] is False, ok.get_json())\n    verifier(client.get(\"/info/matiere\").status_code == 200, \"le site reste fermé après le changement\")\n\n    volontaire = client.get(\"/auth/mot-de-passe\")\n    verifier(\"quand tu veux\" in volontaire.get_data(as_text=True), \"le changement volontaire manque\")\n    encore = client.post(\n        \"/auth/mot-de-passe\",\n        json={\"actuel\": \"Nouveau-Mot-2026\", \"nouveau\": \"Autre-Mot-2026!\", \"confirmation\": \"Autre-Mot-2026!\"},\n        headers=entete,\n    )\n    verifier(encore.status_code == 200, encore.get_json())\n    client.post(\"/auth/logout\", headers=entete)\n    retour = client.post(\"/auth/login\", json={\"username\": \"nouveau\", \"password\": \"Autre-Mot-2026!\"})\n    verifier(retour.status_code == 200 and retour.get_json()[\"must_change_password\"] is False, retour.get_json())\n    verifier(retour.get_json()[\"home\"] == \"/users/dashboard\", retour.get_json())\n");
source("tests/test_flows.py", "scenario", "python", "def scenario():\n    client = app.test_client()\n\n    accueil = client.get(\"/accueil\")\n    verifier(accueil.status_code == 200, \"l'accueil ne répond pas\")\n    verifier(\"Fiches de révision\" in accueil.get_data(as_text=True), \"titre d'accueil absent\")\n    verifier(\"Rechercher une fiche\" in accueil.get_data(as_text=True), \"la recherche de fiches manque à l'accueil\")\n\n    racine = client.get(\"/\", follow_redirects=False)\n    verifier(racine.status_code == 302 and racine.location.endswith(\"/accueil\"), \"la racine ne redirige pas\")\n\n    login_piege = client.get(\"/auth/login-page?next=https://evil.example\")\n    verifier(login_piege.status_code == 200, \"page de connexion indisponible\")\n    verifier(\"evil.example\" not in login_piege.get_data(as_text=True), \"redirection ouverte\")\n    verifier(\"Connexion\" in login_piege.get_data(as_text=True), \"formulaire de connexion absent\")\n\n    matieres = client.get(\"/info/matiere\")\n    verifier(matieres.status_code == 200, \"liste des matières en échec\")\n    verifier(\"Mathematiques\" in matieres.get_json()[\"matiere\"], \"Mathématiques absentes du disque\")\n\n    traversal = client.get(\"/info/classe/..\")\n    verifier(traversal.status_code == 404, \"le segment .. aurait dû être refusé\")\n\n    mauvais = client.post(\"/auth/login\", json={\"username\": \"eleve\", \"password\": \"non\"})\n    verifier(mauvais.status_code == 401, \"un mauvais mot de passe doit être refusé\")\n\n    with app.app_context():\n        eleve = creer_compte(\"eleve\", \"user\")\n        eleve2 = creer_compte(\"eleve2\", \"user\")\n        moderateur = creer_compte(\"moderateur\", \"moderator\")\n        admin = creer_compte(\"admin\", \"admin\")\n        eleve_id = eleve.id\n        admin_id = admin.id\n\n    entete = connecter(client, \"eleve\", \"MotDePasse-Test-9\")\n    moi = client.get(\"/auth/me\")\n    verifier(moi.status_code == 200 and moi.get_json()[\"role\"] == \"user\", \"/auth/me ne décrit pas l'élève\")\n\n    sans_csrf = client.post(\n        \"/upload/Mathematiques/1ere/specialite\",\n        data={\"title\": \"Sans jeton\", \"desc\": \"ne doit pas passer\", \"file\": (io.BytesIO(b\"abc\"), \"note.txt\")},\n        headers={\"Accept\": \"application/json\"},\n    )\n    verifier(sans_csrf.status_code == 401, f\"l'envoi sans CSRF a répondu {sans_csrf.status_code}\")\n\n    html = client.post(\n        \"/upload/Mathematiques/1ere/specialite\",\n        data={\n            \"title\": \"Page\",\n            \"desc\": \"interdite\",\n            \"author\": \"admin\",\n            \"file\": (io.BytesIO(b\"<html></html>\"), \"piege.html\"),\n        },\n        headers=entete,\n    )\n    verifier(html.status_code == 400, \"un fichier HTML aurait dû être refusé\")\n\n    titre = \"<img src=x onerror=alert(1)>\"\n    envoi = client.post(\n        \"/upload/Mathematiques/1ere/specialite\",\n        data={\n            \"title\": titre,\n            \"desc\": \"Fiche de test automatique\",\n            \"author\": \"admin\",\n            \"file\": (io.BytesIO(b\"contenu de la fiche\"), \"notes.txt\"),\n        },\n        headers=entete,\n    )\n    verifier(envoi.status_code == 201, f\"publication refusée : {envoi.get_json()}\")\n    meta = envoi.get_json()[\"metadata\"]\n    file_id = meta[\"id\"]\n    suivre(Path(\"matiere/Mathematiques/1ere/specialite\") / f\"{file_id}.json\")\n    suivre(Path(\"uploads\") / meta[\"filename\"])\n    verifier(meta[\"author\"] == \"eleve\", \"l'auteur du formulaire a été accepté\")\n\n    liste = client.get(\"/info/files/Mathematiques/1ere/specialite\")\n    verifier(file_id in liste.get_json()[\"files\"], \"la fiche publiée n'apparaît pas\")\n\n    telechargement = client.get(f\"/download/Mathematiques/1ere/specialite/{file_id}\")\n    verifier(telechargement.status_code == 200, \"téléchargement impossible\")\n    verifier(telechargement.data == b\"contenu de la fiche\", \"le contenu téléchargé ne correspond pas\")\n\n    page = client.get(\"/users/dashboard\")\n    verifier(page.status_code == 200, \"tableau de bord élève indisponible\")\n    verifier(\"Audit de mes fiches\" in page.get_data(as_text=True), \"le lien d'audit personnel manque\")\n    verifier(b\"<img src=x onerror=alert(1)>\" not in page.data, \"le titre n'est pas échappé dans la page\")\n\n    entete2 = connecter(client, \"eleve2\", \"MotDePasse-Test-9\")\n    vol = client.delete(f\"/users/dashboard/delete/{file_id}\", headers=entete2)\n    verifier(vol.status_code == 403, \"un autre élève a pu supprimer la fiche\")\n\n    entete = connecter(client, \"eleve\", \"MotDePasse-Test-9\")\n    modification = client.post(\n        f\"/users/dashboard/modify/save/{file_id}\",\n        data={\"title\": \"Titre corrige\", \"desc\": \"Description corrigee\", \"matiere\": \"Mathematiques\", \"classe\": \"1ere\", \"specialite\": \"specialite\"},\n        headers=entete,\n    )\n    verifier(modification.status_code == 200, f\"modification refusée : {modification.get_json()}\")\n\n    suppression = client.delete(f\"/users/dashboard/delete/{file_id}\", headers=entete)\n    verifier(suppression.status_code == 200, f\"suppression refusée : {suppression.get_json()}\")\n    verifier(not (Path(\"uploads\") / meta[\"filename\"]).exists(), \"le fichier est resté sur le disque\")\n\n    piege_id = str(uuid.uuid4())\n    piege = Path(\"matiere/Mathematiques/1ere/specialite\") / f\"{piege_id}.json\"\n    suivre(piege)\n    piege.write_text(\n        '{\"id\":\"%s\",\"title\":\"piege\",\"author\":\"eleve\",\"desc\":\"x\",'\n        '\"filename\":\"../secret.txt\",\"original_filename\":\"secret.txt\",'\n        '\"matiere\":\"Mathematiques\",\"classe\":\"1ere\",\"specialite\":\"specialite\"}' % piege_id,\n        encoding=\"utf-8\",\n    )\n    fuite = client.get(f\"/download/Mathematiques/1ere/specialite/{piege_id}\")\n    verifier(fuite.status_code == 404, \"un nom de fichier relatif a été accepté\")\n\n    entete_modo = connecter(client, \"moderateur\", \"MotDePasse-Test-9\")\n    ban_admin = client.post(f\"/moderator/dashboard/ban/{admin_id}\", headers=entete_modo)\n    verifier(ban_admin.status_code == 403, \"un modérateur a suspendu un administrateur\")\n    role_modo = client.post(\n        f\"/moderator/dashboard/role/{eleve_id}\",\n        json={\"role\": \"admin\"},\n        headers=entete_modo,\n    )\n    verifier(role_modo.status_code == 404, \"le changement de rôle existe chez le modérateur\")\n    page_admin = client.get(\"/admin/dashboard\", headers={\"Accept\": \"text/html\"})\n    verifier(page_admin.status_code == 302, \"un modérateur n'est pas renvoyé vers son espace\")\n    verifier(\"/moderator/dashboard\" in page_admin.location, page_admin.location)\n\n    entete_admin = connecter(client, \"admin\", \"MotDePasse-Test-9\")\n    comptes = client.get(\"/admin/comptes-page\", headers={\"Accept\": \"text/html\"})\n    verifier(comptes.status_code == 200 and \"eleve\" in comptes.get_data(as_text=True), \"page des comptes admin\")\n    verifier(\"Rechercher un compte\" in comptes.get_data(as_text=True), \"la recherche de comptes manque\")\n    ban = client.post(f\"/admin/dashboard/ban/{eleve_id}\", headers=entete_admin)\n    verifier(ban.status_code == 200, f\"suspension impossible : {ban.get_json()}\")\n    refuse = client.post(\"/auth/login\", json={\"username\": \"eleve\", \"password\": \"MotDePasse-Test-9\"})\n    verifier(refuse.status_code == 403, \"un compte suspendu peut encore entrer\")\n    retour = client.post(f\"/admin/dashboard/unban/{eleve_id}\", headers=entete_admin)\n    verifier(retour.status_code == 200, \"réactivation impossible\")\n    soi = client.post(f\"/admin/dashboard/role/{admin_id}\", json={\"role\": \"user\"}, headers=entete_admin)\n    verifier(soi.status_code == 403, \"un admin a changé son propre rôle\")\n    promotion = client.post(\n        f\"/admin/dashboard/role/{eleve_id}\",\n        json={\"role\": \"moderator\"},\n        headers=entete_admin,\n    )\n    verifier(promotion.status_code == 200, f\"promotion impossible : {promotion.get_json()}\")\n    client.post(f\"/admin/dashboard/role/{eleve_id}\", json={\"role\": \"user\"}, headers=entete_admin)\n\n    sortie = client.post(\"/auth/logout\", headers=entete_admin)\n    verifier(sortie.status_code == 200, \"déconnexion impossible\")\n    apres = client.get(\"/auth/me\")\n    verifier(apres.status_code == 401, \"la session est encore valable après la déconnexion\")\n\n    with app.app_context():\n        proprietaire = creer_compte(\"proprietaire\", \"owner\")\n        proprietaire_id = proprietaire.id\n\n    sans_session = client.get(\"/owner/audit.json\")\n    verifier(sans_session.status_code == 401, \"l'audit est public\")\n\n    entete_admin = connecter(client, \"admin\", \"MotDePasse-Test-9\")\n    ban_owner = client.post(f\"/admin/dashboard/ban/{proprietaire_id}\", headers=entete_admin)\n    verifier(ban_owner.status_code == 403, f\"un admin a suspendu le propriétaire : {ban_owner.get_json()}\")\n    vol_role = client.post(\n        f\"/admin/dashboard/role/{proprietaire_id}\",\n        json={\"role\": \"user\"},\n        headers=entete_admin,\n    )\n    verifier(vol_role.status_code == 403, f\"un admin a modifié le propriétaire : {vol_role.get_json()}\")\n    faux_owner = client.post(\n        f\"/admin/dashboard/role/{eleve_id}\",\n        json={\"role\": \"owner\"},\n        headers=entete_admin,\n    )\n    verifier(faux_owner.status_code == 400, \"le rôle propriétaire s'attribue depuis l'admin\")\n\n    visiteur = app.test_client()\n    connecter(visiteur, \"eleve\", \"MotDePasse-Test-9\")\n    admin_pause = app.test_client()\n    connecter(admin_pause, \"admin\", \"MotDePasse-Test-9\")\n    entree = client.post(\n        \"/auth/login\",\n        json={\"username\": \"proprietaire\", \"password\": \"MotDePasse-Test-9\"},\n    )\n    verifier(entree.status_code == 200, f\"connexion propriétaire : {entree.get_json()}\")\n    verifier(entree.get_json()[\"home\"] == \"/owner/audit\", \"mauvais accueil propriétaire\")\n    entete_owner = csrf(client)\n\n    page = client.get(\"/owner/audit\", headers={\"Accept\": \"text/html\"})\n    verifier(page.status_code == 200, \"page d'audit indisponible\")\n    texte = page.get_data(as_text=True)\n    verifier(\"Audit du site\" in texte and \"Suspendre le site\" in texte, \"le bouton de suspension manque\")\n    verifier(\"En tête par matière\" in texte, \"le classement d'étoiles manque\")\n    donnees = client.get(\"/owner/audit.json\")\n    verifier(donnees.status_code == 200, f\"json d'audit : {donnees.get_json()}\")\n    audit = donnees.get_json()\n    verifier(audit[\"stockage\"][\"disque_total_octets\"] > 0, \"le disque n'est pas mesuré\")\n    verifier(audit[\"contenu\"][\"matieres\"] > 0, \"les matières ne sont pas comptées\")\n    verifier(\"sessions\" in audit and \"comptes\" in audit and \"securite\" in audit, \"relevé incomplet\")\n    verifier(\n        any(session[\"username\"] == \"proprietaire\" for session in audit[\"sessions\"][\"liste\"]),\n        \"le propriétaire connecté n'apparaît pas\",\n    )\n    refus_eleve = visiteur.get(\"/owner/audit.json\")\n    verifier(refus_eleve.status_code == 403, \"un élève lit l'audit\")\n    admin_owner = client.get(\"/admin/dashboard\", headers={\"Accept\": \"text/html\"})\n    verifier(admin_owner.status_code == 200, \"le propriétaire n'ouvre pas l'administration\")\n\n    verifier_social(client)\n\n    suspension = client.post(\"/owner/site\", json={\"suspendu\": True}, headers=entete_owner)\n    verifier(\n        suspension.status_code == 200 and suspension.get_json()[\"site\"][\"suspendu\"] is True,\n        f\"suspension du site : {suspension.get_json()}\",\n    )\n    page_eleve = visiteur.get(\"/accueil\", headers={\"Accept\": \"text/html\"})\n    verifier(page_eleve.status_code == 503, \"l'élève consulte le site suspendu\")\n    verifier(\"Site suspendu\" in page_eleve.get_data(as_text=True), \"page de pause absente\")\n    verifier(visiteur.get(\"/info/matiere\").status_code == 503, \"l'API reste ouverte pendant la pause\")\n    exterieur = app.test_client()\n    bloque = exterieur.post(\"/auth/login\", json={\"username\": \"eleve\", \"password\": \"MotDePasse-Test-9\"})\n    verifier(bloque.status_code == 503, f\"un élève se connecte pendant la pause : {bloque.get_json()}\")\n    banniere = exterieur.get(\"/auth/login-page\")\n    verifier(\"Le site est suspendu.\" in banniere.get_data(as_text=True), \"la page de connexion ne prévient pas\")\n    verifier(client.get(\"/owner/audit.json\").status_code == 200, \"le propriétaire est bloqué avec le site\")\n    verifier(client.get(\"/admin/dashboard\", headers={\"Accept\": \"text/html\"}).status_code == 200, \"admin coupé pour le propriétaire\")\n    verifier(\n        admin_pause.get(\"/admin/dashboard\", headers={\"Accept\": \"text/html\"}).status_code == 503,\n        \"un administrateur passe pendant la pause\",\n    )\n\n    reprise = client.post(\"/owner/site\", json={\"suspendu\": False}, headers=entete_owner)\n    verifier(\n        reprise.status_code == 200 and reprise.get_json()[\"site\"][\"suspendu\"] is False,\n        f\"réactivation : {reprise.get_json()}\",\n    )\n    verifier(visiteur.get(\"/info/matiere\").status_code == 200, \"le site ne se rouvre pas\")\n\n    sortie_owner = client.post(\"/auth/logout\", headers=entete_owner)\n    verifier(sortie_owner.status_code == 200, \"déconnexion propriétaire impossible\")\n    verifier(client.get(\"/owner/audit.json\").status_code == 401, \"la session propriétaire reste ouverte\")\n    entete_owner = connecter(client, \"proprietaire\", \"MotDePasse-Test-9\")\n    encore = client.get(\"/owner/audit.json\").get_json()[\"sessions\"][\"liste\"]\n    verifier(\n        sum(1 for session in encore if session[\"username\"] == \"proprietaire\") == 1,\n        \"une session fermée est encore listée\",\n    )\n    client.post(\"/auth/logout\", headers=entete_owner)\n\n    verifier_mot_de_passe()\n\n    _ATTEMPTS.clear()\n    os.environ[\"LOGIN_MAX_ATTEMPTS\"] = \"2\"\n    client.post(\"/auth/login\", json={\"username\": \"personne\", \"password\": \"a\"})\n    client.post(\"/auth/login\", json={\"username\": \"personne\", \"password\": \"b\"})\n    bloque = client.post(\"/auth/login\", json={\"username\": \"personne\", \"password\": \"c\"})\n    verifier(bloque.status_code == 429, \"le plafond de tentatives ne s'applique pas\")\n    _ATTEMPTS.clear()\n");
source("users/routes.py", "dashboard", "python", "@users_bp.route(\"/dashboard\", methods=[\"GET\"])\n@jwt_required()\ndef dashboard():\n    \"\"\"Tableau de bord : fiches envoyées et fiches téléchargées.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n\n    uploaded = annoter(files_from_cache(user.uploaded_files, user.uploaded_metadatas), user)\n    downloaded = annoter(files_from_cache(user.download_ids, user.download_metadatas), user)\n    return render_template(\n        \"user_dashboard.html\",\n        profil=public_profile(user, include_status=True),\n        envoyes=uploaded,\n        telecharges=downloaded,\n    )\n");
source("users/routes.py", "audit_page", "python", "@users_bp.route(\"/audit\", methods=[\"GET\"])\n@jwt_required()\ndef audit_page():\n    \"\"\"Relevé des fiches de ce compte, et de rien d'autre.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return render_template(\n        \"audit_perso.html\",\n        profil=public_profile(user),\n        audit=collecter_audit_perso(user),\n        titre=\"Audit de mes fiches\",\n    )\n");
source("users/routes.py", "audit_json", "python", "@users_bp.route(\"/audit.json\", methods=[\"GET\"])\n@jwt_required()\ndef audit_json():\n    \"\"\"Même relevé, pour actualiser la page sans mélanger les comptes.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return jsonify(collecter_audit_perso(user)), 200\n");
source("users/routes.py", "modify_file", "python", "@users_bp.route(\"/dashboard/modify/<file_id>\", methods=[\"GET\"])\n@jwt_required()\ndef modify_file(file_id):\n    \"\"\"Formulaire de modification d'une fiche qui appartient à l'élève.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    if not is_uuid(file_id) or file_id not in (user.uploaded_files or []):\n        return error_response(\"Fiche introuvable\", 404)\n\n    owner, owner_error = owner_of(file_id)\n    if owner_error:\n        return owner_error\n    if owner.id != user.id:\n        return error_response(\"Accès refusé\", 403)\n\n    metadata = read_metadata(find_metadata_path(file_id))\n    if metadata is None:\n        return error_response(\"Fiche introuvable\", 404)\n\n    return render_template(\n        \"modifier.html\",\n        metadata=public_metadata(metadata),\n        save_url=f\"/users/dashboard/modify/save/{file_id}\",\n        retour_url=\"/users/dashboard\",\n        titre=\"Modifier ma fiche\",\n    )\n");
source("users/routes.py", "save_modified_file", "python", "@users_bp.route(\"/dashboard/modify/save/<file_id>\", methods=[\"POST\"])\n@jwt_required()\ndef save_modified_file(file_id):\n    \"\"\"Enregistre le formulaire de modification.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return update_file(user, file_id, request.form, request.files.get(\"file\"), acteur=user)\n");
source("users/routes.py", "delete_file", "python", "@users_bp.route(\"/dashboard/delete/<file_id>\", methods=[\"DELETE\"])\n@jwt_required()\ndef delete_file(file_id):\n    \"\"\"Supprime une fiche de l'élève.\"\"\"\n    user, error = require_user()\n    if error:\n        return error\n    return remove_file(user, file_id)\n");
source("utils/access.py", "forcer_mot_de_passe", "python", "def forcer_mot_de_passe():\n    \"\"\"Tant que le compte n'a pas choisi son mot de passe, le reste du site est fermé.\"\"\"\n    try:\n        verify_jwt_in_request(optional=True)\n    except Exception:\n        return None\n    user = load_current_user()\n    if user is None or user.is_ban or not user.must_change_password:\n        return None\n    if request.endpoint in _PAGES_MOT_DE_PASSE or request.path.startswith((\"/static/\", \"/auth/static/\", \"/legal/\")):\n        return None\n    if wants_html():\n        return redirect(\"/auth/mot-de-passe\")\n    return jsonify({\"error\": \"Choisis un nouveau mot de passe pour continuer.\"}), 403\n");
source("utils/access.py", "home_for_role", "python", "def home_for_role(role):\n    \"\"\"Page d'accueil personnelle selon le rôle.\"\"\"\n    if role == \"owner\":\n        return \"/owner/audit\"\n    if role == \"admin\":\n        return \"/admin/dashboard\"\n    if role == \"moderator\":\n        return \"/moderator/dashboard\"\n    return \"/users/dashboard\"\n");
source("utils/access.py", "load_current_user", "python", "def load_current_user():\n    \"\"\"Compte lié au jeton, ou None s'il n'existe plus.\"\"\"\n    identity = get_jwt_identity()\n    if not identity:\n        return None\n    return db.session.get(User, identity)\n");
source("utils/access.py", "optional_user", "python", "def optional_user():\n    \"\"\"Compte du jeton s'il est encore valide, sinon None.\n\n    Un cookie absent, expiré ou révoqué ne bloque pas la page publique :\n    la personne est simplement traitée comme non connectée.\n    \"\"\"\n    try:\n        verify_jwt_in_request(optional=True)\n    except Exception:\n        return None\n    identity = get_jwt_identity()\n    if not identity or not is_uuid(identity):\n        return None\n    user = db.session.get(User, identity)\n    if user is None or user.is_ban:\n        return None\n    return user\n");
source("utils/access.py", "require_user", "python", "def require_user():\n    \"\"\"Retourne (compte, None) ou (None, réponse d'erreur).\"\"\"\n    user = load_current_user()\n    if user is None:\n        return None, error_response(\"Compte introuvable\", 404)\n    if user.is_ban:\n        return None, error_response(\"Compte suspendu\", 403)\n    return user, None\n");
source("utils/access.py", "require_roles", "python", "def require_roles(user, roles):\n    \"\"\"Laisse passer les rôles listés. Une page HTML est renvoyée vers son propre espace.\"\"\"\n    if user.role in roles:\n        return None\n    if wants_html():\n        return redirect(home_for_role(user.role))\n    return jsonify({\"error\": \"Accès refusé\"}), 403\n");
source("utils/access.py", "can_moderate", "python", "def can_moderate(actor, target):\n    \"\"\"Règle de suspension d'un compte.\n\n    Le propriétaire peut suspendre tout le monde sauf un autre propriétaire.\n    Un administrateur peut suspendre un élève ou un modérateur.\n    Un modérateur ne peut suspendre qu'un élève.\n    Personne ne peut se suspendre soi-même, ni toucher au propriétaire.\n    \"\"\"\n    if actor.id == target.id or target.role == \"owner\":\n        return False\n    if actor.role == \"owner\":\n        return True\n    if actor.role == \"admin\":\n        return target.role != \"admin\"\n    if actor.role == \"moderator\":\n        return target.role == \"user\"\n    return False\n");
source("utils/access.py", "set_ban", "python", "def set_ban(actor, target_id, banned):\n    \"\"\"Suspend ou réactive un compte, si l'acteur en a le droit.\"\"\"\n    if not is_uuid(target_id):\n        return jsonify({\"error\": \"Compte introuvable\"}), 404\n    if actor.role not in (\"admin\", \"moderator\", \"owner\"):\n        return jsonify({\"error\": \"Accès refusé\"}), 403\n\n    target = db.session.get(User, target_id)\n    if target is None:\n        return jsonify({\"error\": \"Compte introuvable\"}), 404\n    if not can_moderate(actor, target):\n        return jsonify({\"error\": \"Action non autorisée sur ce compte\"}), 403\n\n    target.is_ban = bool(banned)\n    db.session.commit()\n    message = \"Compte suspendu\" if banned else \"Compte réactivé\"\n    return jsonify({\"message\": message}), 200\n");
source("utils/access.py", "set_role", "python", "def set_role(actor, target_id, new_role):\n    \"\"\"Change le rôle. Réservé à un administrateur ou au propriétaire, jamais sur son propre compte.\n\n    Le rôle propriétaire ne s'attribue pas ici : il vient de init_users.py.\n    \"\"\"\n    if actor.role not in (\"admin\", \"owner\"):\n        return jsonify({\"error\": \"Accès refusé\"}), 403\n    if new_role not in (\"user\", \"moderator\", \"admin\"):\n        return jsonify({\"error\": \"Rôle inconnu\"}), 400\n    if not is_uuid(target_id):\n        return jsonify({\"error\": \"Compte introuvable\"}), 404\n\n    target = db.session.get(User, target_id)\n    if target is None:\n        return jsonify({\"error\": \"Compte introuvable\"}), 404\n    if target.role == \"owner\":\n        return jsonify({\"error\": \"Le propriétaire ne peut pas être modifié\"}), 403\n    if actor.id == target.id:\n        return jsonify({\"error\": \"Tu ne peux pas modifier ton propre rôle\"}), 403\n\n    # On garde toujours au moins un administrateur, sinon plus personne ne gère le site.\n    if target.role == \"admin\" and new_role != \"admin\":\n        other_admins = User.query.filter(User.role == \"admin\", User.id != target.id).count()\n        if other_admins < 1:\n            return jsonify({\"error\": \"Il doit rester au moins un administrateur\"}), 409\n\n    target.role = new_role\n    db.session.commit()\n    return jsonify({\"message\": \"Rôle mis à jour\", \"role\": new_role}), 200\n");
source("utils/audit.py", "_taille_dossier", "python", "def _taille_dossier(racine):\n    total = 0\n    fichiers = 0\n    racine = Path(racine)\n    if not racine.is_dir():\n        return 0, 0\n    for chemin in racine.rglob(\"*\"):\n        if chemin.is_symlink() or not chemin.is_file():\n            continue\n        try:\n            total += chemin.stat().st_size\n            fichiers += 1\n        except OSError:\n            continue\n    return total, fichiers\n");
source("utils/audit.py", "_taille_base", "python", "def _taille_base():\n    uri = current_app.config.get(\"SQLALCHEMY_DATABASE_URI\") or \"\"\n    try:\n        url = make_url(uri)\n    except Exception:\n        return 0\n    if url.drivername != \"sqlite\" or not url.database:\n        return 0\n    chemin = Path(url.database)\n    if not chemin.is_file():\n        chemin = Path(current_app.instance_path) / url.database\n    if not chemin.is_file():\n        return 0\n    try:\n        return chemin.stat().st_size\n    except OSError:\n        return 0\n");
source("utils/audit.py", "_naive", "python", "def _naive(moment):\n    if moment is None:\n        return None\n    if moment.tzinfo is not None:\n        return moment.astimezone(timezone.utc).replace(tzinfo=None)\n    return moment\n");
source("utils/audit.py", "_compte", "python", "def _compte(user):\n    moment = _naive(user.created_at) if user is not None else None\n    if moment is None:\n        return None\n    return {\"username\": user.username, \"le\": _iso(moment)}\n");
source("utils/audit.py", "_parcourir", "python", "def _parcourir():\n    \"\"\"Fiches, cours vides et compteurs d'arborescence.\"\"\"\n    base = project_dir(\"matiere\")\n    fiches = []\n    invalides = 0\n    doublons = defaultdict(int)\n    vides = []\n    classes = 0\n    specialites = 0\n    matieres = list_names(base, \"dir\")\n\n    for matiere in matieres:\n        dossier_matiere = child_dir(base, matiere)\n        if dossier_matiere is None:\n            continue\n        for classe in list_names(dossier_matiere, \"dir\"):\n            dossier_classe = child_dir(dossier_matiere, classe)\n            if dossier_classe is None:\n                continue\n            classes += 1\n            for specialite in list_names(dossier_classe, \"dir\"):\n                dossier = child_dir(dossier_classe, specialite)\n                if dossier is None:\n                    continue\n                specialites += 1\n                jsons = [nom for nom in list_names(dossier, \"file\") if nom.endswith(\".json\")]\n                if not jsons:\n                    vides.append({\n                        \"matiere\": matiere,\n                        \"classe\": classe,\n                        \"specialite\": specialite,\n                    })\n                for nom in jsons:\n                    file_id = nom[: -len(\".json\")]\n                    if not is_uuid(file_id):\n                        invalides += 1\n                        continue\n                    chemin_json = dossier / nom\n                    meta = read_metadata(chemin_json)\n                    if meta is None or meta.get(\"id\") != file_id:\n                        invalides += 1\n                        continue\n                    doublons[file_id] += 1\n                    stocke = meta.get(\"filename\") if isinstance(meta.get(\"filename\"), str) else \"\"\n                    chemin_fichier = upload_path(stocke) if stocke else None\n                    present = (\n                        chemin_fichier is not None\n                        and chemin_fichier.is_file()\n                        and not chemin_fichier.is_symlink()\n                    )\n                    try:\n                        octets = chemin_fichier.stat().st_size if present else 0\n                        horodatage = chemin_fichier.stat().st_mtime if present else chemin_json.stat().st_mtime\n                    except OSError:\n                        octets = 0\n                        horodatage = 0\n                    brut = load_json_object(chemin_json) or {}\n                    fiches.append({\n                        \"id\": file_id,\n                        \"titre\": brut.get(\"title\") if isinstance(brut.get(\"title\"), str) else \"\",\n                        \"auteur\": brut.get(\"author\") if isinstance(brut.get(\"author\"), str) else \"\",\n                        \"matiere\": matiere,\n                        \"classe\": classe,\n                        \"specialite\": specialite,\n                        \"stocke\": stocke if present else \"\",\n                        \"present\": present,\n                        \"octets\": octets,\n                        \"extension\": Path(str(brut.get(\"original_filename\") or stocke)).suffix.lower() or \"(aucune)\",\n                        \"le\": _iso(datetime.fromtimestamp(horodatage, timezone.utc).replace(tzinfo=None)) if horodatage else None,\n                    })\n\n    ids_doublons = sum(1 for nombre in doublons.values() if nombre > 1)\n    return {\n        \"matieres\": len(matieres),\n        \"classes\": classes,\n        \"specialites\": specialites,\n        \"fiches\": fiches,\n        \"invalides\": invalides,\n        \"doublons\": ids_doublons,\n        \"vides\": vides,\n    }\n");
source("utils/audit.py", "_mesurer_uploads", "python", "def _mesurer_uploads(references):\n    base = project_dir(\"uploads\")\n    total = 0\n    nombre = 0\n    orphelins = []\n    if not base.is_dir():\n        return 0, 0, 0, []\n    for entree in base.iterdir():\n        if entree.name.startswith(\".\") or entree.is_symlink() or not entree.is_file():\n            continue\n        try:\n            taille = entree.stat().st_size\n        except OSError:\n            continue\n        nombre += 1\n        total += taille\n        if entree.name not in references:\n            orphelins.append({\"nom\": entree.name, \"octets\": taille})\n    orphelins.sort(key=lambda item: item[\"octets\"], reverse=True)\n    octets_orphelins = sum(item[\"octets\"] for item in orphelins)\n    return total, nombre, octets_orphelins, orphelins\n");
source("utils/audit.py", "collecter_audit", "python", "def collecter_audit():\n    \"\"\"Dict JSON de tout ce qui se mesure sans inventer de donnée.\"\"\"\n    from utils.site_gate import lire_etat\n\n    maintenant = _maintenant()\n    utilisateurs = User.query.all()\n    parcours = _parcourir()\n    fiches = parcours[\"fiches\"]\n    ids_disque = {fiche[\"id\"] for fiche in fiches}\n    auteurs = {user.username for user in utilisateurs}\n\n    par_role = {\"user\": 0, \"moderator\": 0, \"admin\": 0, \"owner\": 0}\n    actifs = 0\n    avec_envois = 0\n    avec_telechargements = 0\n    sans_activite = 0\n    envois = 0\n    telechargements = 0\n    envois_perdus = 0\n    fiches_lues = set()\n    top_auteurs = []\n    top_lecteurs = []\n    suspendus = []\n\n    for user in utilisateurs:\n        par_role[user.role] = par_role.get(user.role, 0) + 1\n        if user.is_ban:\n            suspendus.append({\"username\": user.username, \"role\": user.role})\n        else:\n            actifs += 1\n        nombre_envois = len(user.uploaded_files or [])\n        nombre_lectures = len(user.download_ids or [])\n        envois += nombre_envois\n        telechargements += nombre_lectures\n        for file_id in user.uploaded_files or []:\n            if file_id not in ids_disque:\n                envois_perdus += 1\n        for file_id in user.download_ids or []:\n            fiches_lues.add(file_id)\n        if nombre_envois:\n            avec_envois += 1\n            top_auteurs.append({\"username\": user.username, \"nombre\": nombre_envois})\n        if nombre_lectures:\n            avec_telechargements += 1\n            top_lecteurs.append({\"username\": user.username, \"nombre\": nombre_lectures})\n        if not nombre_envois and not nombre_lectures:\n            sans_activite += 1\n\n    top_auteurs.sort(key=lambda item: (-item[\"nombre\"], item[\"username\"]))\n    top_lecteurs.sort(key=lambda item: (-item[\"nombre\"], item[\"username\"]))\n\n    dates = []\n    for user in utilisateurs:\n        moment = _naive(user.created_at)\n        if moment is not None:\n            dates.append((moment, user))\n    dates.sort(key=lambda item: item[0])\n    plus_ancien = _compte(dates[0][1]) if dates else None\n    plus_recent = _compte(dates[-1][1]) if dates else None\n\n    def _crees_depuis(delta):\n        seuil = maintenant - delta\n        return sum(1 for moment, _user in dates if moment >= seuil)\n\n    par_matiere = {}\n    par_classe = defaultdict(lambda: {\"fiches\": 0, \"octets\": 0})\n    par_extension = defaultdict(lambda: {\"fiches\": 0, \"octets\": 0})\n    presentes = []\n    manquants = 0\n    auteurs_inconnus = 0\n    references = set()\n\n    for fiche in fiches:\n        bloc = par_matiere.setdefault(fiche[\"matiere\"], {\"fiches\": 0, \"octets\": 0, \"cours\": set()})\n        bloc[\"fiches\"] += 1\n        bloc[\"octets\"] += fiche[\"octets\"]\n        bloc[\"cours\"].add((fiche[\"classe\"], fiche[\"specialite\"]))\n        par_classe[fiche[\"classe\"]][\"fiches\"] += 1\n        par_classe[fiche[\"classe\"]][\"octets\"] += fiche[\"octets\"]\n        par_extension[fiche[\"extension\"]][\"fiches\"] += 1\n        par_extension[fiche[\"extension\"]][\"octets\"] += fiche[\"octets\"]\n        if fiche[\"present\"]:\n            presentes.append(fiche)\n            references.add(fiche[\"stocke\"])\n        else:\n            manquants += 1\n        if fiche[\"auteur\"] not in auteurs:\n            auteurs_inconnus += 1\n\n    uploads_octets, uploads_fichiers, orphelins_octets, orphelins = _mesurer_uploads(references)\n    matiere_octets, matiere_fichiers = _taille_dossier(project_dir(\"matiere\"))\n    instance = Path(current_app.instance_path)\n    instance_octets, _instance_fichiers = _taille_dossier(instance)\n    try:\n        disque = shutil.disk_usage(Path(\".\").resolve())\n        disque_total, disque_utilise, disque_libre = disque.total, disque.used, disque.free\n    except OSError:\n        disque_total = disque_utilise = disque_libre = 0\n\n    plus_gros = sorted(presentes, key=lambda fiche: fiche[\"octets\"], reverse=True)[:8]\n    dernieres = sorted(fiches, key=lambda fiche: fiche[\"le\"] or \"\", reverse=True)[:8]\n    moyenne = int(sum(fiche[\"octets\"] for fiche in presentes) / len(presentes)) if presentes else 0\n\n    etat = lire_etat()\n    expiration = current_app.config.get(\"JWT_ACCESS_TOKEN_EXPIRES\")\n    heures = expiration.total_seconds() / 3600 if hasattr(expiration, \"total_seconds\") else 0\n\n    try:\n        from auth.routes import etat_tentatives\n        tentatives = etat_tentatives()\n    except Exception:\n        tentatives = {\"bloques\": [], \"suivis\": 0}\n\n    return {\n        \"genere_le\": _iso(maintenant),\n        \"site\": {\n            \"suspendu\": bool(etat[\"suspended\"]),\n            \"depuis\": etat[\"since\"],\n            \"par\": etat[\"by\"],\n            \"demarre_le\": _iso(_demarrage()),\n            \"duree_secondes\": int((maintenant - _demarrage()).total_seconds()),\n            \"envoi_max_octets\": int(current_app.config.get(\"MAX_CONTENT_LENGTH\") or 0),\n            \"session_heures\": heures,\n            \"cookie_securise\": bool(current_app.config.get(\"JWT_COOKIE_SECURE\")),\n        },\n        \"stockage\": {\n            \"uploads_octets\": uploads_octets,\n            \"uploads_fichiers\": uploads_fichiers,\n            \"orphelins_octets\": orphelins_octets,\n            \"orphelins\": len(orphelins),\n            \"matiere_octets\": matiere_octets,\n            \"matiere_fichiers\": matiere_fichiers,\n            \"base_octets\": _taille_base(),\n            \"instance_octets\": instance_octets,\n            \"disque_total_octets\": disque_total,\n            \"disque_utilise_octets\": disque_utilise,\n            \"disque_libre_octets\": disque_libre,\n        },\n        \"sessions\": resume_sessions(),\n        \"comptes\": {\n            \"total\": len(utilisateurs),\n            \"actifs\": actifs,\n            \"suspendus\": len(suspendus),\n            \"par_role\": {\n                \"user\": par_role.get(\"user\", 0),\n                \"moderator\": par_role.get(\"moderator\", 0),\n                \"admin\": par_role.get(\"admin\", 0),\n                \"owner\": par_role.get(\"owner\", 0),\n            },\n            \"crees_24h\": _crees_depuis(timedelta(days=1)),\n            \"crees_7j\": _crees_depuis(timedelta(days=7)),\n            \"crees_30j\": _crees_depuis(timedelta(days=30)),\n            \"avec_envois\": avec_envois,\n            \"avec_telechargements\": avec_telechargements,\n            \"sans_activite\": sans_activite,\n            \"plus_ancien\": plus_ancien,\n            \"plus_recent\": plus_recent,\n        },\n        \"activite\": {\n            \"envois\": envois,\n            \"telechargements\": telechargements,\n            \"fiches_telechargees\": len(fiches_lues),\n            \"envois_perdus\": envois_perdus,\n            \"top_auteurs\": top_auteurs[:5],\n            \"top_lecteurs\": top_lecteurs[:5],\n        },\n        \"contenu\": {\n            \"matieres\": parcours[\"matieres\"],\n            \"classes\": parcours[\"classes\"],\n            \"specialites\": parcours[\"specialites\"],\n            \"cours_vides\": len(parcours[\"vides\"]),\n            \"fiches\": len(fiches),\n            \"json_invalides\": parcours[\"invalides\"],\n            \"doublons\": parcours[\"doublons\"],\n            \"fichiers_manquants\": manquants,\n            \"auteurs_inconnus\": auteurs_inconnus,\n            \"taille_moyenne_octets\": moyenne,\n            \"types_autorises\": sorted(EXTENSIONS_AUTORISEES),\n            \"par_matiere\": [\n                {\n                    \"nom\": nom,\n                    \"fiches\": bloc[\"fiches\"],\n                    \"octets\": bloc[\"octets\"],\n                    \"cours\": len(bloc[\"cours\"]),\n                }\n                for nom, bloc in sorted(par_matiere.items(), key=lambda item: (-item[1][\"fiches\"], item[0]))\n            ],\n            \"par_classe\": [\n                {\"nom\": nom, \"fiches\": bloc[\"fiches\"], \"octets\": bloc[\"octets\"]}\n                for nom, bloc in sorted(par_classe.items(), key=lambda item: (ORDRE_CLASSE.get(item[0], 99), item[0]))\n            ],\n            \"par_extension\": [\n                {\"nom\": nom, \"fiches\": bloc[\"fiches\"], \"octets\": bloc[\"octets\"]}\n                for nom, bloc in sorted(par_extension.items(), key=lambda item: (-item[1][\"octets\"], item[0]))\n            ],\n            \"plus_gros\": [_fiche_courte(fiche) for fiche in plus_gros],\n            \"dernieres\": [_fiche_courte(fiche) for fiche in dernieres],\n            \"cours_vides_liste\": parcours[\"vides\"][:15],\n            \"orphelins_liste\": orphelins[:12],\n        },\n        \"securite\": {\n            \"identifiants_bloques\": tentatives[\"bloques\"],\n            \"tentatives_suivies\": tentatives[\"suivis\"],\n            \"comptes_suspendus\": sorted(suspendus, key=lambda item: item[\"username\"]),\n        },\n        \"etoiles\": classement(),\n    }\n");
source("utils/audit.py", "_crees_depuis", "python", "    def _crees_depuis(delta):\n        seuil = maintenant - delta\n        return sum(1 for moment, _user in dates if moment >= seuil)\n");
source("utils/audit.py", "_fiche_courte", "python", "def _fiche_courte(fiche):\n    return {\n        \"titre\": fiche[\"titre\"] or \"Sans titre\",\n        \"auteur\": fiche[\"auteur\"],\n        \"matiere\": fiche[\"matiere\"],\n        \"classe\": fiche[\"classe\"],\n        \"specialite\": fiche[\"specialite\"],\n        \"octets\": fiche[\"octets\"],\n        \"le\": fiche[\"le\"],\n    }\n");
source("utils/audit.py", "_demarrage", "python", "def _demarrage():\n    global _DEMARRAGE\n    if _DEMARRAGE is None:\n        _DEMARRAGE = _maintenant()\n    return _DEMARRAGE\n");
source("utils/audit_perso.py", "_commentaires_visibles", "python", "def _commentaires_visibles(user, file_ids):\n    if not file_ids:\n        return []\n    lignes = (\n        Comment.query.filter(Comment.file_id.in_(file_ids))\n        .order_by(Comment.created_at.desc())\n        .all()\n    )\n    visibles = []\n    for comment in lignes:\n        meta = trouver_fiche(comment.file_id)\n        if meta is None:\n            continue\n        auteur = meta.get(\"author\") if isinstance(meta.get(\"author\"), str) else \"\"\n        if peut_voir(user, comment, auteur):\n            visibles.append((comment, meta))\n    return visibles\n");
source("utils/audit_perso.py", "collecter_audit_perso", "python", "def collecter_audit_perso(user):\n    \"\"\"Dict JSON du relevé personnel.\"\"\"\n    identifiants = [file_id for file_id in (user.uploaded_files or []) if is_uuid(file_id)]\n    fiches = []\n    for file_id in identifiants:\n        meta = trouver_fiche(file_id)\n        if meta is None or meta.get(\"author\") != user.username:\n            continue\n        vue = vue_publique(meta)\n        vue[\"octets\"] = taille_octets(meta)\n        fiches.append(vue)\n    annoter(fiches, user)\n\n    file_ids = {fiche[\"id\"] for fiche in fiches}\n    telechargements = 0\n    if file_ids:\n        for compte in User.query.all():\n            for file_id in compte.download_ids or []:\n                if file_id in file_ids:\n                    telechargements += 1\n\n    visibles = _commentaires_visibles(user, list(file_ids))\n    par_fiche = {fiche[\"id\"]: {\"ouverts\": 0, \"pris\": 0, \"valides\": 0} for fiche in fiches}\n    totaux = {\"ouverts\": 0, \"pris\": 0, \"valides\": 0}\n    for comment, _meta in visibles:\n        cle = {\"ouvert\": \"ouverts\", \"pris\": \"pris\", \"valide\": \"valides\"}.get(comment.status)\n        if cle is None:\n            continue\n        totaux[cle] += 1\n        if comment.file_id in par_fiche:\n            par_fiche[comment.file_id][cle] += 1\n\n    for fiche in fiches:\n        fiche[\"commentaires\"] = par_fiche.get(fiche[\"id\"], {\"ouverts\": 0, \"pris\": 0, \"valides\": 0})\n\n    avec_etoiles = [fiche for fiche in fiches if fiche[\"etoiles\"] > 0]\n    avec_etoiles.sort(key=lambda fiche: (-fiche[\"etoiles\"], (fiche[\"title\"] or \"\").casefold(), fiche[\"id\"]))\n    plus = avec_etoiles[0] if avec_etoiles else None\n\n    recents = []\n    for comment, meta in visibles[:12]:\n        responsable = None\n        if comment.handler_id:\n            handler = db.session.get(User, comment.handler_id)\n            if handler is not None:\n                responsable = handler.username\n        recents.append({\n            \"texte\": comment.body,\n            \"audience\": comment.audience,\n            \"statut\": comment.status,\n            \"responsable\": responsable,\n            \"fiche\": meta.get(\"title\") or \"Sans titre\",\n            \"matiere\": meta.get(\"matiere\") or \"\",\n            \"le\": _iso(comment.created_at),\n        })\n\n    fiches.sort(key=lambda fiche: (-fiche[\"etoiles\"], (fiche[\"title\"] or \"\").casefold()))\n    return {\n        \"genere_le\": _iso(_maintenant()),\n        \"resume\": {\n            \"fiches\": len(fiches),\n            \"octets\": sum(fiche[\"octets\"] for fiche in fiches),\n            \"etoiles\": sum(fiche[\"etoiles\"] for fiche in fiches),\n            \"telechargements\": telechargements,\n            \"commentaires\": totaux,\n        },\n        \"plus_etoilee\": None if plus is None else {\n            \"titre\": plus[\"title\"] or \"Sans titre\",\n            \"matiere\": plus[\"matiere\"],\n            \"classe\": plus[\"classe\"],\n            \"specialite\": plus[\"specialite\"],\n            \"etoiles\": plus[\"etoiles\"],\n        },\n        \"liste\": [\n            {\n                \"id\": fiche[\"id\"],\n                \"titre\": fiche[\"title\"] or \"Sans titre\",\n                \"matiere\": fiche[\"matiere\"],\n                \"classe\": fiche[\"classe\"],\n                \"specialite\": fiche[\"specialite\"],\n                \"etoiles\": fiche[\"etoiles\"],\n                \"octets\": fiche[\"octets\"],\n                \"commentaires\": fiche[\"commentaires\"],\n            }\n            for fiche in fiches\n        ],\n        \"commentaires_recents\": recents,\n    }\n");
source("utils/catalogue.py", "_conforme", "python", "def _conforme(meta, matiere, classe, specialite, file_id):\n    return (\n        meta is not None\n        and meta.get(\"id\") == file_id\n        and meta.get(\"matiere\") == matiere\n        and meta.get(\"classe\") == classe\n        and meta.get(\"specialite\") == specialite\n    )\n");
source("utils/catalogue.py", "toutes_les_fiches", "python", "def toutes_les_fiches():\n    \"\"\"Métadonnées complètes des fiches dont le JSON correspond à son dossier.\"\"\"\n    base = project_dir(\"matiere\")\n    fiches = []\n    for matiere in list_names(base, \"dir\"):\n        dossier_matiere = child_dir(base, matiere)\n        if dossier_matiere is None:\n            continue\n        for classe in list_names(dossier_matiere, \"dir\"):\n            dossier_classe = child_dir(dossier_matiere, classe)\n            if dossier_classe is None:\n                continue\n            for specialite in list_names(dossier_classe, \"dir\"):\n                dossier = child_dir(dossier_classe, specialite)\n                if dossier is None:\n                    continue\n                for nom in list_names(dossier, \"file\"):\n                    if not nom.endswith(\".json\"):\n                        continue\n                    file_id = nom[: -len(\".json\")]\n                    if not is_uuid(file_id):\n                        continue\n                    meta = read_metadata(dossier / nom)\n                    if not _conforme(meta, matiere, classe, specialite, file_id):\n                        continue\n                    fiches.append(meta)\n    return fiches\n");
source("utils/catalogue.py", "trouver_fiche", "python", "def trouver_fiche(file_id):\n    \"\"\"Métadonnées d'une fiche, ou None si l'identifiant est inconnu ou ambigu.\"\"\"\n    if not is_uuid(file_id):\n        return None\n    path = find_metadata_path(file_id)\n    if path is None:\n        return None\n    meta = read_metadata(path)\n    specialite = path.parent.name\n    classe = path.parent.parent.name\n    matiere = path.parent.parent.parent.name\n    if not _conforme(meta, matiere, classe, specialite, file_id):\n        return None\n    return meta\n");
source("utils/catalogue.py", "vue_publique", "python", "def vue_publique(meta):\n    \"\"\"Champs d'une carte. Le nom stocké sur le disque n'en fait pas partie.\"\"\"\n    return public_metadata(meta)\n");
source("utils/catalogue.py", "taille_octets", "python", "def taille_octets(meta):\n    \"\"\"Taille du fichier envoyé, ou 0 s'il est absent ou si son nom est douteux.\"\"\"\n    file_id = meta.get(\"id\")\n    stored = meta.get(\"filename\")\n    if not valid_stored_name(file_id, stored):\n        return 0\n    path = upload_path(stored)\n    if path is None or path.is_symlink() or not path.is_file():\n        return 0\n    try:\n        return path.stat().st_size\n    except OSError:\n        return 0\n");
source("utils/commentaires.py", "_maintenant", "python", "def _maintenant():\n    return datetime.now(timezone.utc).replace(tzinfo=None)\n");
source("utils/commentaires.py", "_equipe", "python", "def _equipe(user):\n    return user is not None and user.role in EQUIPE and not user.is_ban\n");
source("utils/commentaires.py", "_auteur_fiche", "python", "def _auteur_fiche(meta):\n    auteur = meta.get(\"author\") if meta else None\n    return auteur if isinstance(auteur, str) else \"\"\n");
source("utils/commentaires.py", "peut_voir", "python", "def peut_voir(user, comment, auteur_fiche):\n    \"\"\"Vrai si ce compte a le droit de lire ce commentaire.\n\n    « auteur » vise tous les élèves, pas seulement l'auteur de la fiche.\n    L'équipe ne les voit que si le commentaire est aussi adressé à elle.\n    \"\"\"\n    if user is None or user.is_ban:\n        return False\n    if user.id == comment.author_id:\n        return True\n    if comment.audience in (\"auteur\", \"les_deux\") and user.role == \"user\":\n        return True\n    if comment.audience in (\"equipe\", \"les_deux\") and _equipe(user):\n        return True\n    return False\n");
source("utils/commentaires.py", "_peut_suivre", "python", "def _peut_suivre(user, auteur_fiche):\n    \"\"\"L'auteur de la fiche, ou un membre de l'équipe, peut suivre un commentaire.\"\"\"\n    if user is None or user.is_ban:\n        return False\n    if user.username == auteur_fiche:\n        return True\n    return user.role in EQUIPE\n");
source("utils/commentaires.py", "_responsable_actif", "python", "def _responsable_actif(handler_id):\n    if not handler_id:\n        return None\n    handler = db.session.get(User, handler_id)\n    if handler is None or handler.is_ban:\n        return None\n    if handler.role in EQUIPE or handler.role == \"user\":\n        return handler\n    return None\n");
source("utils/commentaires.py", "peut_prendre", "python", "def peut_prendre(user, comment, auteur_fiche):\n    return (\n        _peut_suivre(user, auteur_fiche)\n        and peut_voir(user, comment, auteur_fiche)\n        and comment.status == \"ouvert\"\n        and not comment.handler_id\n    )\n");
source("utils/commentaires.py", "peut_retirer", "python", "def peut_retirer(user, comment, auteur_fiche):\n    \"\"\"Vrai si cette personne suit le commentaire et a modifié la fiche ensuite.\"\"\"\n    return (\n        _peut_suivre(user, auteur_fiche)\n        and peut_voir(user, comment, auteur_fiche)\n        and comment.handler_id == user.id\n        and comment.status in (\"pris\", \"valide\")\n        and bool(comment.corrected)\n    )\n");
source("utils/commentaires.py", "peut_valider", "python", "def peut_valider(user, comment, auteur_fiche):\n    \"\"\"Seul le responsable valide. Le propriétaire reprend si ce responsable n'existe plus.\"\"\"\n    if comment.status != \"pris\" or not comment.handler_id or not _equipe(user):\n        return False\n    if not peut_voir(user, comment, auteur_fiche):\n        return False\n    if comment.handler_id == user.id:\n        return True\n    return user.role == \"owner\" and _responsable_actif(comment.handler_id) is None\n");
source("utils/commentaires.py", "_presenter", "python", "def _presenter(comment, user, auteur_fiche):\n    auteur = db.session.get(User, comment.author_id)\n    responsable = None\n    if comment.handler_id:\n        handler = db.session.get(User, comment.handler_id)\n        if handler is not None:\n            responsable = handler.username\n    return {\n        \"id\": comment.id,\n        \"auteur\": auteur.username if auteur is not None else \"\",\n        \"texte\": comment.body,\n        \"audience\": comment.audience,\n        \"statut\": comment.status,\n        \"responsable\": responsable,\n        \"le\": _iso(comment.created_at),\n        \"peut_prendre\": peut_prendre(user, comment, auteur_fiche),\n        \"peut_valider\": peut_valider(user, comment, auteur_fiche),\n        \"peut_retirer\": peut_retirer(user, comment, auteur_fiche),\n        \"suivi\": comment.handler_id == user.id and comment.status in (\"pris\", \"valide\"),\n    }\n");
source("utils/commentaires.py", "lister", "python", "def lister(user, file_id):\n    meta = trouver_fiche(file_id)\n    if meta is None:\n        return None, (\"Fiche introuvable\", 404)\n    auteur_fiche = _auteur_fiche(meta)\n    commentaires = (\n        Comment.query.filter_by(file_id=file_id)\n        .order_by(Comment.created_at.asc())\n        .all()\n    )\n    visibles = [\n        _presenter(comment, user, auteur_fiche)\n        for comment in commentaires\n        if peut_voir(user, comment, auteur_fiche)\n    ]\n    return {\"commentaires\": visibles}, None\n");
source("utils/commentaires.py", "publier", "python", "def publier(user, file_id, body, audience):\n    meta = trouver_fiche(file_id)\n    if meta is None:\n        return None, (\"Fiche introuvable\", 404)\n    if audience not in AUDIENCES:\n        return None, (\"Indique pour qui est le commentaire.\", 400)\n    texte = clean_text(body, TAILLE_MAX)\n    if texte is None:\n        return None, (\"Le commentaire est vide ou trop long (2000 caractères maximum).\", 400)\n\n    deja = Comment.query.filter_by(file_id=file_id, author_id=user.id).count()\n    if deja >= PAR_FICHE:\n        return None, (\"Tu as déjà beaucoup commenté cette fiche.\", 429)\n    seuil = _maintenant() - timedelta(days=1)\n    du_jour = Comment.query.filter(\n        Comment.author_id == user.id,\n        Comment.created_at >= seuil,\n    ).count()\n    if du_jour >= PAR_JOUR:\n        return None, (\"Trop de commentaires aujourd'hui. Réessaie demain.\", 429)\n\n    maintenant = _maintenant()\n    comment = Comment(\n        file_id=file_id,\n        author_id=user.id,\n        audience=audience,\n        body=texte,\n        status=\"ouvert\",\n        handler_id=None,\n        corrected=False,\n        created_at=maintenant,\n        updated_at=maintenant,\n    )\n    db.session.add(comment)\n    db.session.commit()\n    return {\"commentaire\": _presenter(comment, user, _auteur_fiche(meta))}, None\n");
source("utils/commentaires.py", "prendre", "python", "def prendre(user, file_id, comment_id):\n    \"\"\"Réserve le commentaire. Une seule réservation peut réussir.\"\"\"\n    if not is_uuid(comment_id):\n        return None, (\"Commentaire introuvable\", 404)\n    meta = trouver_fiche(file_id)\n    if meta is None:\n        return None, (\"Fiche introuvable\", 404)\n    comment = db.session.get(Comment, comment_id)\n    auteur_fiche = _auteur_fiche(meta)\n    if comment is None or comment.file_id != file_id or not peut_voir(user, comment, auteur_fiche):\n        return None, (\"Commentaire introuvable\", 404)\n    if not _peut_suivre(user, auteur_fiche):\n        return None, (\"Seul l'auteur de la fiche, un modérateur, un administrateur ou le propriétaire peut suivre ce commentaire.\", 403)\n    if comment.status == \"pris\" and comment.handler_id == user.id:\n        return {\"commentaire\": _presenter(comment, user, auteur_fiche)}, None\n    if comment.status != \"ouvert\" or comment.handler_id:\n        return None, (\"Quelqu'un s'occupe déjà de ce commentaire.\", 409)\n\n    db.session.execute(\n        update(Comment)\n        .where(\n            Comment.id == comment_id,\n            Comment.file_id == file_id,\n            Comment.status == \"ouvert\",\n            Comment.handler_id.is_(None),\n        )\n        .values(status=\"pris\", handler_id=user.id, corrected=False, updated_at=_maintenant())\n    )\n    db.session.commit()\n    db.session.expire_all()\n    comment = db.session.get(Comment, comment_id)\n    if comment is not None and comment.handler_id == user.id and comment.status == \"pris\":\n        return {\"commentaire\": _presenter(comment, user, auteur_fiche)}, None\n    return None, (\"Quelqu'un s'occupe déjà de ce commentaire.\", 409)\n");
source("utils/commentaires.py", "valider", "python", "def valider(user, file_id, comment_id):\n    if not is_uuid(comment_id):\n        return None, (\"Commentaire introuvable\", 404)\n    meta = trouver_fiche(file_id)\n    if meta is None:\n        return None, (\"Fiche introuvable\", 404)\n    comment = db.session.get(Comment, comment_id)\n    auteur_fiche = _auteur_fiche(meta)\n    if comment is None or comment.file_id != file_id or not peut_voir(user, comment, auteur_fiche):\n        return None, (\"Commentaire introuvable\", 404)\n    if not peut_valider(user, comment, auteur_fiche):\n        if comment.status == \"valide\":\n            return None, (\"Ce commentaire est déjà validé.\", 409)\n        return None, (\"Seul le responsable de ce commentaire peut le valider.\", 403)\n\n    # On revérifie en base : le responsable ne doit pas avoir changé entre-temps.\n    valeurs = {\"status\": \"valide\", \"updated_at\": _maintenant()}\n    filtre = (\n        update(Comment)\n        .where(\n            Comment.id == comment_id,\n            Comment.file_id == file_id,\n            Comment.status == \"pris\",\n        )\n    )\n    if comment.handler_id == user.id:\n        filtre = filtre.where(Comment.handler_id == user.id)\n    elif user.role == \"owner\" and _responsable_actif(comment.handler_id) is None:\n        filtre = filtre.where(Comment.handler_id == comment.handler_id)\n    else:\n        return None, (\"Seul le responsable de ce commentaire peut le valider.\", 403)\n\n    db.session.execute(filtre.values(**valeurs))\n    db.session.commit()\n    db.session.expire_all()\n    comment = db.session.get(Comment, comment_id)\n    if comment is not None and comment.status == \"valide\" and (\n        comment.handler_id == user.id or user.role == \"owner\"\n    ):\n        return {\"commentaire\": _presenter(comment, user, auteur_fiche)}, None\n    return None, (\"Seul le responsable de ce commentaire peut le valider.\", 403)\n");
source("utils/commentaires.py", "retirer", "python", "def retirer(user, file_id, comment_id):\n    \"\"\"Retire le commentaire suivi, une fois la fiche modifiée par le même compte.\"\"\"\n    if not is_uuid(comment_id):\n        return None, (\"Commentaire introuvable\", 404)\n    meta = trouver_fiche(file_id)\n    if meta is None:\n        return None, (\"Fiche introuvable\", 404)\n    comment = db.session.get(Comment, comment_id)\n    auteur_fiche = _auteur_fiche(meta)\n    if comment is None or comment.file_id != file_id or not peut_voir(user, comment, auteur_fiche):\n        return None, (\"Commentaire introuvable\", 404)\n    if comment.handler_id != user.id or not _peut_suivre(user, auteur_fiche):\n        return None, (\"Seul le compte qui suit ce commentaire peut le retirer.\", 403)\n    if not comment.corrected:\n        return None, (\"Modifie la fiche pendant que tu suis ce commentaire, ensuite tu pourras le retirer.\", 403)\n\n    resultat = Comment.query.filter(\n        Comment.id == comment_id,\n        Comment.file_id == file_id,\n        Comment.handler_id == user.id,\n        Comment.corrected.is_(True),\n        Comment.status.in_((\"pris\", \"valide\")),\n    ).delete(synchronize_session=False)\n    db.session.commit()\n    if resultat != 1:\n        return None, (\"Commentaire introuvable\", 404)\n    return {\"message\": \"Commentaire retiré\"}, None\n");
source("utils/dir.py", "list_names", "python", "def list_names(directory, kind):\n    \"\"\"Liste les noms d'enfants directs : « dir » pour les dossiers, « file » pour les fichiers.\"\"\"\n    directory = Path(directory).resolve()\n    base = project_dir(\"matiere\")\n    if directory != base and not directory.is_relative_to(base):\n        return []\n    if not directory.is_dir():\n        return []\n\n    names = []\n    try:\n        for entry in directory.iterdir():\n            if entry.name.startswith(\".\"):\n                continue\n            if entry.is_symlink():\n                continue\n            if kind == \"dir\" and entry.is_dir():\n                names.append(entry.name)\n            elif kind == \"file\" and entry.is_file():\n                names.append(entry.name)\n    except OSError:\n        return []\n    return sorted(names, key=str.lower)\n");
source("utils/dir.py", "child_dir", "python", "def child_dir(parent, name):\n    \"\"\"Sous-dossier direct de parent, ou None si le nom est invalide ou absent.\"\"\"\n    if not segment_ok(name):\n        return None\n    parent = Path(parent).resolve()\n    base = project_dir(\"matiere\")\n    if parent != base and not parent.is_relative_to(base):\n        return None\n\n    candidate = parent / name\n    if candidate.is_symlink() or not candidate.is_dir():\n        return None\n    resolved = candidate.resolve()\n    if resolved.parent != parent or not resolved.is_relative_to(base):\n        return None\n    return resolved\n");
source("utils/dir.py", "find_metadata_path", "python", "def find_metadata_path(file_id):\n    \"\"\"Retrouve le JSON d'une fiche par son UUID.\n\n    S'il existe deux fichiers pour le même id, on ne choisit pas au hasard :\n    on retourne None pour ne pas modifier la mauvaise fiche.\n    \"\"\"\n    if not is_uuid(file_id):\n        return None\n\n    base = project_dir(\"matiere\")\n    found = []\n    for path in base.rglob(file_id + \".json\"):\n        if path.is_symlink():\n            continue\n        resolved = path.resolve()\n        # Profondeur attendue : matiere / matière / classe / spécialité / fichier.json\n        if resolved.parent.parent.parent.parent != base:\n            continue\n        if resolved.is_file() and resolved.is_relative_to(base):\n            found.append(resolved)\n\n    if len(found) != 1:\n        return None\n    return found[0]\n");
source("utils/etoiles.py", "_maintenant", "python", "def _maintenant():\n    return datetime.now(timezone.utc).replace(tzinfo=None)\n");
source("utils/etoiles.py", "compter", "python", "def compter(file_ids):\n    \"\"\"Nombre d'étoiles par fiche. Les identifiants inconnus valent zéro.\"\"\"\n    identifiants = [file_id for file_id in file_ids if is_uuid(file_id)]\n    if not identifiants:\n        return {}\n    rows = (\n        db.session.query(Star.file_id, db.func.count(Star.id))\n        .filter(Star.file_id.in_(identifiants))\n        .group_by(Star.file_id)\n        .all()\n    )\n    return {file_id: nombre for file_id, nombre in rows}\n");
source("utils/etoiles.py", "deja_etoilees", "python", "def deja_etoilees(user_id, file_ids):\n    \"\"\"Identifiants que ce compte a déjà étoilés, parmi la liste demandée.\"\"\"\n    identifiants = [file_id for file_id in file_ids if is_uuid(file_id)]\n    if not user_id or not identifiants:\n        return set()\n    rows = (\n        Star.query.filter(Star.user_id == user_id, Star.file_id.in_(identifiants))\n        .with_entities(Star.file_id)\n        .all()\n    )\n    return {file_id for (file_id,) in rows}\n");
source("utils/etoiles.py", "annoter", "python", "def annoter(fiches, user):\n    \"\"\"Ajoute etoiles et etoile_moi sur des dictionnaires déjà publics.\"\"\"\n    identifiants = [fiche.get(\"id\") for fiche in fiches if is_uuid(fiche.get(\"id\"))]\n    comptes = compter(identifiants)\n    miennes = deja_etoilees(user.id, identifiants) if user is not None else set()\n    for fiche in fiches:\n        identifiant = fiche.get(\"id\")\n        fiche[\"etoiles\"] = int(comptes.get(identifiant, 0))\n        fiche[\"etoile_moi\"] = identifiant in miennes\n    return fiches\n");
source("utils/etoiles.py", "nombre_pour", "python", "def nombre_pour(file_id):\n    return int(compter([file_id]).get(file_id, 0))\n");
source("utils/etoiles.py", "basculer", "python", "def basculer(user, file_id):\n    \"\"\"Pose ou retire l'étoile du compte. (données, None) ou (None, (message, code)).\"\"\"\n    if trouver_fiche(file_id) is None:\n        return None, (\"Fiche introuvable\", 404)\n\n    existante = Star.query.filter_by(user_id=user.id, file_id=file_id).first()\n    if existante is not None:\n        db.session.delete(existante)\n        db.session.commit()\n        return {\"etoile\": False, \"etoiles\": nombre_pour(file_id)}, None\n\n    db.session.add(Star(user_id=user.id, file_id=file_id, created_at=_maintenant()))\n    try:\n        db.session.commit()\n    except IntegrityError:\n        db.session.rollback()\n        return {\"etoile\": True, \"etoiles\": nombre_pour(file_id)}, None\n    return {\"etoile\": True, \"etoiles\": nombre_pour(file_id)}, None\n");
source("utils/etoiles.py", "_courte", "python", "def _courte(meta, etoiles):\n    vue = vue_publique(meta)\n    return {\n        \"id\": vue[\"id\"],\n        \"titre\": vue[\"title\"] or \"Sans titre\",\n        \"auteur\": vue[\"author\"],\n        \"matiere\": vue[\"matiere\"],\n        \"classe\": vue[\"classe\"],\n        \"specialite\": vue[\"specialite\"],\n        \"etoiles\": etoiles,\n    }\n");
source("utils/etoiles.py", "classement", "python", "def classement():\n    \"\"\"La fiche la plus étoilée, et les mieux étoilées de chaque matière.\n\n    Une matière n'apparaît que si au moins une de ses fiches a une étoile.\n    En cas d'égalité, on garde toutes les fiches à ce maximum.\n    Le classement global n'en retient qu'une : le titre, puis l'identifiant.\n    \"\"\"\n    fiches = toutes_les_fiches()\n    comptes = compter([fiche[\"id\"] for fiche in fiches])\n    total = sum(comptes.values())\n    par_matiere = {}\n    for meta in fiches:\n        etoiles = int(comptes.get(meta[\"id\"], 0))\n        if etoiles <= 0:\n            continue\n        par_matiere.setdefault(meta.get(\"matiere\") or \"\", []).append((meta, etoiles))\n\n    groupes = []\n    gagnantes = []\n    for matiere in sorted(par_matiere):\n        lignes = par_matiere[matiere]\n        meilleur = max(etoiles for _meta, etoiles in lignes)\n        tete = [\n            _courte(meta, etoiles)\n            for meta, etoiles in lignes\n            if etoiles == meilleur\n        ]\n        tete.sort(key=lambda fiche: ((fiche[\"titre\"] or \"\").casefold(), fiche[\"id\"]))\n        groupes.append({\"matiere\": matiere, \"fiches\": tete})\n        gagnantes.extend(tete)\n\n    gagnantes.sort(key=lambda fiche: (-fiche[\"etoiles\"], (fiche[\"titre\"] or \"\").casefold(), fiche[\"id\"]))\n    return {\n        \"total\": total,\n        \"plus_etoilee\": gagnantes[0] if gagnantes else None,\n        \"par_matiere\": groupes,\n    }\n");
source("utils/files.py", "location_cache", "python", "def location_cache(file_id, filename, subject, school_class, speciality):\n    \"\"\"Rappel minimal stocké dans le compte. Il ne contient pas le contenu du fichier.\"\"\"\n    return {\n        \"id\": file_id,\n        \"filename\": filename,\n        \"matiere\": subject,\n        \"classe\": school_class,\n        \"specialite\": speciality,\n    }\n");
source("utils/files.py", "public_metadata", "python", "def public_metadata(metadata):\n    \"\"\"Champs montrés à l'écran. Le nom interne du disque n'est pas nécessaire à la page.\"\"\"\n    return {\n        \"id\": metadata.get(\"id\"),\n        \"title\": metadata.get(\"title\") or \"\",\n        \"author\": metadata.get(\"author\") or \"\",\n        \"desc\": metadata.get(\"desc\") or \"\",\n        \"original_filename\": metadata.get(\"original_filename\") or \"\",\n        \"matiere\": metadata.get(\"matiere\") or \"\",\n        \"classe\": metadata.get(\"classe\") or \"\",\n        \"specialite\": metadata.get(\"specialite\") or \"\",\n    }\n");
source("utils/files.py", "read_metadata", "python", "def read_metadata(path):\n    \"\"\"Charge un JSON de fiche et vérifie qu'il a un id valide.\"\"\"\n    data = load_json_object(path)\n    if not isinstance(data, dict) or not is_uuid(data.get(\"id\")):\n        return None\n    return data\n");
source("utils/files.py", "_remove_file", "python", "def _remove_file(path):\n    \"\"\"Supprime un fichier s'il existe. Une erreur disque est journalisée, pas montrée brute.\"\"\"\n    try:\n        if path is not None and path.is_file():\n            path.unlink()\n    except OSError:\n        current_app.logger.exception(\"Suppression impossible : %s\", path)\n");
source("utils/files.py", "_propagate_downloads", "python", "def _propagate_downloads(file_id, cache):\n    \"\"\"Met à jour le rappel de ceux qui ont déjà téléchargé cette fiche.\"\"\"\n    for person in User.query.all():\n        downloads = dict(person.download_metadatas or {})\n        if file_id not in downloads:\n            continue\n        downloads[file_id] = cache\n        person.download_metadatas = downloads\n        flag_modified(person, \"download_metadatas\")\n");
source("utils/files.py", "files_from_cache", "python", "def files_from_cache(file_ids, cache):\n    \"\"\"Reconstruit les fiches visibles à partir des id mémorisés sur le compte.\"\"\"\n    visible = []\n    for file_id in file_ids or []:\n        if not is_uuid(file_id):\n            continue\n        hint = (cache or {}).get(file_id) or {}\n        category = valid_category(hint.get(\"matiere\"), hint.get(\"classe\"), hint.get(\"specialite\"))\n        path = metadata_path(category, file_id) if category is not None else None\n        if path is None or not path.is_file():\n            path = find_metadata_path(file_id)\n        if path is None or not path.is_file():\n            continue\n        metadata = read_metadata(path)\n        if metadata is None or metadata.get(\"id\") != file_id:\n            continue\n        visible.append(public_metadata(metadata))\n    return visible\n");
source("utils/files.py", "owner_of", "python", "def owner_of(file_id):\n    \"\"\"Retrouve le compte auteur d'une fiche. (compte, None) ou (None, erreur).\"\"\"\n    if not is_uuid(file_id):\n        return None, error_response(\"Identifiant de fiche invalide\", 400)\n\n    path = find_metadata_path(file_id)\n    if path is None:\n        return None, error_response(\"Fiche introuvable\", 404)\n\n    metadata = read_metadata(path)\n    author = metadata.get(\"author\") if metadata else None\n    if not isinstance(author, str) or not author:\n        return None, error_response(\"Auteur introuvable\", 404)\n\n    owner = User.query.filter_by(username=author).first()\n    if owner is None or file_id not in (owner.uploaded_files or []):\n        return None, error_response(\"Propriétaire introuvable\", 404)\n    return owner, None\n");
source("utils/files.py", "store_upload", "python", "def store_upload(user, subject, school_class, speciality, storage, title, description):\n    \"\"\"Enregistre une nouvelle fiche au nom du compte connecté.\n\n    L'auteur est toujours l'identifiant du compte. La valeur envoyée par le\n    formulaire est ignorée, pour qu'on ne puisse pas signer une fiche à la place\n    de quelqu'un d'autre.\n    \"\"\"\n    category = valid_category(subject, school_class, speciality)\n    if category is None:\n        return jsonify({\"error\": \"Catégorie introuvable\"}), 404\n\n    clean_title = clean_text(title, 120)\n    clean_description = clean_text(description, 2000)\n    if not clean_title or not clean_description:\n        return jsonify({\n            \"error\": \"Le titre et la description sont obligatoires (120 et 2000 caractères maximum).\"\n        }), 400\n\n    if storage is None or not storage.filename:\n        return jsonify({\"error\": \"Aucun fichier sélectionné\"}), 400\n\n    file_id = str(uuid.uuid4())\n    filename = stored_name(file_id, storage.filename)\n    if not filename:\n        return jsonify({\n            \"error\": \"Type de fichier non autorisé. Utilise un PDF, une image, un document ou un zip.\"\n        }), 400\n\n    destination = upload_path(filename)\n    meta_path = metadata_path(category, file_id)\n    if destination is None or meta_path is None:\n        return jsonify({\"error\": \"Chemin de stockage invalide\"}), 400\n\n    try:\n        storage.save(destination)\n    except OSError:\n        current_app.logger.exception(\"Échec d'écriture du fichier\")\n        return jsonify({\"error\": \"Enregistrement impossible\"}), 500\n\n    if not destination.is_file() or destination.stat().st_size <= 0:\n        _remove_file(destination)\n        return jsonify({\"error\": \"Le fichier est vide\"}), 400\n\n    metadata = {\n        \"id\": file_id,\n        \"title\": clean_title,\n        \"author\": user.username,\n        \"desc\": clean_description,\n        \"filename\": filename,\n        \"original_filename\": secure_filename(storage.filename),\n        \"matiere\": subject,\n        \"classe\": school_class,\n        \"specialite\": speciality,\n    }\n\n    try:\n        save_json_file(meta_path, metadata)\n        uploaded = list(user.uploaded_files or [])\n        uploaded.append(file_id)\n        user.uploaded_files = uploaded\n        flag_modified(user, \"uploaded_files\")\n        uploaded_meta = dict(user.uploaded_metadatas or {})\n        uploaded_meta[file_id] = location_cache(file_id, filename, subject, school_class, speciality)\n        user.uploaded_metadatas = uploaded_meta\n        flag_modified(user, \"uploaded_metadatas\")\n        db.session.commit()\n    except Exception:\n        db.session.rollback()\n        current_app.logger.exception(\"Échec d'enregistrement de la fiche\")\n        _remove_file(destination)\n        _remove_file(meta_path)\n        return jsonify({\"error\": \"Enregistrement impossible\"}), 500\n\n    return jsonify({\"message\": \"Fiche publiée\", \"metadata\": metadata}), 201\n");
source("utils/files.py", "_noter_suivi", "python", "def _noter_suivi(acteur, file_id):\n    \"\"\"Le compte qui suit un commentaire vient de modifier la fiche : il pourra le retirer.\"\"\"\n    if acteur is None or not is_uuid(file_id):\n        return\n    Comment.query.filter(\n        Comment.file_id == file_id,\n        Comment.handler_id == acteur.id,\n        Comment.status.in_((\"pris\", \"valide\")),\n    ).update({Comment.corrected: True}, synchronize_session=False)\n");
source("utils/files.py", "update_file", "python", "def update_file(owner, file_id, form, storage, acteur=None):\n    \"\"\"Modifie le texte, la catégorie, et éventuellement le fichier d'une fiche.\n\n    acteur est le compte qui enregistre. C'est lui, et pas l'auteur affiché,\n    qui débloque le retrait des commentaires qu'il suit.\n    \"\"\"\n    if not is_uuid(file_id):\n        return jsonify({\"error\": \"Identifiant de fiche invalide\"}), 400\n    if file_id not in (owner.uploaded_files or []):\n        return jsonify({\"error\": \"Cette fiche ne figure pas dans les envois de ce compte\"}), 403\n\n    subject = form.get(\"matiere\")\n    school_class = form.get(\"classe\")\n    speciality = form.get(\"specialite\")\n    category = valid_category(subject, school_class, speciality)\n    if category is None:\n        return jsonify({\"error\": \"Catégorie introuvable\"}), 404\n\n    clean_title = clean_text(form.get(\"title\"), 120)\n    clean_description = clean_text(form.get(\"desc\"), 2000)\n    if not clean_title or not clean_description:\n        return jsonify({\"error\": \"Le titre et la description sont obligatoires.\"}), 400\n\n    old_meta_path = find_metadata_path(file_id)\n    if old_meta_path is None:\n        return jsonify({\"error\": \"Métadonnées introuvables\"}), 404\n\n    old_metadata = read_metadata(old_meta_path)\n    if old_metadata is None or old_metadata.get(\"id\") != file_id:\n        return jsonify({\"error\": \"Métadonnées invalides\"}), 404\n    if old_metadata.get(\"author\") != owner.username:\n        return jsonify({\"error\": \"Le propriétaire de la fiche ne correspond pas\"}), 403\n\n    old_stored = old_metadata.get(\"filename\")\n    old_original = old_metadata.get(\"original_filename\")\n    if not valid_stored_name(file_id, old_stored) or not isinstance(old_original, str) or not old_original:\n        return jsonify({\"error\": \"Fichier stocké invalide\"}), 400\n\n    old_file = upload_path(old_stored)\n    if old_file is None:\n        return jsonify({\"error\": \"Fichier stocké invalide\"}), 400\n\n    new_file = None\n    new_stored = old_stored\n    new_original = secure_filename(old_original) or \"fiche\"\n    if storage is not None and storage.filename:\n        candidate = stored_name(file_id, storage.filename)\n        # Même nom qu'avant : on en calcule un autre pour pouvoir revenir en arrière.\n        if candidate and candidate == old_stored:\n            candidate = stored_name(file_id, uuid.uuid4().hex + \"_\" + storage.filename)\n        if not candidate:\n            return jsonify({\"error\": \"Type de fichier non autorisé.\"}), 400\n        new_file = upload_path(candidate)\n        if new_file is None:\n            return jsonify({\"error\": \"Chemin de stockage invalide\"}), 400\n        new_stored = candidate\n        new_original = secure_filename(storage.filename)\n\n    new_meta_path = metadata_path(category, file_id)\n    if new_meta_path is None:\n        return jsonify({\"error\": \"Chemin de métadonnées invalide\"}), 400\n\n    metadata = {\n        \"id\": file_id,\n        \"title\": clean_title,\n        \"author\": owner.username,\n        \"desc\": clean_description,\n        \"filename\": new_stored,\n        \"original_filename\": new_original,\n        \"matiere\": subject,\n        \"classe\": school_class,\n        \"specialite\": speciality,\n    }\n    cache = location_cache(file_id, new_stored, subject, school_class, speciality)\n\n    try:\n        if new_file is not None:\n            storage.save(new_file)\n            if not new_file.is_file() or new_file.stat().st_size <= 0:\n                _remove_file(new_file)\n                return jsonify({\"error\": \"Le fichier est vide\"}), 400\n        save_json_file(new_meta_path, metadata)\n        uploaded_meta = dict(owner.uploaded_metadatas or {})\n        uploaded_meta[file_id] = cache\n        owner.uploaded_metadatas = uploaded_meta\n        flag_modified(owner, \"uploaded_metadatas\")\n        _propagate_downloads(file_id, cache)\n        _noter_suivi(acteur, file_id)\n        db.session.commit()\n    except Exception:\n        db.session.rollback()\n        current_app.logger.exception(\"Échec de mise à jour de la fiche\")\n        if new_meta_path != old_meta_path and new_meta_path.exists():\n            _remove_file(new_meta_path)\n        elif old_meta_path.exists():\n            save_json_file(old_meta_path, old_metadata)\n        if new_file is not None and new_file != old_file:\n            _remove_file(new_file)\n        return jsonify({\"error\": \"Mise à jour impossible\"}), 500\n\n    if old_meta_path != new_meta_path:\n        _remove_file(old_meta_path)\n    if new_file is not None and old_file != new_file:\n        _remove_file(old_file)\n\n    return jsonify({\"message\": \"Fiche mise à jour\"}), 200\n");
source("utils/files.py", "remove_file", "python", "def remove_file(owner, file_id):\n    \"\"\"Retire la fiche du compte, puis du disque.\"\"\"\n    if not is_uuid(file_id):\n        return jsonify({\"error\": \"Identifiant de fiche invalide\"}), 400\n    if file_id not in (owner.uploaded_files or []):\n        return jsonify({\"error\": \"Cette fiche ne figure pas dans les envois de ce compte\"}), 403\n\n    meta_path = find_metadata_path(file_id)\n    if meta_path is None:\n        return jsonify({\"error\": \"Métadonnées introuvables\"}), 404\n\n    metadata = read_metadata(meta_path)\n    if metadata is None or metadata.get(\"author\") != owner.username:\n        return jsonify({\"error\": \"Le propriétaire de la fiche ne correspond pas\"}), 403\n\n    stored = metadata.get(\"filename\")\n    if not valid_stored_name(file_id, stored):\n        return jsonify({\"error\": \"Fichier stocké invalide\"}), 400\n    file_path = upload_path(stored)\n    if file_path is None:\n        return jsonify({\"error\": \"Fichier stocké invalide\"}), 400\n\n    # Même transaction que le compte : une étoile ou un commentaire ne survit pas à la fiche.\n    Star.query.filter(Star.file_id == file_id).delete(synchronize_session=False)\n    Comment.query.filter(Comment.file_id == file_id).delete(synchronize_session=False)\n\n    owner.uploaded_files = [item for item in (owner.uploaded_files or []) if item != file_id]\n    flag_modified(owner, \"uploaded_files\")\n    uploaded_meta = dict(owner.uploaded_metadatas or {})\n    uploaded_meta.pop(file_id, None)\n    owner.uploaded_metadatas = uploaded_meta\n    flag_modified(owner, \"uploaded_metadatas\")\n\n    try:\n        db.session.commit()\n    except Exception:\n        db.session.rollback()\n        current_app.logger.exception(\"Échec de suppression en base\")\n        return jsonify({\"error\": \"Suppression impossible\"}), 500\n\n    _remove_file(file_path)\n    _remove_file(meta_path)\n    return jsonify({\"message\": \"Fiche supprimée\"}), 200\n");
source("utils/files.py", "resolve_download", "python", "def resolve_download(subject, school_class, speciality, file_id):\n    \"\"\"Vérifie la fiche demandée et retourne (nom interne, nom d'origine, rappel).\"\"\"\n    if not is_uuid(file_id):\n        return None, (jsonify({\"error\": \"Identifiant de fiche invalide\"}), 400)\n\n    category = valid_category(subject, school_class, speciality)\n    if category is None:\n        return None, (jsonify({\"error\": \"Catégorie introuvable\"}), 404)\n\n    path = metadata_path(category, file_id)\n    if path is None or not path.is_file():\n        return None, (jsonify({\"error\": \"Fiche introuvable\"}), 404)\n\n    metadata = read_metadata(path)\n    if metadata is None or metadata.get(\"id\") != file_id:\n        return None, (jsonify({\"error\": \"Métadonnées invalides\"}), 404)\n    if (\n        metadata.get(\"matiere\") != subject\n        or metadata.get(\"classe\") != school_class\n        or metadata.get(\"specialite\") != speciality\n    ):\n        return None, (jsonify({\"error\": \"La fiche ne correspond pas à cette catégorie\"}), 404)\n\n    stored = metadata.get(\"filename\")\n    if not valid_stored_name(file_id, stored):\n        return None, (jsonify({\"error\": \"Fichier stocké invalide\"}), 404)\n    if upload_path(stored) is None or not upload_path(stored).is_file():\n        return None, (jsonify({\"error\": \"Fichier introuvable\"}), 404)\n\n    original = secure_filename(metadata.get(\"original_filename\") or \"\") or \"fiche\"\n    cache = location_cache(file_id, stored, subject, school_class, speciality)\n    return (stored, original, cache), None\n");
source("utils/files.py", "remember_download", "python", "def remember_download(user, file_id, cache):\n    \"\"\"Ajoute la fiche à l'historique si un compte est connecté.\"\"\"\n    if user is None or user.is_ban:\n        return\n    downloads = list(user.download_ids or [])\n    if file_id not in downloads:\n        downloads.append(file_id)\n        user.download_ids = downloads\n        flag_modified(user, \"download_ids\")\n    metas = dict(user.download_metadatas or {})\n    metas[file_id] = cache\n    user.download_metadatas = metas\n    flag_modified(user, \"download_metadatas\")\n    db.session.commit()\n");
source("utils/http.py", "wants_html", "python", "def wants_html():\n    \"\"\"Vrai quand c'est une navigation de page, pas un appel de l'API.\"\"\"\n    if request.method != \"GET\":\n        return False\n    # Ces préfixes sont toujours des données, même si on les ouvre dans la barre d'adresse.\n    if request.path.startswith((\"/info\", \"/upload\", \"/download\")):\n        return False\n    accept = request.headers.get(\"Accept\", \"\")\n    return \"text/html\" in accept\n");
source("utils/http.py", "error_response", "python", "def error_response(message, status):\n    \"\"\"Erreur affichable : page simple, ou JSON pour le script de la page.\"\"\"\n    if wants_html():\n        return render_template(\"erreur.html\", message=message), status\n    return jsonify({\"error\": message}), status\n");
source("utils/http.py", "safe_next_url", "python", "def safe_next_url(value, default=\"/accueil\"):\n    \"\"\"N'accepte qu'un chemin interne. Bloque les redirections vers un autre site.\"\"\"\n    if not isinstance(value, str):\n        return default\n    if not value.startswith(\"/\") or value.startswith(\"//\"):\n        return default\n    if any(char in value for char in (\"\\\\\", \"\\x00\", \"\\r\", \"\\n\", \" \")):\n        return default\n    return value\n");
source("utils/http.py", "redirect_to_login", "python", "def redirect_to_login():\n    \"\"\"Envoie vers la page de connexion en mémorisant la page demandée.\"\"\"\n    target = safe_next_url(request.path, \"/accueil\")\n    return redirect(\"/auth/login-page?next=\" + quote(target, safe=\"/\"))\n");
source("utils/json_utils.py", "load_json_object", "python", "def load_json_object(file_path):\n    \"\"\"Retourne un objet JSON, ou None si le fichier est illisible ou n'est pas un objet.\"\"\"\n    try:\n        with open(file_path, \"r\", encoding=\"utf-8\") as handle:\n            data = json.load(handle)\n    except (OSError, UnicodeError, json.JSONDecodeError):\n        return None\n    if not isinstance(data, dict):\n        return None\n    return data\n");
source("utils/json_utils.py", "load_json_file", "python", "def load_json_file(file_path):\n    \"\"\"Ancienne forme : un dictionnaire vide quand la lecture échoue.\"\"\"\n    data = load_json_object(file_path)\n    return data if data is not None else {}\n");
source("utils/json_utils.py", "save_json_file", "python", "def save_json_file(file_path, data):\n    \"\"\"Écrit le JSON en UTF-8 et remplace l'ancien fichier seulement à la fin.\"\"\"\n    path = Path(file_path)\n    temporary = path.with_suffix(path.suffix + \".tmp\")\n    with open(temporary, \"w\", encoding=\"utf-8\") as handle:\n        json.dump(data, handle, indent=4, ensure_ascii=False)\n        handle.flush()\n        os.fsync(handle.fileno())\n    os.replace(temporary, path)\n");
source("utils/presence.py", "_maintenant", "python", "def _maintenant():\n    return datetime.now(timezone.utc).replace(tzinfo=None)\n");
source("utils/presence.py", "_depuis_claim", "python", "def _depuis_claim(valeur):\n    \"\"\"Convertit l'expiration du jeton en datetime UTC naïf, comme le reste de la base.\"\"\"\n    if isinstance(valeur, datetime):\n        if valeur.tzinfo is not None:\n            return valeur.astimezone(timezone.utc).replace(tzinfo=None)\n        return valeur\n    if isinstance(valeur, (int, float)):\n        return datetime.fromtimestamp(valeur, timezone.utc).replace(tzinfo=None)\n    return _maintenant() + timedelta(hours=8)\n");
source("utils/presence.py", "_iso", "python", "def _iso(moment):\n    if moment is None:\n        return None\n    if moment.tzinfo is not None:\n        moment = moment.astimezone(timezone.utc).replace(tzinfo=None)\n    return moment.isoformat(timespec=\"seconds\") + \"Z\"\n");
source("utils/presence.py", "_agent", "python", "def _agent(valeur):\n    if not isinstance(valeur, str):\n        return \"\"\n    propre = valeur.replace(\"\\r\", \" \").replace(\"\\n\", \" \").strip()\n    return propre[:240]\n");
source("utils/presence.py", "ouvrir_presence", "python", "def ouvrir_presence(user_id, token, user_agent):\n    \"\"\"Enregistre le jeton qui vient d'être émis.\"\"\"\n    claims = decode_token(token)\n    jti = claims.get(\"jti\")\n    if not isinstance(jti, str) or not jti:\n        return\n    maintenant = _maintenant()\n    db.session.add(Presence(\n        jti=jti,\n        user_id=user_id,\n        created_at=maintenant,\n        last_seen=maintenant,\n        expires_at=_depuis_claim(claims.get(\"exp\")),\n        user_agent=_agent(user_agent),\n        revoked=False,\n    ))\n    db.session.commit()\n");
source("utils/presence.py", "fermer_presence", "python", "def fermer_presence(jti):\n    \"\"\"Marque la session comme fermée. Un jeton déjà inconnu est ignoré.\"\"\"\n    if not jti:\n        return\n    ligne = db.session.get(Presence, jti)\n    if ligne is None or ligne.revoked:\n        return\n    ligne.revoked = True\n    ligne.last_seen = _maintenant()\n    db.session.commit()\n");
source("utils/presence.py", "est_revoquee", "python", "def est_revoquee(jti):\n    \"\"\"Vrai seulement si cette session a été fermée explicitement.\n\n    Les jetons émis avant ce suivi n'ont pas de ligne : ils restent valables\n    jusqu'à leur expiration, le ban étant vérifié à part.\n    \"\"\"\n    if not jti:\n        return False\n    ligne = db.session.get(Presence, jti)\n    return ligne is not None and bool(ligne.revoked)\n");
source("utils/presence.py", "toucher_presence", "python", "def toucher_presence(jti):\n    \"\"\"Met à jour la dernière activité, au plus une fois toutes les 30 secondes.\"\"\"\n    if not jti:\n        return\n    if db.session.new or db.session.dirty or db.session.deleted:\n        return\n    ligne = db.session.get(Presence, jti)\n    if ligne is None or ligne.revoked:\n        return\n    maintenant = _maintenant()\n    if ligne.last_seen and (maintenant - ligne.last_seen).total_seconds() < 30:\n        return\n    ligne.last_seen = maintenant\n    db.session.commit()\n");
source("utils/presence.py", "resume_sessions", "python", "def resume_sessions():\n    \"\"\"Sessions encore valides, et celles fermées mais pas encore expirées.\"\"\"\n    maintenant = _maintenant()\n    Presence.query.filter(Presence.expires_at < maintenant).delete(synchronize_session=False)\n    db.session.commit()\n\n    lignes = (\n        db.session.query(Presence, User)\n        .outerjoin(User, User.id == Presence.user_id)\n        .filter(Presence.expires_at >= maintenant)\n        .order_by(Presence.last_seen.desc())\n        .all()\n    )\n\n    seuil = maintenant - FENETRE_EN_LIGNE\n    liste = []\n    personnes = set()\n    en_ligne = 0\n    deconnectees = 0\n    for presence, user in lignes:\n        if presence.revoked:\n            deconnectees += 1\n            continue\n        suspendu = user is None or bool(user.is_ban)\n        recent = presence.last_seen is not None and presence.last_seen >= seuil\n        if user is not None and not suspendu:\n            personnes.add(user.id)\n            if recent:\n                en_ligne += 1\n        liste.append({\n            \"username\": user.username if user is not None else \"compte supprimé\",\n            \"nom\": f\"{user.name} {user.surname}\".strip() if user is not None else \"Compte supprimé\",\n            \"role\": user.role if user is not None else \"\",\n            \"suspendu\": suspendu,\n            \"depuis\": _iso(presence.created_at),\n            \"vu\": _iso(presence.last_seen),\n            \"expire\": _iso(presence.expires_at),\n            \"agent\": presence.user_agent or \"\",\n            \"en_ligne\": bool(recent and not suspendu),\n        })\n\n    return {\n        \"ouvertes\": len(liste),\n        \"personnes\": len(personnes),\n        \"en_ligne\": en_ligne,\n        \"deconnectees\": deconnectees,\n        \"liste\": liste,\n    }\n");
source("utils/recherche.py", "_contient", "python", "def _contient(valeur, aiguille):\n    return aiguille.casefold() in (valeur or \"\").casefold()\n");
source("utils/recherche.py", "_entier", "python", "def _entier(valeur, plafond):\n    if valeur is None or valeur == \"\":\n        return None, None\n    if isinstance(valeur, str):\n        valeur = valeur.strip()\n    if not isinstance(valeur, str) or not valeur.isdigit():\n        return None, \"Le nombre d'étoiles minimum est invalide.\"\n    nombre = int(valeur)\n    if nombre > plafond:\n        return None, \"Le nombre d'étoiles minimum est trop grand.\"\n    return nombre, None\n");
source("utils/recherche.py", "chercher_fiches", "python", "def chercher_fiches(args, user):\n    \"\"\"Retourne (données, None) ou (None, (message, code)).\"\"\"\n    q = (args.get(\"q\") or \"\").strip()\n    matiere = (args.get(\"matiere\") or \"\").strip()\n    classe = (args.get(\"classe\") or \"\").strip()\n    specialite = (args.get(\"specialite\") or \"\").strip()\n    auteur = (args.get(\"auteur\") or \"\").strip()\n    if q and clean_text(q, 120) is None:\n        return None, (\"La recherche est vide ou trop longue.\", 400)\n    for nom, valeur in ((\"matière\", matiere), (\"classe\", classe), (\"spécialité\", specialite)):\n        if valeur and not segment_ok(valeur):\n            return None, (f\"Cette {nom} est invalide.\", 400)\n    if auteur and clean_text(auteur, 80) is None:\n        return None, (\"Le nom d'auteur est invalide.\", 400)\n    minimum, erreur = _entier(args.get(\"etoiles_min\"), 1_000_000)\n    if erreur:\n        return None, (erreur, 400)\n    if not any((q, matiere, classe, specialite, auteur, minimum not in (None, 0))):\n        return None, (\"Indique au moins un critère.\", 400)\n\n    vues = []\n    for meta in toutes_les_fiches():\n        vue = vue_publique(meta)\n        if matiere and vue[\"matiere\"] != matiere:\n            continue\n        if classe and vue[\"classe\"] != classe:\n            continue\n        if specialite and vue[\"specialite\"] != specialite:\n            continue\n        if auteur and not _contient(vue[\"author\"], auteur):\n            continue\n        if q and not any(\n            _contient(vue[champ], q)\n            for champ in (\"title\", \"desc\", \"author\", \"original_filename\", \"matiere\", \"classe\", \"specialite\")\n        ):\n            continue\n        vues.append(vue)\n\n    annoter(vues, user)\n    if minimum:\n        vues = [vue for vue in vues if vue[\"etoiles\"] >= minimum]\n    vues.sort(key=lambda vue: (-vue[\"etoiles\"], (vue[\"title\"] or \"\").casefold(), vue[\"id\"]))\n    tronque = len(vues) > LIMITE_FICHES\n    return {\"fiches\": vues[:LIMITE_FICHES], \"tronque\": tronque}, None\n");
source("utils/recherche.py", "chercher_comptes", "python", "def chercher_comptes(args):\n    \"\"\"Retourne (données, None) ou (None, (message, code)).\"\"\"\n    q = (args.get(\"q\") or \"\").strip()\n    role = (args.get(\"role\") or \"\").strip()\n    etat = (args.get(\"etat\") or \"\").strip()\n    if q and clean_text(q, 80) is None:\n        return None, (\"La recherche est vide ou trop longue.\", 400)\n    if role and role not in ROLES:\n        return None, (\"Rôle inconnu.\", 400)\n    if etat and etat not in (\"actif\", \"suspendu\"):\n        return None, (\"État inconnu.\", 400)\n    if not any((q, role, etat)):\n        return None, (\"Indique au moins un critère.\", 400)\n\n    trouvés = []\n    for compte in User.query.order_by(User.username.asc()).all():\n        if role and compte.role != role:\n            continue\n        if etat == \"actif\" and compte.is_ban:\n            continue\n        if etat == \"suspendu\" and not compte.is_ban:\n            continue\n        if q and not any(_contient(getattr(compte, champ), q) for champ in (\"username\", \"name\", \"surname\")):\n            continue\n        trouvés.append(compte)\n\n    tronque = len(trouvés) > LIMITE_COMPTES\n    profils = [public_profile(compte, include_status=True) for compte in trouvés[:LIMITE_COMPTES]]\n    return {\"comptes\": profils, \"tronque\": tronque}, None\n");
source("utils/security.py", "segment_ok", "python", "def segment_ok(name):\n    \"\"\"Vrai si le nom peut être un dossier de matière, de classe ou de spécialité.\"\"\"\n    return isinstance(name, str) and _SEGMENT.fullmatch(name) is not None\n");
source("utils/security.py", "is_uuid", "python", "def is_uuid(value):\n    \"\"\"Vrai uniquement pour un UUID version 4 écrit en minuscules, comme ceux que l'on crée.\"\"\"\n    if not isinstance(value, str):\n        return False\n    try:\n        parsed = uuid.UUID(value)\n    except (ValueError, AttributeError, TypeError):\n        return False\n    return parsed.version == 4 and str(parsed) == value\n");
source("utils/security.py", "clean_text", "python", "def clean_text(value, max_length):\n    \"\"\"Nettoie un titre ou une description. Retourne None si le texte est inutilisable.\"\"\"\n    if not isinstance(value, str):\n        return None\n    value = value.replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\").strip()\n    if not value or len(value) > max_length or \"\\x00\" in value:\n        return None\n    return value\n");
source("utils/security.py", "extension_allowed", "python", "def extension_allowed(filename):\n    \"\"\"Vrai si le suffixe du fichier est dans la liste autorisée.\"\"\"\n    if not isinstance(filename, str):\n        return False\n    return Path(filename).suffix.lower() in EXTENSIONS_AUTORISEES\n");
source("utils/security.py", "valid_stored_name", "python", "def valid_stored_name(file_id, stored_name):\n    \"\"\"Le nom interne doit rester un simple fichier du dossier uploads, préfixé par l'id.\"\"\"\n    if not is_uuid(file_id) or not isinstance(stored_name, str):\n        return False\n    if stored_name != Path(stored_name).name:\n        return False\n    if \"/\" in stored_name or \"\\\\\" in stored_name or \"\\x00\" in stored_name:\n        return False\n    # secure_filename retire les suites du type « ../ ». S'il modifie le nom, on le refuse.\n    if secure_filename(stored_name) != stored_name:\n        return False\n    if not stored_name.startswith(file_id + \"_\"):\n        return False\n    return extension_allowed(stored_name)\n");
source("utils/security.py", "stored_name", "python", "def stored_name(file_id, original_filename):\n    \"\"\"Construit le nom unique « <uuid>_<nom sûr> », ou None si le type est interdit.\"\"\"\n    cleaned = secure_filename(original_filename or \"\")\n    if not cleaned or not extension_allowed(cleaned):\n        return None\n    suffix = Path(cleaned).suffix.lower()\n    if len(cleaned) > 100:\n        cleaned = cleaned[: 100 - len(suffix)] + suffix\n    name = f\"{file_id}_{cleaned}\"\n    if not valid_stored_name(file_id, name):\n        return None\n    return name\n");
source("utils/security.py", "project_dir", "python", "def project_dir(folder_name):\n    \"\"\"Dossier racine du projet, résolu, pour comparer les chemins réels.\"\"\"\n    return Path(folder_name).resolve()\n");
source("utils/security.py", "valid_category", "python", "def valid_category(subject, school_class, speciality):\n    \"\"\"Retourne le dossier matiere/<matière>/<classe>/<spécialité> s'il existe vraiment.\n\n    Un lien symbolique est refusé : après résolution, il pourrait pointer\n    en dehors de l'arborescence prévue.\n    \"\"\"\n    if not all(segment_ok(part) for part in (subject, school_class, speciality)):\n        return None\n\n    base = project_dir(\"matiere\")\n    current = base\n    for part in (subject, school_class, speciality):\n        current = current / part\n        if current.is_symlink() or not current.is_dir():\n            return None\n\n    resolved = current.resolve()\n    # Trois niveaux exactement : matière, classe, spécialité.\n    if resolved.parent.parent.parent != base:\n        return None\n    if not resolved.is_relative_to(base):\n        return None\n    return resolved\n");
source("utils/security.py", "metadata_path", "python", "def metadata_path(category_dir, file_id):\n    \"\"\"Chemin du JSON de fiche, sans pouvoir remonter d'un dossier.\"\"\"\n    if category_dir is None or not is_uuid(file_id):\n        return None\n    path = (category_dir / f\"{file_id}.json\").resolve()\n    if path.parent != category_dir.resolve():\n        return None\n    return path\n");
source("utils/security.py", "upload_path", "python", "def upload_path(stored):\n    \"\"\"Chemin du fichier dans uploads/, ou None si le nom tente de s'en échapper.\"\"\"\n    if not isinstance(stored, str) or stored != Path(stored).name:\n        return None\n    base = project_dir(\"uploads\")\n    base.mkdir(exist_ok=True)\n    path = (base / stored).resolve()\n    if path.parent != base or not path.is_relative_to(base):\n        return None\n    return path\n");
source("utils/site_gate.py", "_chemin", "python", "def _chemin():\n    force = os.environ.get(\"SITE_STATUS_PATH\")\n    if force:\n        return Path(force)\n    dossier = Path(\"instance\")\n    dossier.mkdir(exist_ok=True)\n    return dossier / \"site_status.json\"\n");
source("utils/site_gate.py", "_ouvert", "python", "def _ouvert():\n    return {\"suspended\": False, \"since\": None, \"by\": None}\n");
source("utils/site_gate.py", "lire_etat", "python", "def lire_etat():\n    \"\"\"État courant. Un fichier absent veut dire : le site est ouvert.\"\"\"\n    chemin = _chemin()\n    if not chemin.is_file():\n        return _ouvert()\n    try:\n        data = json.loads(chemin.read_text(encoding=\"utf-8\"))\n    except (OSError, json.JSONDecodeError, UnicodeError):\n        return _ouvert()\n    if not isinstance(data, dict):\n        return _ouvert()\n    return {\n        \"suspended\": bool(data.get(\"suspended\")),\n        \"since\": data.get(\"since\") if isinstance(data.get(\"since\"), str) else None,\n        \"by\": data.get(\"by\") if isinstance(data.get(\"by\"), str) else None,\n    }\n");
source("utils/site_gate.py", "definir_suspension", "python", "def definir_suspension(suspendu, username):\n    \"\"\"Pose ou retire la suspension. Une seconde suspension ne change pas la date.\"\"\"\n    with _VERROU:\n        actuel = lire_etat()\n        if suspendu and actuel[\"suspended\"]:\n            return actuel\n        if suspendu:\n            etat = {\n                \"suspended\": True,\n                \"since\": datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace(\"+00:00\", \"Z\"),\n                \"by\": username or \"\",\n            }\n        else:\n            etat = _ouvert()\n        chemin = _chemin()\n        chemin.parent.mkdir(exist_ok=True)\n        temporaire = chemin.with_suffix(\".tmp\")\n        temporaire.write_text(json.dumps(etat), encoding=\"utf-8\")\n        try:\n            os.chmod(temporaire, 0o600)\n        except OSError:\n            pass\n        temporaire.replace(chemin)\n        return etat\n");
source("utils/site_gate.py", "_date_lisible", "python", "def _date_lisible(iso):\n    if not isinstance(iso, str) or len(iso) < 16:\n        return None\n    # 2026-10-19T17:36:00Z -> 19/10/2026 17:36 UTC\n    try:\n        jour, heure = iso[:10], iso[11:16]\n        annee, mois, numero = jour.split(\"-\")\n        return f\"{numero}/{mois}/{annee} {heure} UTC\"\n    except ValueError:\n        return None\n");
source("utils/site_gate.py", "_est_proprietaire", "python", "def _est_proprietaire():\n    \"\"\"Vrai si le cookie courant est un propriétaire non suspendu.\n\n    Une erreur de jeton ne bloque pas la requête : l'appelant décide ensuite.\n    \"\"\"\n    from flask_jwt_extended import get_jwt, verify_jwt_in_request\n\n    from database.model import User, db\n\n    try:\n        verify_jwt_in_request(optional=True)\n        claims = get_jwt()\n    except Exception:\n        return False\n    user_id = claims.get(\"sub\") if claims else None\n    if not user_id:\n        return False\n    user = db.session.get(User, user_id)\n    return user is not None and user.role == \"owner\" and not user.is_ban\n");
source("utils/site_gate.py", "bloquer_si_suspendu", "python", "def bloquer_si_suspendu():\n    \"\"\"Réponse 503 si le site est en pause, sinon None pour laisser passer.\"\"\"\n    etat = lire_etat()\n    if not etat[\"suspended\"]:\n        return None\n    if request.endpoint in _ENDPOINTS_OUVERTS or request.path.startswith((\"/static/\", \"/legal/\")):\n        return None\n    if _est_proprietaire():\n        return None\n    if wants_html():\n        return render_template(\"suspendu.html\", depuis=_date_lisible(etat.get(\"since\"))), 503\n    return jsonify({\"error\": \"Le site est suspendu.\"}), 503\n");
source("utils/users.py", "public_profile", "python", "def public_profile(user, include_status=False):\n    \"\"\"Champs sûrs à montrer dans une page ou une réponse JSON.\"\"\"\n    profile = {\n        \"id\": user.id,\n        \"name\": user.name,\n        \"surname\": user.surname,\n        \"username\": user.username,\n        \"role\": user.role,\n        \"must_change_password\": bool(user.must_change_password),\n    }\n    if include_status:\n        profile[\"is_ban\"] = bool(user.is_ban)\n        profile[\"created_at\"] = user.created_at.isoformat() if user.created_at else None\n    return profile\n");
source("utils/users.py", "list_profiles", "python", "def list_profiles():\n    \"\"\"Tous les comptes, triés par identifiant, pour les pages de gestion.\"\"\"\n    from database.model import User\n\n    users = User.query.order_by(User.username).all()\n    return [public_profile(user, include_status=True) for user in users]\n");
source("static/accueil.js", "afficherZones", "javascript", "  function afficherZones() {\n    const pret = Boolean(choix);\n    formulaire.hidden = !(pret && connecte);\n    invite.hidden = !(pret && !connecte);\n  }");
source("static/accueil.js", "cheminCours", "javascript", "  function cheminCours() {\n    return \"/info/files/\"\n      + encodeURIComponent(choix.matiere) + \"/\"\n      + encodeURIComponent(choix.classe) + \"/\"\n      + encodeURIComponent(choix.specialite);\n  }");
source("static/accueil.js", "chargerFiches", "javascript", "  function chargerFiches() {\n    fichiers.replaceChildren();\n    if (!choix) return;\n    const attente = document.createElement(\"p\");\n    attente.className = \"vide\";\n    attente.textContent = \"Chargement des fiches…\";\n    fichiers.append(attente);\n    api(cheminCours()).then(function (reponse) {\n      fichiers.replaceChildren();\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Fiches indisponibles\", \"erreur\");\n        return;\n      }\n      const liste = reponse.data.metadata || [];\n      if (!liste.length) {\n        const vide = document.createElement(\"p\");\n        vide.className = \"vide\";\n        vide.textContent = \"Aucune fiche pour ce cours.\";\n        fichiers.append(vide);\n        return;\n      }\n      liste.forEach(function (fiche) {\n        if (!fiche || !fiche.id) return;\n        fichiers.append(carteFiche(fiche, []));\n      });\n    });\n  }");
source("static/accueil.js", "onChange", "javascript", "    onChange: function (nouveau) {\n      choix = nouveau;\n      afficherZones();\n      chargerFiches();\n    }");
source("static/audit.js", "nombre", "javascript", "  function nombre(valeur) {\n    return Number(valeur || 0).toLocaleString(\"fr-FR\");\n  }");
source("static/audit.js", "octets", "javascript", "  function octets(valeur) {\n    const n = Number(valeur || 0);\n    const unites = [\"o\", \"Ko\", \"Mo\", \"Go\", \"To\"];\n    let reste = n;\n    let index = 0;\n    while (reste >= 1024 && index < unites.length - 1) {\n      reste /= 1024;\n      index += 1;\n    }\n    const texte = index === 0\n      ? String(Math.round(reste))\n      : reste.toLocaleString(\"fr-FR\", { maximumFractionDigits: reste >= 10 ? 0 : 1 });\n    return texte + \" \" + unites[index];\n  }");
source("static/audit.js", "detailOctets", "javascript", "  function detailOctets(valeur) {\n    return nombre(valeur) + \" octets\";\n  }");
source("static/audit.js", "dateCourte", "javascript", "  function dateCourte(iso) {\n    if (!iso) return \"—\";\n    const date = new Date(iso);\n    if (Number.isNaN(date.getTime())) return iso;\n    return date.toLocaleString(\"fr-FR\");\n  }");
source("static/audit.js", "duree", "javascript", "  function duree(secondes) {\n    const total = Math.max(0, Math.floor(Number(secondes) || 0));\n    const heures = Math.floor(total / 3600);\n    const minutes = Math.floor((total % 3600) / 60);\n    if (heures) return heures + \" h \" + minutes + \" min\";\n    return minutes + \" min\";\n  }");
source("static/audit.js", "pourcent", "javascript", "  function pourcent(part, total) {\n    if (!total) return \"0 %\";\n    return (part / total * 100).toLocaleString(\"fr-FR\", { maximumFractionDigits: 1 }) + \" %\";\n  }");
source("static/audit.js", "vider", "javascript", "  function vider(id) {\n    const zone = document.getElementById(id);\n    if (zone) zone.replaceChildren();\n    return zone;\n  }");
source("static/audit.js", "carte", "javascript", "  function carte(libelle, valeur, detail) {\n    const article = document.createElement(\"article\");\n    article.className = \"stat\";\n    const fort = document.createElement(\"strong\");\n    fort.textContent = valeur;\n    const span = document.createElement(\"span\");\n    span.textContent = libelle;\n    article.append(fort, span);\n    if (detail) {\n      const petit = document.createElement(\"small\");\n      petit.textContent = detail;\n      article.append(petit);\n    }\n    return article;\n  }");
source("static/audit.js", "tableau", "javascript", "  function tableau(colonnes, lignes, vide) {\n    if (!lignes.length) {\n      const paragraphe = document.createElement(\"p\");\n      paragraphe.className = \"vide\";\n      paragraphe.textContent = vide;\n      return paragraphe;\n    }\n    const enveloppe = document.createElement(\"div\");\n    enveloppe.className = \"table-scroll\";\n    const table = document.createElement(\"table\");\n    table.className = \"comptes\";\n    const thead = document.createElement(\"thead\");\n    const entete = document.createElement(\"tr\");\n    colonnes.forEach(function (colonne) {\n      const th = document.createElement(\"th\");\n      th.textContent = colonne;\n      entete.append(th);\n    });\n    thead.append(entete);\n    const corps = document.createElement(\"tbody\");\n    lignes.forEach(function (cellules) {\n      const tr = document.createElement(\"tr\");\n      cellules.forEach(function (cellule) {\n        const td = document.createElement(\"td\");\n        if (cellule && cellule.noeud) {\n          td.append(cellule.noeud);\n        } else {\n          td.textContent = cellule == null ? \"\" : String(cellule);\n        }\n        tr.append(td);\n      });\n      corps.append(tr);\n    });\n    table.append(thead, corps);\n    enveloppe.append(table);\n    return enveloppe;\n  }");
source("static/audit.js", "listeSimple", "javascript", "  function listeSimple(items, vide) {\n    if (!items.length) {\n      const paragraphe = document.createElement(\"p\");\n      paragraphe.className = \"vide\";\n      paragraphe.textContent = vide;\n      return paragraphe;\n    }\n    const ul = document.createElement(\"ul\");\n    items.forEach(function (texte) {\n      const li = document.createElement(\"li\");\n      li.textContent = texte;\n      ul.append(li);\n    });\n    return ul;\n  }");
source("static/audit.js", "cours", "javascript", "  function cours(fiche) {\n    return [fiche.matiere, fiche.classe, fiche.specialite].filter(Boolean).join(\" · \");\n  }");
source("static/audit.js", "peindre", "javascript", "  function peindre() {\n    if (!audit) return;\n    const site = audit.site || {};\n    const stockage = audit.stockage || {};\n    const sessions = audit.sessions || {};\n    const comptes = audit.comptes || {};\n    const activite = audit.activite || {};\n    const contenu = audit.contenu || {};\n    const securite = audit.securite || {};\n    const roles = comptes.par_role || {};\n\n    const etat = document.getElementById(\"etat-site\");\n    etat.textContent = \"Relevé du \" + dateCourte(audit.genere_le)\n      + \" · processus démarré depuis \" + duree(site.duree_secondes)\n      + \" · session \" + nombre(site.session_heures) + \" h\"\n      + \" · cookie \" + (site.cookie_securise ? \"HTTPS seulement\" : \"aussi en HTTP\");\n\n    const bouton = document.getElementById(\"bouton-site\");\n    if (site.suspendu) {\n      bouton.textContent = \"Réactiver le site\";\n      bouton.className = \"bouton\";\n    } else {\n      bouton.textContent = \"Suspendre le site\";\n      bouton.className = \"bouton bouton-danger\";\n    }\n\n    let banniere = document.getElementById(\"banniere-site\");\n    if (site.suspendu) {\n      if (!banniere) {\n        banniere = document.createElement(\"p\");\n        banniere.id = \"banniere-site\";\n        banniere.className = \"banniere\";\n        document.getElementById(\"zone-pilotage\").prepend(banniere);\n      }\n      banniere.textContent = \"Le site est suspendu\"\n        + (site.par ? \" par \" + site.par : \"\")\n        + (site.depuis ? \" depuis le \" + dateCourte(site.depuis) : \"\")\n        + \". Toi seul peux encore naviguer.\";\n    } else if (banniere) {\n      banniere.remove();\n    }\n\n    const zoneSessions = vider(\"zone-sessions\");\n    const grilleSessions = document.createElement(\"div\");\n    grilleSessions.className = \"grille-stats\";\n    grilleSessions.append(\n      carte(\"En ligne\", nombre(sessions.en_ligne), \"activité < 15 min\"),\n      carte(\"Personnes avec une session\", nombre(sessions.personnes)),\n      carte(\"Sessions ouvertes\", nombre(sessions.ouvertes)),\n      carte(\"Déconnectées, jeton encore en base\", nombre(sessions.deconnectees))\n    );\n    zoneSessions.append(grilleSessions);\n    zoneSessions.append(tableau(\n      [\"Nom\", \"Identifiant\", \"Rôle\", \"État\", \"Depuis\", \"Dernière activité\", \"Expire\", \"Navigateur\"],\n      (sessions.liste || []).map(function (session) {\n        const etatSession = document.createElement(\"span\");\n        if (session.suspendu) {\n          etatSession.textContent = \"Compte suspendu\";\n        } else if (session.en_ligne) {\n          etatSession.className = \"badge\";\n          etatSession.textContent = \"En ligne\";\n        } else {\n          etatSession.textContent = \"Session ouverte\";\n        }\n        return [\n          session.nom,\n          session.username,\n          session.role ? libelleRole(session.role) : \"—\",\n          { noeud: etatSession },\n          dateCourte(session.depuis),\n          dateCourte(session.vu),\n          dateCourte(session.expire),\n          session.agent || \"—\"\n        ];\n      }),\n      \"Personne n'est connecté.\"\n    ));\n\n    const zoneStockage = vider(\"zone-stockage\");\n    zoneStockage.append(\n      carte(\"Fichiers envoyés\", octets(stockage.uploads_octets), detailOctets(stockage.uploads_octets) + \" · \" + nombre(stockage.uploads_fichiers) + \" fichiers\"),\n      carte(\"Fiches (JSON)\", octets(stockage.matiere_octets), detailOctets(stockage.matiere_octets) + \" · \" + nombre(stockage.matiere_fichiers) + \" fichiers\"),\n      carte(\"Base des comptes\", octets(stockage.base_octets), detailOctets(stockage.base_octets)),\n      carte(\"Dossier instance\", octets(stockage.instance_octets), detailOctets(stockage.instance_octets)),\n      carte(\"Orphelins\", octets(stockage.orphelins_octets), nombre(stockage.orphelins) + \" fichiers sans fiche\"),\n      carte(\"Disque utilisé\", pourcent(stockage.disque_utilise_octets, stockage.disque_total_octets), octets(stockage.disque_utilise_octets) + \" sur \" + octets(stockage.disque_total_octets)),\n      carte(\"Disque libre\", octets(stockage.disque_libre_octets), detailOctets(stockage.disque_libre_octets)),\n      carte(\"Taille max d'un envoi\", octets(site.envoi_max_octets), detailOctets(site.envoi_max_octets))\n    );\n\n    const zoneComptes = vider(\"zone-comptes\");\n    zoneComptes.append(\n      carte(\"Comptes\", nombre(comptes.total)),\n      carte(\"Actifs\", nombre(comptes.actifs)),\n      carte(\"Suspendus\", nombre(comptes.suspendus)),\n      carte(\"Élèves\", nombre(roles.user)),\n      carte(\"Modérateurs\", nombre(roles.moderator)),\n      carte(\"Administrateurs\", nombre(roles.admin)),\n      carte(\"Propriétaires\", nombre(roles.owner)),\n      carte(\"Créés en 24 h\", nombre(comptes.crees_24h)),\n      carte(\"Créés en 7 jours\", nombre(comptes.crees_7j)),\n      carte(\"Créés en 30 jours\", nombre(comptes.crees_30j)),\n      carte(\"Ont publié\", nombre(comptes.avec_envois)),\n      carte(\"Ont téléchargé\", nombre(comptes.avec_telechargements)),\n      carte(\"Sans activité\", nombre(comptes.sans_activite))\n    );\n    const anciennete = document.getElementById(\"zone-anciennete\");\n    const ancien = comptes.plus_ancien;\n    const recent = comptes.plus_recent;\n    anciennete.textContent = ancien\n      ? \"Plus ancien : \" + ancien.username + \" (\" + dateCourte(ancien.le) + \"). Plus récent : \" + recent.username + \" (\" + dateCourte(recent.le) + \").\"\n      : \"Aucun compte daté.\";\n\n    const zoneActivite = vider(\"zone-activite\");\n    zoneActivite.append(\n      carte(\"Envois enregistrés\", nombre(activite.envois)),\n      carte(\"Téléchargements enregistrés\", nombre(activite.telechargements)),\n      carte(\"Fiches distinctes téléchargées\", nombre(activite.fiches_telechargees)),\n      carte(\"Envois perdus\", nombre(activite.envois_perdus), \"cités sur un compte, absents du disque\")\n    );\n    vider(\"zone-auteurs\").append(tableau(\n      [\"Identifiant\", \"Fiches\"],\n      (activite.top_auteurs || []).map(function (ligne) { return [ligne.username, nombre(ligne.nombre)]; }),\n      \"Aucune publication.\"\n    ));\n    const etoiles = audit.etoiles || {};\n    const zoneEtoiles = vider(\"zone-etoiles\");\n    if (zoneEtoiles) {\n      zoneEtoiles.append(\n        carte(\"Étoiles posées\", nombre(etoiles.total)),\n        carte(\"Matières avec une étoile\", nombre((etoiles.par_matiere || []).length))\n      );\n    }\n    const globale = vider(\"zone-etoile-globale\");\n    if (globale) {\n      if (!etoiles.plus_etoilee) {\n        const vide = document.createElement(\"p\");\n        vide.className = \"vide\";\n        vide.textContent = \"Aucune fiche n'a encore d'étoile.\";\n        globale.append(vide);\n      } else {\n        const fiche = etoiles.plus_etoilee;\n        globale.append(tableau(\n          [\"Titre\", \"Auteur\", \"Cours\", \"Étoiles\"],\n          [[fiche.titre, fiche.auteur, cours(fiche), nombre(fiche.etoiles)]],\n          \"Aucune fiche n'a encore d'étoile.\"\n        ));\n      }\n    }\n    const parMatiere = [];\n    (etoiles.par_matiere || []).forEach(function (groupe) {\n      (groupe.fiches || []).forEach(function (fiche) {\n        parMatiere.push([groupe.matiere, fiche.titre, fiche.auteur, cours(fiche), nombre(fiche.etoiles)]);\n      });\n    });\n    const zoneMatieresEtoiles = vider(\"zone-etoiles-matiere\");\n    if (zoneMatieresEtoiles) {\n      zoneMatieresEtoiles.append(tableau(\n        [\"Matière\", \"Titre\", \"Auteur\", \"Cours\", \"Étoiles\"],\n        parMatiere,\n        \"Aucune matière n'a de fiche étoilée.\"\n      ));\n    }\n\n    vider(\"zone-lecteurs\").append(tableau(\n      [\"Identifiant\", \"Téléchargements\"],\n      (activite.top_lecteurs || []).map(function (ligne) { return [ligne.username, nombre(ligne.nombre)]; }),\n      \"Aucun téléchargement.\"\n    ));\n\n    const zoneContenu = vider(\"zone-contenu\");\n    zoneContenu.append(\n      carte(\"Fiches valides\", nombre(contenu.fiches)),\n      carte(\"Matières\", nombre(contenu.matieres)),\n      carte(\"Classes\", nombre(contenu.classes)),\n      carte(\"Spécialités\", nombre(contenu.specialites)),\n      carte(\"Cours vides\", nombre(contenu.cours_vides)),\n      carte(\"JSON invalides\", nombre(contenu.json_invalides)),\n      carte(\"Identifiants en double\", nombre(contenu.doublons)),\n      carte(\"Fichiers manquants\", nombre(contenu.fichiers_manquants)),\n      carte(\"Auteurs inconnus\", nombre(contenu.auteurs_inconnus)),\n      carte(\"Taille moyenne\", octets(contenu.taille_moyenne_octets), detailOctets(contenu.taille_moyenne_octets))\n    );\n    vider(\"zone-matieres\").append(tableau(\n      [\"Matière\", \"Fiches\", \"Cours\", \"Volume\"],\n      (contenu.par_matiere || []).map(function (ligne) {\n        return [ligne.nom, nombre(ligne.fiches), nombre(ligne.cours), octets(ligne.octets)];\n      }),\n      \"Aucune fiche.\"\n    ));\n    vider(\"zone-classes\").append(tableau(\n      [\"Classe\", \"Fiches\", \"Volume\"],\n      (contenu.par_classe || []).map(function (ligne) {\n        return [ligne.nom, nombre(ligne.fiches), octets(ligne.octets)];\n      }),\n      \"Aucune fiche.\"\n    ));\n    vider(\"zone-extensions\").append(tableau(\n      [\"Type\", \"Fiches\", \"Volume\"],\n      (contenu.par_extension || []).map(function (ligne) {\n        return [ligne.nom, nombre(ligne.fiches), octets(ligne.octets)];\n      }),\n      \"Aucune fiche.\"\n    ));\n    vider(\"zone-gros\").append(tableau(\n      [\"Titre\", \"Auteur\", \"Cours\", \"Taille\"],\n      (contenu.plus_gros || []).map(function (ligne) {\n        return [ligne.titre, ligne.auteur, cours(ligne), octets(ligne.octets)];\n      }),\n      \"Aucun fichier.\"\n    ));\n    vider(\"zone-recentes\").append(tableau(\n      [\"Titre\", \"Auteur\", \"Cours\", \"Quand\"],\n      (contenu.dernieres || []).map(function (ligne) {\n        return [ligne.titre, ligne.auteur, cours(ligne), dateCourte(ligne.le)];\n      }),\n      \"Aucune fiche.\"\n    ));\n    vider(\"zone-vides\").append(listeSimple(\n      (contenu.cours_vides_liste || []).map(function (ligne) {\n        return ligne.matiere + \" · \" + ligne.classe + \" · \" + ligne.specialite;\n      }),\n      \"Aucun cours vide.\"\n    ));\n    if ((contenu.cours_vides || 0) > (contenu.cours_vides_liste || []).length) {\n      const suite = document.createElement(\"p\");\n      suite.className = \"note\";\n      suite.textContent = \"Extrait de \" + (contenu.cours_vides_liste || []).length + \" cours vides sur \" + nombre(contenu.cours_vides) + \".\";\n      document.getElementById(\"zone-vides\").append(suite);\n    }\n    vider(\"zone-orphelins\").append(tableau(\n      [\"Fichier\", \"Taille\"],\n      (contenu.orphelins_liste || []).map(function (ligne) {\n        return [ligne.nom, octets(ligne.octets)];\n      }),\n      \"Aucun orphelin.\"\n    ));\n    document.getElementById(\"zone-types\").textContent = \"Types autorisés à l'envoi : \" + (contenu.types_autorises || []).join(\", \");\n\n    const zoneSecurite = vider(\"zone-securite\");\n    zoneSecurite.append(\n      carte(\"Identifiants suivis\", nombre(securite.tentatives_suivies), \"échecs récents de mot de passe\"),\n      carte(\"Identifiants bloqués\", nombre((securite.identifiants_bloques || []).length)),\n      carte(\"Comptes suspendus\", nombre((securite.comptes_suspendus || []).length))\n    );\n    vider(\"zone-bloques\").append(listeSimple(securite.identifiants_bloques || [], \"Aucun identifiant bloqué.\"));\n    vider(\"zone-bannis\").append(tableau(\n      [\"Identifiant\", \"Rôle\"],\n      (securite.comptes_suspendus || []).map(function (ligne) {\n        return [ligne.username, libelleRole(ligne.role)];\n      }),\n      \"Aucun compte suspendu.\"\n    ));\n    dessinerGraphiques(site, stockage, comptes, roles, activite, contenu, etoilesDe(audit));\n  }\n");
source("static/audit.js", "appliquer", "javascript", "  function appliquer(data, message) {\n    audit = data;\n    peindre();\n    if (message) afficherStatut(\"statut\", message, \"ok\");\n  }");
source("static/audit.js", "actualiser", "javascript", "  function actualiser(message) {\n    if (enCours) return;\n    enCours = true;\n    api(\"/owner/audit.json\").then(function (reponse) {\n      enCours = false;\n      if (reponse.status === 401) {\n        window.location.assign(\"/auth/login-page?next=/owner/audit\");\n        return;\n      }\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Relevé indisponible\", \"erreur\");\n        return;\n      }\n      appliquer(reponse.data, message);\n    });\n  }");
source("static/audit_perso.js", "nombre", "javascript", "  function nombre(valeur) {\n    return Number(valeur || 0).toLocaleString(\"fr-FR\");\n  }");
source("static/audit_perso.js", "octets", "javascript", "  function octets(valeur) {\n    const n = Number(valeur || 0);\n    const unites = [\"o\", \"Ko\", \"Mo\", \"Go\"];\n    let reste = n;\n    let index = 0;\n    while (reste >= 1024 && index < unites.length - 1) {\n      reste /= 1024;\n      index += 1;\n    }\n    const texte = index === 0\n      ? String(Math.round(reste))\n      : reste.toLocaleString(\"fr-FR\", { maximumFractionDigits: 1 });\n    return texte + \" \" + unites[index];\n  }");
source("static/audit_perso.js", "dateCourte", "javascript", "  function dateCourte(iso) {\n    if (!iso) return \"—\";\n    const date = new Date(iso);\n    if (Number.isNaN(date.getTime())) return iso;\n    return date.toLocaleString(\"fr-FR\");\n  }");
source("static/audit_perso.js", "vider", "javascript", "  function vider(id) {\n    const zone = document.getElementById(id);\n    if (zone) zone.replaceChildren();\n    return zone;\n  }");
source("static/audit_perso.js", "carte", "javascript", "  function carte(libelle, valeur, detail) {\n    const article = document.createElement(\"article\");\n    article.className = \"stat\";\n    const fort = document.createElement(\"strong\");\n    fort.textContent = valeur;\n    const span = document.createElement(\"span\");\n    span.textContent = libelle;\n    article.append(fort, span);\n    if (detail) {\n      const petit = document.createElement(\"small\");\n      petit.textContent = detail;\n      article.append(petit);\n    }\n    return article;\n  }");
source("static/audit_perso.js", "tableau", "javascript", "  function tableau(colonnes, lignes, vide) {\n    if (!lignes.length) {\n      const paragraphe = document.createElement(\"p\");\n      paragraphe.className = \"vide\";\n      paragraphe.textContent = vide;\n      return paragraphe;\n    }\n    const enveloppe = document.createElement(\"div\");\n    enveloppe.className = \"table-scroll\";\n    const table = document.createElement(\"table\");\n    table.className = \"comptes\";\n    const entete = document.createElement(\"tr\");\n    colonnes.forEach(function (colonne) {\n      const th = document.createElement(\"th\");\n      th.textContent = colonne;\n      entete.append(th);\n    });\n    const thead = document.createElement(\"thead\");\n    thead.append(entete);\n    const corps = document.createElement(\"tbody\");\n    lignes.forEach(function (cellules) {\n      const tr = document.createElement(\"tr\");\n      cellules.forEach(function (cellule) {\n        const td = document.createElement(\"td\");\n        td.textContent = cellule == null ? \"\" : String(cellule);\n        tr.append(td);\n      });\n      corps.append(tr);\n    });\n    table.append(thead, corps);\n    enveloppe.append(table);\n    return enveloppe;\n  }");
source("static/audit_perso.js", "cours", "javascript", "  function cours(fiche) {\n    return [fiche.matiere, fiche.classe, fiche.specialite].filter(Boolean).join(\" · \");\n  }");
source("static/audit_perso.js", "audience", "javascript", "  function audience(valeur) {\n    if (valeur === \"auteur\") return \"Tous les utilisateurs\";\n    if (valeur === \"equipe\") return \"Équipe\";\n    if (valeur === \"les_deux\") return \"Utilisateurs et équipe\";\n    return valeur || \"\";\n  }");
source("static/audit_perso.js", "statut", "javascript", "  function statut(valeur, responsable) {\n    if (valeur === \"valide\") return \"Validé\" + (responsable ? \" par \" + responsable : \"\");\n    if (valeur === \"pris\") return \"Pris en charge\" + (responsable ? \" par \" + responsable : \"\");\n    return \"En attente\";\n  }");
source("static/audit_perso.js", "peindre", "javascript", "  function peindre() {\n    if (!audit) return;\n    const resume = audit.resume || {};\n    const commentaires = resume.commentaires || {};\n    const zone = vider(\"zone-resume\");\n    zone.append(\n      carte(\"Fiches\", nombre(resume.fiches)),\n      carte(\"Volume\", octets(resume.octets)),\n      carte(\"Étoiles reçues\", nombre(resume.etoiles)),\n      carte(\"Téléchargements\", nombre(resume.telechargements), \"de tes fiches\"),\n      carte(\"Commentaires ouverts\", nombre(commentaires.ouverts)),\n      carte(\"Pris en charge\", nombre(commentaires.pris)),\n      carte(\"Validés\", nombre(commentaires.valides))\n    );\n    const graphique = document.getElementById(\"graphique-perso\");\n    if (graphique && typeof barreAnimee === \"function\") {\n      graphique.replaceChildren();\n      const maxEtoiles = (audit.liste || []).reduce(function (max, fiche) {\n        return Math.max(max, fiche.etoiles || 0);\n      }, 0);\n      (audit.liste || []).slice(0, 8).forEach(function (fiche) {\n        graphique.append(barreAnimee(\n          fiche.titre,\n          fiche.etoiles || 0,\n          maxEtoiles || 1,\n          nombre(fiche.etoiles) + \" étoiles\"\n        ));\n      });\n      if (!(audit.liste || []).length) {\n        const vide = document.createElement(\"p\");\n        vide.className = \"vide\";\n        vide.textContent = \"Aucune fiche à dessiner.\";\n        graphique.append(vide);\n      }\n    }\n    const plus = document.getElementById(\"zone-plus\");\n    plus.textContent = audit.plus_etoilee\n      ? \"Ta fiche la plus étoilée : \" + audit.plus_etoilee.titre\n        + \" (\" + nombre(audit.plus_etoilee.etoiles) + \").\"\n      : \"Aucune de tes fiches n'a encore d'étoile.\";\n\n    vider(\"zone-fiches\").append(tableau(\n      [\"Titre\", \"Cours\", \"Étoiles\", \"Commentaires\", \"Taille\"],\n      (audit.liste || []).map(function (fiche) {\n        const suivi = fiche.commentaires || {};\n        const detail = nombre(suivi.ouverts) + \" ouverts, \"\n          + nombre(suivi.pris) + \" pris, \"\n          + nombre(suivi.valides) + \" validés\";\n        return [fiche.titre, cours(fiche), nombre(fiche.etoiles), detail, octets(fiche.octets)];\n      }),\n      \"Tu n'as pas encore publié de fiche.\"\n    ));\n\n    vider(\"zone-commentaires\").append(tableau(\n      [\"Fiche\", \"Commentaire\", \"Visible par\", \"État\", \"Quand\"],\n      (audit.commentaires_recents || []).map(function (ligne) {\n        return [\n          ligne.fiche + (ligne.matiere ? \" · \" + ligne.matiere : \"\"),\n          ligne.texte,\n          audience(ligne.audience),\n          statut(ligne.statut, ligne.responsable),\n          dateCourte(ligne.le)\n        ];\n      }),\n      \"Aucun commentaire à lire.\"\n    ));\n  }\n");
source("static/common.js", "lireCookie", "javascript", "function lireCookie(nom) {\n  const morceaux = document.cookie.split(\";\");\n  for (let i = 0; i < morceaux.length; i += 1) {\n    const partie = morceaux[i].trim();\n    const egal = partie.indexOf(\"=\");\n    if (egal > 0 && partie.slice(0, egal) === nom) {\n      return decodeURIComponent(partie.slice(egal + 1));\n    }\n  }\n  return \"\";\n}");
source("static/common.js", "api", "javascript", "function api(chemin, options) {\n  options = options || {};\n  const methode = options.method || \"GET\";\n  const entetes = { Accept: \"application/json\" };\n  if (methode !== \"GET\" && methode !== \"HEAD\") {\n    const jeton = lireCookie(\"csrf_access_token\");\n    if (jeton) entetes[\"X-CSRF-TOKEN\"] = jeton;\n  }\n  let corps;\n  if (options.json !== undefined) {\n    entetes[\"Content-Type\"] = \"application/json\";\n    corps = JSON.stringify(options.json);\n  } else if (options.body) {\n    corps = options.body;\n  }\n\n  return fetch(chemin, {\n    method: methode,\n    credentials: \"same-origin\",\n    headers: entetes,\n    body: corps\n  }).then(function (reponse) {\n    return reponse.text().then(function (texte) {\n      let data = {};\n      if (texte) {\n        try {\n          data = JSON.parse(texte);\n        } catch (e) {\n          data = {\n            error: reponse.status === 413\n              ? \"Fichier trop volumineux.\"\n              : \"Réponse inattendue du serveur.\"\n          };\n        }\n      }\n      return { ok: reponse.ok, status: reponse.status, data: data };\n    });\n  }).catch(function () {\n    return { ok: false, status: 0, data: { error: \"Impossible de joindre le serveur.\" } };\n  });\n}");
source("static/common.js", "afficherStatut", "javascript", "function afficherStatut(id, message, type) {\n  const zone = document.getElementById(id);\n  if (!zone) return;\n  zone.textContent = message || \"\";\n  zone.classList.remove(\"ok\", \"erreur\");\n  if (type) zone.classList.add(type);\n}");
source("static/common.js", "lienEspace", "javascript", "function lienEspace(role) {\n  if (role === \"owner\") return \"/owner/audit\";\n  if (role === \"admin\") return \"/admin/dashboard\";\n  if (role === \"moderator\") return \"/moderator/dashboard\";\n  return \"/users/dashboard\";\n}");
source("static/common.js", "libelleRole", "javascript", "function libelleRole(role) {\n  if (role === \"owner\") return \"Propriétaire\";\n  if (role === \"admin\") return \"Administrateur\";\n  if (role === \"moderator\") return \"Modérateur\";\n  return \"Élève\";\n}");
source("static/common.js", "lireJson", "javascript", "function lireJson(id) {\n  const zone = document.getElementById(id);\n  if (!zone) return null;\n  try {\n    return JSON.parse(zone.textContent);\n  } catch (e) {\n    return null;\n  }\n}");
source("static/common.js", "libelleAudience", "javascript", "function libelleAudience(audience) {\n  if (audience === \"auteur\") return \"Pour tous les utilisateurs\";\n  if (audience === \"equipe\") return \"Pour l'équipe\";\n  if (audience === \"les_deux\") return \"Pour les utilisateurs et l'équipe\";\n  return \"\";\n}");
source("static/common.js", "libelleStatutCommentaire", "javascript", "function libelleStatutCommentaire(commentaire) {\n  if (commentaire.statut === \"valide\") {\n    return \"Validé\" + (commentaire.responsable ? \" par \" + commentaire.responsable : \"\");\n  }\n  if (commentaire.statut === \"pris\") {\n    return \"Pris en charge par \" + (commentaire.responsable || \"un responsable\");\n  }\n  return \"En attente\";\n}");
source("static/common.js", "messageLocal", "javascript", "function messageLocal(zone, texte, type) {\n  let paragraphe = zone.querySelector(\".statut-local\");\n  if (!paragraphe) {\n    paragraphe = document.createElement(\"p\");\n    paragraphe.className = \"statut statut-local\";\n    paragraphe.setAttribute(\"role\", \"status\");\n    zone.prepend(paragraphe);\n  }\n  paragraphe.textContent = texte || \"\";\n  paragraphe.classList.remove(\"ok\", \"erreur\");\n  if (type) paragraphe.classList.add(type);\n}");
source("static/common.js", "allerConnexion", "javascript", "function allerConnexion() {\n  const retour = window.location.pathname + window.location.search;\n  window.location.assign(\"/auth/login-page?next=\" + encodeURIComponent(retour));\n}");
source("static/common.js", "boutonEtoile", "javascript", "function boutonEtoile(fiche) {\n  const bouton = document.createElement(\"button\");\n  bouton.type = \"button\";\n  bouton.className = \"bouton bouton-secondaire etoile\";\n\n  function libelle(nombre, actif) {\n    const compte = Number(nombre) || 0;\n    bouton.textContent = (actif ? \"★ \" : \"☆ \") + compte;\n    bouton.setAttribute(\"aria-pressed\", actif ? \"true\" : \"false\");\n    bouton.setAttribute(\"aria-label\", actif ? \"Retirer mon étoile\" : \"Mettre une étoile\");\n  }\n\n  libelle(fiche.etoiles, fiche.etoile_moi);\n  bouton.addEventListener(\"click\", function () {\n    bouton.disabled = true;\n    api(\"/fiches/\" + encodeURIComponent(fiche.id) + \"/etoile\", { method: \"POST\" }).then(function (reponse) {\n      bouton.disabled = false;\n      if (reponse.status === 401) {\n        allerConnexion();\n        return;\n      }\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Étoile impossible\", \"erreur\");\n        return;\n      }\n      libelle(reponse.data.etoiles, reponse.data.etoile);\n    });\n  });\n  return bouton;\n}");
source("static/common.js", "libelle", "javascript", "  function libelle(nombre, actif) {\n    const compte = Number(nombre) || 0;\n    bouton.textContent = (actif ? \"★ \" : \"☆ \") + compte;\n    bouton.setAttribute(\"aria-pressed\", actif ? \"true\" : \"false\");\n    bouton.setAttribute(\"aria-label\", actif ? \"Retirer mon étoile\" : \"Mettre une étoile\");\n  }");
source("static/common.js", "dessinerCommentaires", "javascript", "function dessinerCommentaires(fiche, panneau) {\n  panneau.replaceChildren();\n  const attente = document.createElement(\"p\");\n  attente.className = \"vide\";\n  attente.textContent = \"Chargement des commentaires…\";\n  panneau.append(attente);\n\n  api(\"/fiches/\" + encodeURIComponent(fiche.id) + \"/commentaires\").then(function (reponse) {\n    panneau.replaceChildren();\n    if (reponse.status === 401) {\n      const lien = document.createElement(\"a\");\n      lien.href = \"/auth/login-page?next=\" + encodeURIComponent(window.location.pathname + window.location.search);\n      lien.textContent = \"Connecte-toi pour lire et écrire un commentaire.\";\n      panneau.append(lien);\n      return;\n    }\n    if (!reponse.ok) {\n      messageLocal(panneau, reponse.data.error || \"Commentaires indisponibles\", \"erreur\");\n      return;\n    }\n\n    const form = document.createElement(\"form\");\n    const texte = document.createElement(\"textarea\");\n    texte.name = \"texte\";\n    texte.required = true;\n    texte.maxLength = 2000;\n    texte.rows = 3;\n    texte.placeholder = \"Un retour pour améliorer la fiche\";\n    texte.setAttribute(\"aria-label\", \"Commentaire\");\n    const audience = document.createElement(\"select\");\n    audience.setAttribute(\"aria-label\", \"Qui peut lire ce commentaire\");\n    [\n      [\"auteur\", \"Pour tous les utilisateurs\"],\n      [\"equipe\", \"Seulement pour l'équipe (modération, admin, propriétaire)\"],\n      [\"les_deux\", \"Pour les utilisateurs et l'équipe\"]\n    ].forEach(function (paire) {\n      const option = document.createElement(\"option\");\n      option.value = paire[0];\n      option.textContent = paire[1];\n      audience.append(option);\n    });\n    const envoyer = document.createElement(\"button\");\n    envoyer.type = \"submit\";\n    envoyer.className = \"bouton\";\n    envoyer.textContent = \"Publier le commentaire\";\n    const note = document.createElement(\"p\");\n    note.className = \"note\";\n    note.textContent = \"N'importe quel compte peut commenter une fiche. L'équipe ne voit pas un commentaire réservé aux utilisateurs. Une seule personne le suit, puis peut le retirer après avoir modifié la fiche.\";\n    form.append(texte, audience, note, envoyer);\n    form.addEventListener(\"submit\", function (event) {\n      event.preventDefault();\n      envoyer.disabled = true;\n      api(\"/fiches/\" + encodeURIComponent(fiche.id) + \"/commentaires\", {\n        method: \"POST\",\n        json: { texte: texte.value, audience: audience.value }\n      }).then(function (creation) {\n        envoyer.disabled = false;\n        if (creation.status === 401) {\n          allerConnexion();\n          return;\n        }\n        if (!creation.ok) {\n          messageLocal(panneau, creation.data.error || \"Commentaire refusé\", \"erreur\");\n          return;\n        }\n        texte.value = \"\";\n        dessinerCommentaires(fiche, panneau);\n      });\n    });\n    panneau.append(form);\n\n    const liste = reponse.data.commentaires || [];\n    if (!liste.length) {\n      const vide = document.createElement(\"p\");\n      vide.className = \"vide\";\n      vide.textContent = \"Aucun commentaire visible pour toi.\";\n      panneau.append(vide);\n      return;\n    }\n    liste.forEach(function (commentaire) {\n      const article = document.createElement(\"article\");\n      article.className = \"commentaire\";\n      const titre = document.createElement(\"p\");\n      titre.className = \"meta\";\n      titre.textContent = (commentaire.auteur || \"Compte\") + \" · \" + libelleAudience(commentaire.audience) + \" · \" + libelleStatutCommentaire(commentaire);\n      const corps = document.createElement(\"p\");\n      corps.textContent = commentaire.texte || \"\";\n      article.append(titre, corps);\n      if (commentaire.peut_prendre) {\n        const prendre = document.createElement(\"button\");\n        prendre.type = \"button\";\n        prendre.className = \"bouton bouton-secondaire\";\n        prendre.textContent = \"Je m'en occupe\";\n        prendre.addEventListener(\"click\", function () {\n          prendre.disabled = true;\n          api(\"/fiches/\" + encodeURIComponent(fiche.id) + \"/commentaires/\" + encodeURIComponent(commentaire.id) + \"/prendre\", {\n            method: \"POST\"\n          }).then(function (suite) {\n            if (!suite.ok) {\n              prendre.disabled = false;\n              messageLocal(panneau, suite.data.error || \"Prise en charge impossible\", \"erreur\");\n              return;\n            }\n            dessinerCommentaires(fiche, panneau);\n          });\n        });\n        article.append(prendre);\n      }\n      if (commentaire.suivi && !commentaire.peut_retirer) {\n        const aide = document.createElement(\"p\");\n        aide.className = \"note\";\n        aide.textContent = \"Tu suis ce commentaire. Enregistre une modification de la fiche pour pouvoir le retirer.\";\n        article.append(aide);\n      }\n      if (commentaire.peut_retirer) {\n        const retirer = document.createElement(\"button\");\n        retirer.type = \"button\";\n        retirer.className = \"bouton bouton-danger\";\n        retirer.textContent = \"Retirer le commentaire\";\n        retirer.addEventListener(\"click\", function () {\n          if (!window.confirm(\"Retirer ce commentaire ? La fiche a été modifiée pendant ce suivi.\")) return;\n          retirer.disabled = true;\n          api(\"/fiches/\" + encodeURIComponent(fiche.id) + \"/commentaires/\" + encodeURIComponent(commentaire.id), {\n            method: \"DELETE\"\n          }).then(function (suite) {\n            if (!suite.ok) {\n              retirer.disabled = false;\n              messageLocal(panneau, suite.data.error || \"Retrait impossible\", \"erreur\");\n              return;\n            }\n            dessinerCommentaires(fiche, panneau);\n          });\n        });\n        article.append(retirer);\n      }\n      if (commentaire.peut_valider) {\n        const valider = document.createElement(\"button\");\n        valider.type = \"button\";\n        valider.className = \"bouton\";\n        valider.textContent = \"Valider le commentaire\";\n        valider.addEventListener(\"click\", function () {\n          valider.disabled = true;\n          api(\"/fiches/\" + encodeURIComponent(fiche.id) + \"/commentaires/\" + encodeURIComponent(commentaire.id) + \"/valider\", {\n            method: \"POST\"\n          }).then(function (suite) {\n            if (!suite.ok) {\n              valider.disabled = false;\n              messageLocal(panneau, suite.data.error || \"Validation impossible\", \"erreur\");\n              return;\n            }\n            dessinerCommentaires(fiche, panneau);\n          });\n        });\n        article.append(valider);\n      }\n      panneau.append(article);\n    });\n  });\n}");
source("static/common.js", "zoneCommentaires", "javascript", "function zoneCommentaires(fiche) {\n  const bloc = document.createElement(\"div\");\n  bloc.className = \"commentaires\";\n  const ouvrir = document.createElement(\"button\");\n  ouvrir.type = \"button\";\n  ouvrir.textContent = \"Commentaires\";\n  const panneau = document.createElement(\"div\");\n  panneau.hidden = true;\n  ouvrir.addEventListener(\"click\", function () {\n    panneau.hidden = !panneau.hidden;\n    ouvrir.setAttribute(\"aria-expanded\", panneau.hidden ? \"false\" : \"true\");\n    if (!panneau.hidden) dessinerCommentaires(fiche, panneau);\n  });\n  ouvrir.setAttribute(\"aria-expanded\", \"false\");\n  bloc.append(panneau);\n  return { bloc: bloc, ouvrir: ouvrir };\n}\n");
source("static/common.js", "carteFiche", "javascript", "/* Carte d'une fiche. Le texte vient de textContent, jamais de innerHTML. */\nfunction carteFiche(fiche, actions) {\n  const carte = document.createElement(\"article\");\n  carte.className = \"fiche\";\n\n  const titre = document.createElement(\"h3\");\n  titre.textContent = fiche.title || \"Sans titre\";\n\n  const meta = document.createElement(\"p\");\n  meta.className = \"meta\";\n  meta.textContent = [fiche.author, fiche.matiere, fiche.classe, fiche.specialite]\n    .filter(Boolean)\n    .join(\" · \");\n\n  const description = document.createElement(\"p\");\n  description.textContent = fiche.desc || \"\";\n\n  const fichier = document.createElement(\"p\");\n  fichier.className = \"fichier\";\n  fichier.textContent = fiche.original_filename || \"\";\n\n  const barre = document.createElement(\"div\");\n  barre.className = \"barre-fiche\";\n  if (fiche.id) barre.append(boutonEtoile(fiche));\n  const menu = document.createElement(\"details\");\n  menu.className = \"menu-liste\";\n  const resume = document.createElement(\"summary\");\n  resume.textContent = \"Actions\";\n  const panneau = document.createElement(\"div\");\n  panneau.className = \"menu-panneau\";\n  const lien = document.createElement(\"a\");\n  lien.textContent = \"Télécharger\";\n  lien.href = \"/download/\"\n    + encodeURIComponent(fiche.matiere) + \"/\"\n    + encodeURIComponent(fiche.classe) + \"/\"\n    + encodeURIComponent(fiche.specialite) + \"/\"\n    + encodeURIComponent(fiche.id);\n  panneau.append(lien);\n  (actions || []).forEach(function (action) {\n    if (action.href) {\n      const aller = document.createElement(\"a\");\n      aller.href = action.href;\n      aller.textContent = action.libelle;\n      panneau.append(aller);\n      return;\n    }\n    const bouton = document.createElement(\"button\");\n    bouton.type = \"button\";\n    bouton.textContent = action.libelle;\n    bouton.addEventListener(\"click\", action.onClick);\n    panneau.append(bouton);\n  });\n  if (fiche.id) {\n    const commentaires = zoneCommentaires(fiche);\n    panneau.append(commentaires.ouvrir);\n    carte.append(titre, meta, description, fichier, barre, commentaires.bloc);\n  } else {\n    carte.append(titre, meta, description, fichier, barre);\n  }\n  menu.append(resume, panneau);\n  barre.append(menu);\n  return carte;\n}\n");
source("static/common.js", "supprimerFiche", "javascript", "function supprimerFiche(url) {\n  if (!window.confirm(\"Supprimer cette fiche ? Cette action est définitive.\")) return;\n  api(url, { method: \"DELETE\" }).then(function (reponse) {\n    if (!reponse.ok) {\n      afficherStatut(\"statut\", reponse.data.error || \"Suppression impossible\", \"erreur\");\n      return;\n    }\n    /* Recharge toute la page : un lien de téléchargement encore affiché\n       pointerait vers une fiche qui n'existe plus. */\n    sessionStorage.setItem(\"flash\", \"Fiche supprimée.\");\n    window.location.reload();\n  });\n}");
source("static/common.js", "monterRechercheFiches", "javascript", "/* Recherche de fiches. Le tri suit la frappe et les listes, sans bouton. */\nfunction monterRechercheFiches(formulaire, zone, actionsPour) {\n  if (!formulaire || !zone) return;\n  let delai = 0;\n  let serie = 0;\n\n  function criteres() {\n    const params = new URLSearchParams();\n    new FormData(formulaire).forEach(function (valeur, cle) {\n      const texte = String(valeur || \"\").trim();\n      if (!texte || texte === \"0\") return;\n      params.set(cle, texte);\n    });\n    return params;\n  }\n\n  function peindre(reponse) {\n    zone.replaceChildren();\n    if (!reponse.ok) {\n      afficherStatut(\"statut\", reponse.data.error || \"Recherche impossible\", \"erreur\");\n      return;\n    }\n    afficherStatut(\"statut\", \"\", \"\");\n    const liste = reponse.data.fiches || [];\n    if (!liste.length) {\n      const vide = document.createElement(\"p\");\n      vide.className = \"vide\";\n      vide.textContent = \"Aucune fiche ne correspond.\";\n      zone.append(vide);\n      return;\n    }\n    liste.forEach(function (fiche) {\n      if (!fiche || !fiche.id) return;\n      zone.append(carteFiche(fiche, actionsPour ? actionsPour(fiche) : []));\n    });\n    if (reponse.data.tronque) {\n      const suite = document.createElement(\"p\");\n      suite.className = \"note\";\n      suite.textContent = \"Seules les 80 premières fiches sont affichées. Affine la recherche.\";\n      zone.append(suite);\n    }\n  }\n\n  function lancer() {\n    const params = criteres();\n    const ticket = ++serie;\n    if (!params.toString()) {\n      zone.replaceChildren();\n      afficherStatut(\"statut\", \"\", \"\");\n      return;\n    }\n    api(\"/info/recherche?\" + params.toString()).then(function (reponse) {\n      if (ticket !== serie) return;\n      peindre(reponse);\n    });\n  }\n\n  function bientot() {\n    window.clearTimeout(delai);\n    delai = window.setTimeout(lancer, 250);\n  }\n\n  formulaire.addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    window.clearTimeout(delai);\n    lancer();\n  });\n  formulaire.querySelectorAll(\"input\").forEach(function (champ) {\n    champ.addEventListener(\"input\", bientot);\n    champ.addEventListener(\"search\", function () {\n      window.clearTimeout(delai);\n      lancer();\n    });\n  });\n  formulaire.querySelectorAll(\"select\").forEach(function (champ) {\n    champ.addEventListener(\"change\", function () {\n      window.clearTimeout(delai);\n      lancer();\n    });\n  });\n}\n");
source("static/common.js", "monterSelecteur", "javascript", "function monterSelecteur(racine, options) {\n  options = options || {};\n  const etat = { matiere: \"\", classe: \"\", specialite: \"\" };\n  let valeurs = options.valeurs || null;\n  if (!valeurs) {\n    try {\n      valeurs = JSON.parse(sessionStorage.getItem(\"fiche-cours\") || \"null\");\n    } catch (e) {\n      valeurs = null;\n    }\n  }\n\n  function creerSelect(etiquette) {\n    const bloc = document.createElement(\"label\");\n    bloc.className = \"champ\";\n    const span = document.createElement(\"span\");\n    span.textContent = etiquette;\n    const select = document.createElement(\"select\");\n    bloc.append(span, select);\n    racine.append(bloc);\n    return select;\n  }\n\n  function vider(select, libelle) {\n    select.replaceChildren();\n    const option = document.createElement(\"option\");\n    option.value = \"\";\n    option.textContent = libelle;\n    select.append(option);\n  }\n\n  function remplir(select, noms, libelle) {\n    vider(select, libelle);\n    (noms || []).forEach(function (nom) {\n      const option = document.createElement(\"option\");\n      option.value = nom;\n      option.textContent = nom;\n      select.append(option);\n    });\n  }\n\n  const selectMatiere = creerSelect(\"Matière\");\n  const selectClasse = creerSelect(\"Classe\");\n  const selectSpecialite = creerSelect(\"Spécialité\");\n  selectClasse.disabled = true;\n  selectSpecialite.disabled = true;\n\n  function valeurUnique(select) {\n    /* Un seul vrai choix : on le prend, le placeholder ne compte pas. */\n    let seule = \"\";\n    let nombre = 0;\n    for (let i = 0; i < select.options.length; i += 1) {\n      const valeur = select.options[i].value;\n      if (!valeur) continue;\n      nombre += 1;\n      seule = valeur;\n    }\n    return nombre === 1 ? seule : \"\";\n  }\n\n  function choixComplet() {\n    if (!etat.matiere || !etat.classe || !etat.specialite) return null;\n    return { matiere: etat.matiere, classe: etat.classe, specialite: etat.specialite };\n  }\n\n  function notifier() {\n    const choix = choixComplet();\n    if (choix) sessionStorage.setItem(\"fiche-cours\", JSON.stringify(choix));\n    if (options.onChange) options.onChange(choix);\n  }\n\n  function chargerSpecialites() {\n    vider(selectSpecialite, \"Choisir une spécialité\");\n    selectSpecialite.disabled = true;\n    etat.specialite = \"\";\n    if (!etat.classe) {\n      notifier();\n      return Promise.resolve();\n    }\n    const url = \"/info/specialite/\"\n      + encodeURIComponent(etat.matiere) + \"/\"\n      + encodeURIComponent(etat.classe);\n    return api(url).then(function (reponse) {\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Spécialités indisponibles\", \"erreur\");\n        notifier();\n        return;\n      }\n      remplir(selectSpecialite, reponse.data.specialite, \"Choisir une spécialité\");\n      selectSpecialite.disabled = false;\n      if (valeurs && valeurs.specialite) {\n        selectSpecialite.value = valeurs.specialite;\n        if (selectSpecialite.value) etat.specialite = valeurs.specialite;\n        valeurs = null;\n      }\n      if (!etat.specialite) {\n        const seule = valeurUnique(selectSpecialite);\n        if (seule) {\n          selectSpecialite.value = seule;\n          etat.specialite = seule;\n        }\n      }\n      notifier();\n    });\n  }\n\n  function chargerClasses() {\n    vider(selectClasse, \"Choisir une classe\");\n    vider(selectSpecialite, \"Choisir une spécialité\");\n    selectClasse.disabled = true;\n    selectSpecialite.disabled = true;\n    etat.classe = \"\";\n    etat.specialite = \"\";\n    if (!etat.matiere) {\n      notifier();\n      return Promise.resolve();\n    }\n    return api(\"/info/classe/\" + encodeURIComponent(etat.matiere)).then(function (reponse) {\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Classes indisponibles\", \"erreur\");\n        notifier();\n        return;\n      }\n      remplir(selectClasse, reponse.data.classe, \"Choisir une classe\");\n      selectClasse.disabled = false;\n      if (valeurs && valeurs.classe) {\n        selectClasse.value = valeurs.classe;\n        if (selectClasse.value) {\n          etat.classe = valeurs.classe;\n          return chargerSpecialites();\n        }\n        valeurs = null;\n      }\n      const seuleClasse = valeurUnique(selectClasse);\n      if (seuleClasse) {\n        selectClasse.value = seuleClasse;\n        etat.classe = seuleClasse;\n        return chargerSpecialites();\n      }\n      notifier();\n    });\n  }\n\n  selectMatiere.addEventListener(\"change\", function () {\n    etat.matiere = selectMatiere.value;\n    valeurs = null;\n    chargerClasses();\n  });\n  selectClasse.addEventListener(\"change\", function () {\n    etat.classe = selectClasse.value;\n    valeurs = null;\n    chargerSpecialites();\n  });\n  selectSpecialite.addEventListener(\"change\", function () {\n    etat.specialite = selectSpecialite.value;\n    notifier();\n  });\n\n  return {\n    lire: choixComplet,\n    demarrer: function () {\n      vider(selectMatiere, \"Choisir une matière\");\n      vider(selectClasse, \"Choisir une classe\");\n      vider(selectSpecialite, \"Choisir une spécialité\");\n      return api(\"/info/matiere\").then(function (reponse) {\n        if (!reponse.ok) {\n          afficherStatut(\"statut\", reponse.data.error || \"Matières indisponibles\", \"erreur\");\n          return;\n        }\n        remplir(selectMatiere, reponse.data.matiere, \"Choisir une matière\");\n        if (valeurs && valeurs.matiere) {\n          selectMatiere.value = valeurs.matiere;\n          if (selectMatiere.value) {\n            etat.matiere = valeurs.matiere;\n            return chargerClasses();\n          }\n          valeurs = null;\n        }\n        const seuleMatiere = valeurUnique(selectMatiere);\n        if (seuleMatiere) {\n          selectMatiere.value = seuleMatiere;\n          etat.matiere = seuleMatiere;\n          return chargerClasses();\n        }\n      });\n    }\n  };\n}");
source("static/common.js", "creerSelect", "javascript", "  function creerSelect(etiquette) {\n    const bloc = document.createElement(\"label\");\n    bloc.className = \"champ\";\n    const span = document.createElement(\"span\");\n    span.textContent = etiquette;\n    const select = document.createElement(\"select\");\n    bloc.append(span, select);\n    racine.append(bloc);\n    return select;\n  }");
