source("static/common.js", "chargerSpecialites", "javascript", "  function chargerSpecialites() {\n    vider(selectSpecialite, \"Choisir une spécialité\");\n    selectSpecialite.disabled = true;\n    etat.specialite = \"\";\n    if (!etat.classe) {\n      notifier();\n      return Promise.resolve();\n    }\n    const url = \"/info/specialite/\"\n      + encodeURIComponent(etat.matiere) + \"/\"\n      + encodeURIComponent(etat.classe);\n    return api(url).then(function (reponse) {\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Spécialités indisponibles\", \"erreur\");\n        notifier();\n        return;\n      }\n      remplir(selectSpecialite, reponse.data.specialite, \"Choisir une spécialité\");\n      selectSpecialite.disabled = false;\n      if (valeurs && valeurs.specialite) {\n        selectSpecialite.value = valeurs.specialite;\n        if (selectSpecialite.value) etat.specialite = valeurs.specialite;\n        valeurs = null;\n      }\n      if (!etat.specialite) {\n        const seule = valeurUnique(selectSpecialite);\n        if (seule) {\n          selectSpecialite.value = seule;\n          etat.specialite = seule;\n        }\n      }\n      notifier();\n    });\n  }");
source("static/common.js", "chargerClasses", "javascript", "  function chargerClasses() {\n    vider(selectClasse, \"Choisir une classe\");\n    vider(selectSpecialite, \"Choisir une spécialité\");\n    selectClasse.disabled = true;\n    selectSpecialite.disabled = true;\n    etat.classe = \"\";\n    etat.specialite = \"\";\n    if (!etat.matiere) {\n      notifier();\n      return Promise.resolve();\n    }\n    return api(\"/info/classe/\" + encodeURIComponent(etat.matiere)).then(function (reponse) {\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Classes indisponibles\", \"erreur\");\n        notifier();\n        return;\n      }\n      remplir(selectClasse, reponse.data.classe, \"Choisir une classe\");\n      selectClasse.disabled = false;\n      if (valeurs && valeurs.classe) {\n        selectClasse.value = valeurs.classe;\n        if (selectClasse.value) {\n          etat.classe = valeurs.classe;\n          return chargerSpecialites();\n        }\n        valeurs = null;\n      }\n      const seuleClasse = valeurUnique(selectClasse);\n      if (seuleClasse) {\n        selectClasse.value = seuleClasse;\n        etat.classe = seuleClasse;\n        return chargerSpecialites();\n      }\n      notifier();\n    });\n  }");
source("static/common.js", "remplirNavigation", "javascript", "function remplirNavigation() {\n  const zone = document.getElementById(\"nav-compte\");\n  if (!zone) return;\n  api(\"/auth/me\").then(function (reponse) {\n    zone.replaceChildren();\n    const compte = reponse.ok ? reponse.data : null;\n    document.body.dataset.connecte = compte ? \"1\" : \"0\";\n    document.body.dataset.role = compte ? compte.role : \"\";\n    if (!compte) {\n      const lien = document.createElement(\"a\");\n      lien.href = \"/auth/login-page\";\n      lien.textContent = \"Connexion\";\n      zone.append(lien);\n    } else if (compte.must_change_password && window.location.pathname !== \"/auth/mot-de-passe\") {\n      window.location.assign(\"/auth/mot-de-passe\");\n      return;\n    } else {\n      const menuCompte = document.createElement(\"details\");\n      menuCompte.className = \"menu-liste\";\n      const resumeCompte = document.createElement(\"summary\");\n      resumeCompte.textContent = compte.name;\n      const panneauCompte = document.createElement(\"div\");\n      panneauCompte.className = \"menu-panneau\";\n      if (!compte.must_change_password) {\n        const espace = document.createElement(\"a\");\n        espace.href = lienEspace(compte.role);\n        espace.textContent = \"Mon espace\";\n        const motDePasse = document.createElement(\"a\");\n        motDePasse.href = \"/auth/mot-de-passe\";\n        motDePasse.textContent = \"Mot de passe\";\n        panneauCompte.append(espace, motDePasse);\n      }\n      const sortie = document.createElement(\"a\");\n      sortie.href = \"/auth/logout-page\";\n      sortie.textContent = \"Déconnexion\";\n      panneauCompte.append(sortie);\n      menuCompte.append(resumeCompte, panneauCompte);\n      zone.append(menuCompte);\n      const salut = document.getElementById(\"salut\");\n      if (salut) salut.textContent = \"Bonjour \" + compte.name + \" \" + compte.surname + \".\";\n    }\n    document.dispatchEvent(new CustomEvent(\"compte-connu\", { detail: compte }));\n  });\n}\n");
source("static/common.js", "demarrer", "javascript", "    demarrer: function () {\n      vider(selectMatiere, \"Choisir une matière\");\n      vider(selectClasse, \"Choisir une classe\");\n      vider(selectSpecialite, \"Choisir une spécialité\");\n      return api(\"/info/matiere\").then(function (reponse) {\n        if (!reponse.ok) {\n          afficherStatut(\"statut\", reponse.data.error || \"Matières indisponibles\", \"erreur\");\n          return;\n        }\n        remplir(selectMatiere, reponse.data.matiere, \"Choisir une matière\");\n        if (valeurs && valeurs.matiere) {\n          selectMatiere.value = valeurs.matiere;\n          if (selectMatiere.value) {\n            etat.matiere = valeurs.matiere;\n            return chargerClasses();\n          }\n          valeurs = null;\n        }\n        const seuleMatiere = valeurUnique(selectMatiere);\n        if (seuleMatiere) {\n          selectMatiere.value = seuleMatiere;\n          etat.matiere = seuleMatiere;\n          return chargerClasses();\n        }\n      });\n    }");
source("static/comptes.js", "dessiner", "javascript", "  function dessiner(liste) {\n    corps.replaceChildren();\n    liste.forEach(ajouterLigne);\n  }");
source("static/comptes.js", "cellule", "javascript", "  function cellule(texte) {\n    const td = document.createElement(\"td\");\n    td.textContent = texte;\n    return td;\n  }");
source("static/comptes.js", "ajouterLigne", "javascript", "  function ajouterLigne(compte) {\n    const ligne = document.createElement(\"tr\");\n    ligne.append(\n      cellule((compte.name || \"\") + \" \" + (compte.surname || \"\")),\n      cellule(compte.username || \"\"),\n      cellule(libelleRole(compte.role)),\n      cellule(compte.is_ban ? \"Suspendu\" : \"Actif\")\n    );\n    const actions = document.createElement(\"td\");\n\n    if (compte.id === moi) {\n      actions.textContent = \"C'est toi\";\n    } else if (compte.role === \"owner\") {\n      actions.textContent = \"Propriétaire\";\n    } else if (peutRoles || compte.role === \"user\") {\n      if (peutRoles) {\n        const select = document.createElement(\"select\");\n        [\n          [\"user\", \"Élève\"],\n          [\"moderator\", \"Modérateur\"],\n          [\"admin\", \"Administrateur\"]\n        ].forEach(function (paire) {\n          const option = document.createElement(\"option\");\n          option.value = paire[0];\n          option.textContent = paire[1];\n          if (paire[0] === compte.role) option.selected = true;\n          select.append(option);\n        });\n        const enregistrer = document.createElement(\"button\");\n        enregistrer.type = \"button\";\n        enregistrer.className = \"bouton bouton-secondaire\";\n        enregistrer.textContent = \"Changer le rôle\";\n        enregistrer.addEventListener(\"click\", function () {\n          enregistrer.disabled = true;\n          api(prefixe + \"/dashboard/role/\" + encodeURIComponent(compte.id), {\n            method: \"POST\",\n            json: { role: select.value }\n          }).then(function (reponse) {\n            enregistrer.disabled = false;\n            if (!reponse.ok) {\n              afficherStatut(\"statut\", reponse.data.error || \"Changement impossible\", \"erreur\");\n              return;\n            }\n            window.location.reload();\n          });\n        });\n        const barre = document.createElement(\"div\");\n        barre.className = \"ligne-actions\";\n        barre.append(select, enregistrer);\n        actions.append(barre);\n      }\n      if (peutRoles && compte.role === \"admin\") {\n        /* Un administrateur ne suspend pas un autre administrateur. */\n      } else {\n        const suspendre = document.createElement(\"button\");\n        suspendre.type = \"button\";\n        suspendre.className = \"bouton bouton-danger\";\n        suspendre.textContent = compte.is_ban ? \"Réactiver\" : \"Suspendre\";\n        suspendre.addEventListener(\"click\", function () {\n          const action = compte.is_ban ? \"unban\" : \"ban\";\n          const question = compte.is_ban\n            ? \"Réactiver ce compte ?\"\n            : \"Suspendre ce compte ? Il ne pourra plus se connecter.\";\n          if (!window.confirm(question)) return;\n          api(prefixe + \"/dashboard/\" + action + \"/\" + encodeURIComponent(compte.id), {\n            method: \"POST\"\n          }).then(function (reponse) {\n            if (!reponse.ok) {\n              afficherStatut(\"statut\", reponse.data.error || \"Action impossible\", \"erreur\");\n              return;\n            }\n            window.location.reload();\n          });\n        });\n        actions.append(suspendre);\n      }\n    } else {\n      actions.textContent = \"Aucune action\";\n    }\n\n    ligne.append(actions);\n    corps.append(ligne);\n  }");
source("static/espace.js", "remplir", "javascript", "  function remplir(zone, fiches, avecActions) {\n    zone.replaceChildren();\n    if (!fiches.length) {\n      const vide = document.createElement(\"p\");\n      vide.className = \"vide\";\n      vide.textContent = \"Rien ici pour le moment.\";\n      zone.append(vide);\n      return;\n    }\n    fiches.forEach(function (fiche) {\n      const actions = avecActions ? [\n        {\n          libelle: \"Modifier\",\n          href: \"/users/dashboard/modify/\" + encodeURIComponent(fiche.id)\n        },\n        {\n          libelle: \"Supprimer\",\n          classe: \"bouton-danger\",\n          onClick: function () {\n            supprimerFiche(\"/users/dashboard/delete/\" + encodeURIComponent(fiche.id));\n          }\n        }\n      ] : [];\n      zone.append(carteFiche(fiche, actions));\n    });\n  }");
source("static/espace.js", "onClick", "javascript", "          onClick: function () {\n            supprimerFiche(\"/users/dashboard/delete/\" + encodeURIComponent(fiche.id));\n          }");
source("static/staff.js", "charger", "javascript", "  function charger() {\n    fichiers.replaceChildren();\n    if (!choix) return;\n    const attente = document.createElement(\"p\");\n    attente.className = \"vide\";\n    attente.textContent = \"Chargement des fiches…\";\n    fichiers.append(attente);\n    const url = \"/info/files/\"\n      + encodeURIComponent(choix.matiere) + \"/\"\n      + encodeURIComponent(choix.classe) + \"/\"\n      + encodeURIComponent(choix.specialite);\n    api(url).then(function (reponse) {\n      fichiers.replaceChildren();\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Fiches indisponibles\", \"erreur\");\n        return;\n      }\n      const liste = reponse.data.metadata || [];\n      if (!liste.length) {\n        const vide = document.createElement(\"p\");\n        vide.className = \"vide\";\n        vide.textContent = \"Aucune fiche pour ce cours.\";\n        fichiers.append(vide);\n        return;\n      }\n      liste.forEach(function (fiche) {\n        if (!fiche || !fiche.id) return;\n        const actions = [\n          {\n            libelle: \"Modifier\",\n            href: prefixe + \"/dashboard/modify/\" + encodeURIComponent(fiche.id)\n          },\n          {\n            libelle: \"Supprimer\",\n            classe: \"bouton-danger\",\n            onClick: function () {\n              supprimerFiche(prefixe + \"/dashboard/delete/\" + encodeURIComponent(fiche.id));\n            }\n          }\n        ];\n        fichiers.append(carteFiche(fiche, actions));\n      });\n    });\n  }");
source("static/staff.js", "onClick", "javascript", "            onClick: function () {\n              supprimerFiche(prefixe + \"/dashboard/delete/\" + encodeURIComponent(fiche.id));\n            }");
source("static/staff.js", "onChange", "javascript", "    onChange: function (nouveau) {\n      choix = nouveau;\n      charger();\n    }");
source("static/modifier.js", "Formulaire de modification", "javascript", "/* Formulaire de modification, commun à l'élève, au modérateur et à l'admin. */\n\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  const metadata = lireJson(\"fiche-data\") || {};\n  const formulaire = document.getElementById(\"form-modifier\");\n  const selecteur = monterSelecteur(document.getElementById(\"selecteur\"), {\n    valeurs: {\n      matiere: metadata.matiere,\n      classe: metadata.classe,\n      specialite: metadata.specialite\n    }\n  });\n  selecteur.demarrer();\n\n  formulaire.addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    const choix = selecteur.lire();\n    if (!choix) {\n      afficherStatut(\"statut\", \"Choisis une matière, une classe et une spécialité.\", \"erreur\");\n      return;\n    }\n    const bouton = formulaire.querySelector(\"button[type=submit]\");\n    bouton.disabled = true;\n    const data = new FormData(formulaire);\n    data.set(\"matiere\", choix.matiere);\n    data.set(\"classe\", choix.classe);\n    data.set(\"specialite\", choix.specialite);\n    api(formulaire.dataset.saveUrl, { method: \"POST\", body: data }).then(function (reponse) {\n      bouton.disabled = false;\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Enregistrement impossible\", \"erreur\");\n        return;\n      }\n      window.location.assign(formulaire.dataset.retourUrl);\n    });\n  });\n});\n");
source("auth/static/login.js", "Formulaire de connexion", "javascript", "/* Formulaire de connexion. Le mot de passe part en JSON, jamais dans l'adresse. */\n\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  const config = lireJson(\"login-config\") || { next: \"/accueil\" };\n  const formulaire = document.getElementById(\"form-login\");\n\n  document.addEventListener(\"compte-connu\", function (event) {\n    if (!event.detail) return;\n    if (event.detail.must_change_password) {\n      window.location.assign(\"/auth/mot-de-passe\");\n      return;\n    }\n    const suivant = config.next && config.next !== \"/accueil\"\n      ? config.next\n      : lienEspace(event.detail.role);\n    window.location.assign(suivant);\n  });\n\n  formulaire.addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    const bouton = formulaire.querySelector(\"button\");\n    bouton.disabled = true;\n    api(\"/auth/login\", {\n      method: \"POST\",\n      json: {\n        username: formulaire.username.value.trim(),\n        password: formulaire.password.value\n      }\n    }).then(function (reponse) {\n      bouton.disabled = false;\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Connexion impossible\", \"erreur\");\n        return;\n      }\n      if (reponse.data.must_change_password) {\n        window.location.assign(\"/auth/mot-de-passe\");\n        return;\n      }\n      if (config.next && config.next !== \"/accueil\" && config.next !== \"/auth/login-page\") {\n        window.location.assign(config.next);\n        return;\n      }\n      window.location.assign(reponse.data.home || lienEspace(reponse.data.role));\n    });\n  });\n});\n");
source("auth/static/logout.js", "Formulaire de déconnexion", "javascript", "/* Confirme la sortie, puis efface les cookies de session. */\n\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  document.getElementById(\"form-sortie\").addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    api(\"/auth/logout\", { method: \"POST\" }).then(function (reponse) {\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Déconnexion impossible\", \"erreur\");\n        return;\n      }\n      window.location.assign(\"/accueil\");\n    });\n  });\n});\n");
source("auth/static/mot-de-passe.js", "Formulaire du mot de passe", "javascript", "/* Changement de mot de passe. L'ancien et le nouveau partent en JSON, pas dans l'adresse. */\n\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  const config = lireJson(\"mot-de-passe-config\") || { obligatoire: false, retour: \"/accueil\" };\n  const formulaire = document.getElementById(\"form-mot-de-passe\");\n\n  formulaire.addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    const bouton = formulaire.querySelector(\"button\");\n    bouton.disabled = true;\n    api(\"/auth/mot-de-passe\", {\n      method: \"POST\",\n      json: {\n        actuel: formulaire.actuel.value,\n        nouveau: formulaire.nouveau.value,\n        confirmation: formulaire.confirmation.value\n      }\n    }).then(function (reponse) {\n      bouton.disabled = false;\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Changement impossible\", \"erreur\");\n        return;\n      }\n      window.location.assign(reponse.data.home || config.retour || \"/accueil\");\n    });\n  });\n});\n");
source("static/style.css", ":root", "css", ":root {\n  --encre: #1c2430;\n  --encre-douce: #4d5968;\n  --papier: #f4efe4;\n  --carte: #fffdf8;\n  --ligne: #e4d9c6;\n  --foret: #1d6b4f;\n  --foret-fonce: #14543d;\n  --danger: #8d2f2f;\n  --focus: #b86b12;\n  --ombre: 0 10px 30px rgba(48, 36, 18, 0.06);\n}\n");
source("static/style.css", "body", "css", "body {\n  margin: 0;\n  min-height: 100vh;\n  color: var(--encre);\n  background:\n    radial-gradient(circle at top left, rgba(29, 107, 79, 0.08), transparent 28rem),\n    var(--papier);\n  font-family: \"Segoe UI\", \"Helvetica Neue\", sans-serif;\n  line-height: 1.5;\n}\n");
source("static/style.css", ".passer", "css", ".passer {\n  position: absolute;\n  left: 1rem;\n  top: -3rem;\n  background: var(--encre);\n  color: white;\n  padding: 0.4rem 0.7rem;\n}\n");
