source("static/style.css", ".panneau", "css", ".panneau {\n  background: var(--carte);\n  border: 1px solid var(--ligne);\n  border-radius: 16px;\n  padding: 1.2rem;\n  margin: 1rem 0;\n  box-shadow: var(--ombre);\n}\n");
