source("static/style.css", ".selecteur et .champ", "css", ".selecteur, .champ { display: grid; gap: 0.35rem; }\n\n\n.selecteur { gap: 0.9rem; }\n\n\n.champ { display: grid; gap: 0.35rem; }\n");
source("static/style.css", "champs de saisie", "css", "input, select, textarea {\n  width: 100%;\n  padding: 0.65rem 0.75rem;\n  border: 1px solid #cbbfaa;\n  border-radius: 10px;\n  background: white;\n  color: var(--encre);\n  font: inherit;\n}\n\n\ntextarea {\n  width: 100%;\n  padding: 0.65rem 0.75rem;\n  border: 1px solid #cbbfaa;\n  border-radius: 10px;\n  background: white;\n  color: var(--encre);\n  font: inherit;\n}\n\n\ninput:focus, select:focus, textarea:focus, button:focus-visible, a:focus-visible {\n  outline: 3px solid var(--focus);\n  outline-offset: 2px;\n}\n");
source("static/style.css", ".bouton", "css", ".bouton, button.bouton {\n  display: inline-block;\n  border: 0;\n  border-radius: 999px;\n  padding: 0.6rem 1rem;\n  background: var(--foret);\n  color: white;\n  text-decoration: none;\n  cursor: pointer;\n  font: inherit;\n}\n\n\n.bouton:hover { background: var(--foret-fonce); }\n\n\n.bouton:disabled { opacity: 0.6; cursor: wait; }\n");
source("static/style.css", ".bouton-secondaire", "css", ".bouton-secondaire {\n  background: transparent;\n  color: var(--foret-fonce);\n  border: 1px solid var(--foret);\n}\n");
source("static/style.css", ".bouton-danger", "css", ".bouton-danger {\n  background: transparent;\n  color: var(--danger);\n  border: 1px solid var(--danger);\n}\n");
source("static/style.css", ".actions", "css", ".actions, .ligne-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.6rem;\n  margin-top: 0.8rem;\n}\n");
source("static/style.css", ".fiche", "css", ".fiche {\n  border: 1px solid var(--ligne);\n  border-radius: 12px;\n  padding: 1rem;\n  margin: 0.8rem 0;\n  background: #fff;\n}\n\n\n.fiche h3 { margin: 0 0 0.3rem; }\n");
source("static/style.css", ".etoile", "css", ".etoile[aria-pressed=\"true\"] {\n  background: #f4e4b3;\n  color: #6a4b00;\n  border-color: #c4a15a;\n}\n");
source("static/style.css", ".recherche", "css", ".recherche {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));\n  gap: 0.6rem 0.8rem;\n  align-items: end;\n}\n");
source("static/style.css", ".commentaires", "css", ".commentaires { margin-top: 0.8rem; }\n\n\n.commentaire {\n  border-top: 1px solid var(--ligne);\n  margin-top: 0.8rem;\n  padding-top: 0.6rem;\n}\n\n\n.commentaire-form, .commentaires form {\n  display: grid;\n  gap: 0.5rem;\n}\n");
source("static/style.css", ".meta, .note, .fichier, .pied", "css", ".meta, .note, .fichier, .pied {\n  color: var(--encre-douce);\n}\n");
source("static/style.css", ".statut", "css", ".statut { min-height: 1.4rem; font-weight: 650; }\n\n\n.statut.ok { color: var(--foret-fonce); }\n\n\n.statut.erreur { color: var(--danger); }\n");
source("static/style.css", ".grille-stats", "css", ".grille-stats {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(11.5rem, 1fr));\n  gap: 0.75rem;\n  margin: 0.6rem 0 1rem;\n}\n");
source("static/style.css", ".stat", "css", ".stat {\n  background: #fff;\n  border: 1px solid var(--ligne);\n  border-radius: 14px;\n  padding: 0.85rem 1rem;\n}\n\n\n.stat strong {\n  display: block;\n  font-size: 1.35rem;\n  font-variant-numeric: tabular-nums;\n}\n\n\n.stat span, .stat small {\n  display: block;\n  color: var(--encre-douce);\n}\n");
source("static/style.css", ".banniere", "css", ".banniere {\n  border: 1px solid var(--danger);\n  background: #f8ecec;\n  border-radius: 12px;\n  padding: 0.8rem 1rem;\n}\n");
source("static/style.css", ".badge", "css", ".badge {\n  display: inline-block;\n  background: #e5f4ec;\n  color: var(--foret-fonce);\n  border-radius: 999px;\n  padding: 0.1rem 0.55rem;\n  font-size: 0.85rem;\n}\n");
source("static/style.css", ".vide", "css", ".vide { color: var(--encre-douce); }\n");
source("static/style.css", ".table-scroll et .comptes", "css", ".table-scroll { overflow-x: auto; }\n\n\ntable.comptes {\n  width: 100%;\n  border-collapse: collapse;\n  background: var(--carte);\n}\n\n\n.comptes th, .comptes td {\n  text-align: left;\n  padding: 0.7rem;\n  border-bottom: 1px solid var(--ligne);\n  vertical-align: top;\n}\n\n\n.comptes select { min-width: 10rem; }\n");
source("static/style.css", ".pied", "css", ".pied {\n  color: var(--encre-douce);\n}\n\n.statut { min-height: 1.4rem; font-weight: 650; }\n\n.grille-stats {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(11.5rem, 1fr));\n  gap: 0.75rem;\n  margin: 0.6rem 0 1rem;\n}\n\n.stat {\n  background: #fff;\n  border: 1px solid var(--ligne);\n  border-radius: 14px;\n  padding: 0.85rem 1rem;\n}\n\n.stat strong {\n  display: block;\n  font-size: 1.35rem;\n  font-variant-numeric: tabular-nums;\n}\n\n.stat span, .stat small {\n  display: block;\n  color: var(--encre-douce);\n}\n\n.stat small { font-size: 0.82rem; }\n\n.banniere {\n  border: 1px solid var(--danger);\n  background: #f8ecec;\n  border-radius: 12px;\n  padding: 0.8rem 1rem;\n}\n\n.badge {\n  display: inline-block;\n  background: #e5f4ec;\n  color: var(--foret-fonce);\n  border-radius: 999px;\n  padding: 0.1rem 0.55rem;\n  font-size: 0.85rem;\n}\n\n.statut.ok { color: var(--foret-fonce); }\n\n.statut.erreur { color: var(--danger); }\n\n.vide { color: var(--encre-douce); }\n\n.table-scroll { overflow-x: auto; }\n\ntable.comptes {\n  width: 100%;\n  border-collapse: collapse;\n  background: var(--carte);\n}\n\n.comptes th, .comptes td {\n  text-align: left;\n  padding: 0.7rem;\n  border-bottom: 1px solid var(--ligne);\n  vertical-align: top;\n}\n\n.comptes select { min-width: 10rem; }\n\n.pied {\n  text-align: center;\n  padding: 1.2rem 1rem 5rem;\n}\n");
source("static/style.css", "[hidden]", "css", "[hidden] { display: none !important; }\n");
source("static/style.css", "petit écran", "css", "@media (max-width: 700px) {\n  .barre { align-items: flex-start; flex-direction: column; }\n  main { width: min(100% - 1.2rem, 980px); }\n}\n");
source("templates/base.html", "Squelette commun", "html", "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>{% block titre %}Fiches de révision{% endblock %}</title>\n  <link rel=\"stylesheet\" href=\"{{ url_for('static', filename='style.css') }}\">\n</head>\n<body>\n  <!-- Le lien d'évitement sert à sauter le menu au clavier. -->\n  <a class=\"passer\" href=\"#contenu\">Aller au contenu</a>\n  <header class=\"barre\">\n    <a class=\"marque\" href=\"/accueil\">Fiches</a>\n    <nav class=\"menu\" aria-label=\"Navigation\">\n      <a href=\"/accueil\">Accueil</a>\n      <span id=\"nav-compte\"></span>\n    </nav>\n  </header>\n  <main id=\"contenu\">\n    {% block contenu %}{% endblock %}\n  </main>\n  <footer class=\"pied\">\n    <p>Partage de fiches entre élèves</p>\n    <nav class=\"menu-legal\" aria-label=\"Informations légales\">\n      <a href=\"/legal/mentions\">Mentions légales</a>\n      <a href=\"/legal/confidentialite\">Politique de confidentialité</a>\n      <a href=\"/legal/cookies\">Gestion des cookies</a>\n      <a href=\"/legal/licences\">Licences</a>\n    </nav>\n  </footer>\n  <div id=\"banniere-cookies\" class=\"banniere-cookies\" hidden>\n    <p>Seuls les cookies de connexion et de sécurité sont déposés. Pas de mesure d'audience.</p>\n    <a href=\"/legal/cookies\">Gestion des cookies</a>\n    <button id=\"cookies-ok\" class=\"bouton\" type=\"button\">J'ai compris</button>\n  </div>\n  <script src=\"{{ url_for('static', filename='common.js') }}\"></script>\n  {% block scripts %}{% endblock %}\n</body>\n</html>\n");
source("templates/index.html", "Accueil", "html", "{% extends \"base.html\" %}\n{% block titre %}Accueil — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"intro\">\n    <h1>Fiches de révision</h1>\n    <p id=\"salut\" class=\"salut\"></p>\n    <p>Choisis un cours. Les fiches s'affichent tout de suite. La publication demande un compte.</p>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Cours</h2>\n    <div id=\"selecteur\" class=\"selecteur\"></div>\n  </section>\n\n  <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n\n  <section class=\"panneau\">\n    <h2>Rechercher une fiche</h2>\n    <p class=\"note\">Le texte cherche dans le titre, la description, l'auteur et le nom du fichier. La liste suit la saisie. Le cours se choisit dans le menu.</p>\n    <form id=\"form-recherche\" class=\"recherche\">\n      <label class=\"champ\">Texte\n        <input type=\"search\" name=\"q\" maxlength=\"120\" autocomplete=\"off\">\n      </label>\n      <label class=\"champ\">Auteur\n        <input type=\"text\" name=\"auteur\" maxlength=\"80\" autocomplete=\"off\">\n      </label>\n      <label class=\"champ\">Étoiles minimum\n        <input type=\"number\" name=\"etoiles_min\" min=\"0\" max=\"1000000\" inputmode=\"numeric\">\n      </label>\n    </form>\n    <div id=\"resultats\" class=\"liste\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Fiches disponibles</h2>\n    <div id=\"fichiers\" class=\"liste\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Publier une fiche</h2>\n    <p id=\"invite-connexion\" hidden>\n      <a href=\"/auth/login-page?next=/accueil\">Connecte-toi</a> pour publier dans ce cours.\n    </p>\n    <!-- L'auteur n'est pas demandé : le serveur enregistre l'identifiant du compte. -->\n    <form id=\"form-envoi\" hidden>\n      <label class=\"champ\">Fichier\n        <input type=\"file\" name=\"file\" required\n          accept=\".pdf,.txt,.md,.csv,.png,.jpg,.jpeg,.gif,.webp,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.odt,.odp,.ods,.zip\">\n      </label>\n      <label class=\"champ\">Titre\n        <input type=\"text\" name=\"title\" required maxlength=\"120\" autocomplete=\"off\">\n      </label>\n      <label class=\"champ\">Description\n        <textarea name=\"desc\" required maxlength=\"2000\" rows=\"4\"></textarea>\n      </label>\n      <p class=\"note\">PDF, image, document ou zip. 100 Mo maximum. Le HTML n'est pas accepté.</p>\n      <button class=\"bouton\" type=\"submit\">Publier</button>\n    </form>\n  </section>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='accueil.js') }}\"></script>\n{% endblock %}\n");
source("templates/user_dashboard.html", "Espace élève", "html", "{% extends \"base.html\" %}\n{% block titre %}Mon espace — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"intro\">\n    <h1>Mon espace</h1>\n    <p>Bonjour {{ profil.name }} {{ profil.surname }}. Voici tes fiches.</p>\n    <details class=\"menu-liste\">\n      <summary>Mon menu</summary>\n      <div class=\"menu-panneau\">\n        <a href=\"/users/audit\">Audit de mes fiches</a>\n        <a href=\"/accueil\">Publier une fiche</a>\n      </div>\n    </details>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Mes envois</h2>\n    <div id=\"envoyes\" class=\"liste\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Mes téléchargements</h2>\n    <div id=\"telecharges\" class=\"liste\"></div>\n  </section>\n  <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n  <script id=\"fiches-data\" type=\"application/json\">{{ {\"envoyes\": envoyes, \"telecharges\": telecharges}|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='espace.js') }}\"></script>\n{% endblock %}\n");
source("templates/audit_perso.html", "Audit de mes fiches", "html", "{% extends \"base.html\" %}\n{% block titre %}{{ titre }} — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"intro\">\n    <h1>Audit de mes fiches</h1>\n    <p>Bonjour {{ profil.name }} {{ profil.surname }}. Ce relevé ne contient que tes fiches : pas celles des autres, pas les sessions du site.</p>\n    <details class=\"menu-liste\">\n      <summary>Actions</summary>\n      <div class=\"menu-panneau\">\n        <a href=\"/users/dashboard\">Retour à mes fiches</a>\n        <button id=\"bouton-actualiser\" type=\"button\">Actualiser</button>\n      </div>\n    </details>\n  </section>\n  <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n\n  <section class=\"panneau\">\n    <h2>Mes chiffres</h2>\n    <div id=\"graphique-perso\" class=\"graphiques\"></div>\n    <div id=\"zone-resume\" class=\"grille-stats\" hidden></div>\n    <p id=\"zone-plus\" class=\"note\"></p>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Mes fiches</h2>\n    <div id=\"zone-fiches\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Commentaires que je peux lire</h2>\n    <p class=\"note\">Un commentaire réservé à l'équipe n'apparaît pas ici. Ceux que tu vois servent à corriger tes fiches.</p>\n    <div id=\"zone-commentaires\"></div>\n  </section>\n\n  <script id=\"audit-data\" type=\"application/json\">{{ audit|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='graphiques.js') }}\"></script>\n  <script src=\"{{ url_for('static', filename='audit_perso.js') }}\"></script>\n{% endblock %}\n");
source("templates/audit.html", "Audit du propriétaire", "html", "{% extends \"base.html\" %}\n{% block titre %}{{ titre }} — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"intro\" id=\"zone-pilotage\">\n    <h1>Audit du site</h1>\n    <p>Bonjour {{ profil.name }} {{ profil.surname }}. Ce relevé est réservé au propriétaire.</p>\n    <p id=\"etat-site\" class=\"note\"></p>\n    <details class=\"menu-liste\">\n      <summary>Pilotage</summary>\n      <div class=\"menu-panneau\">\n        <button id=\"bouton-site\" type=\"button\">Suspendre le site</button>\n        <button id=\"bouton-actualiser\" type=\"button\">Actualiser</button>\n        <a href=\"/admin/dashboard\">Modérer les fiches</a>\n        <a href=\"/admin/comptes-page\">Gérer les comptes</a>\n      </div>\n    </details>\n  </section>\n  <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n\n  <div class=\"onglets\" role=\"tablist\" aria-label=\"Sections de l'audit\">\n    <button type=\"button\" role=\"tab\" data-onglet=\"vue\" aria-selected=\"true\">Vue d'ensemble</button>\n    <button type=\"button\" role=\"tab\" data-onglet=\"sessions\" aria-selected=\"false\">Sessions</button>\n    <button type=\"button\" role=\"tab\" data-onglet=\"contenu\" aria-selected=\"false\">Contenu</button>\n    <button type=\"button\" role=\"tab\" data-onglet=\"etoiles\" aria-selected=\"false\">Étoiles</button>\n    <button type=\"button\" role=\"tab\" data-onglet=\"securite\" aria-selected=\"false\">Sécurité</button>\n  </div>\n\n  <div id=\"onglet-vue\" class=\"onglet\">\n    <section class=\"panneau\">\n      <h2>Vue d'ensemble</h2>\n      <div id=\"graphiques\" class=\"graphiques\"></div>\n    </section>\n  </div>\n\n  <div id=\"onglet-sessions\" class=\"onglet\" hidden>\n  <section class=\"panneau\">\n    <h2>Utilisateurs connectés</h2>\n    <p class=\"note\">Une session reste dans la liste jusqu'à expiration du jeton ou déconnexion. « En ligne » veut dire une activité dans les 15 dernières minutes. La page se rafraîchit toute seule.</p>\n    <div id=\"zone-sessions\"></div>\n  </section>\n\n  </div>\n\n  <div id=\"onglet-contenu\" class=\"onglet\" hidden>\n  <section class=\"panneau\">\n    <h2>Stockage</h2>\n    <div id=\"zone-stockage\" class=\"grille-stats\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Comptes</h2>\n    <div id=\"zone-comptes\" class=\"grille-stats\"></div>\n    <p id=\"zone-anciennete\" class=\"note\"></p>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Activité</h2>\n    <div id=\"zone-activite\" class=\"grille-stats\"></div>\n    <h3>Comptes qui publient le plus</h3>\n    <div id=\"zone-auteurs\"></div>\n    <h3>Comptes qui téléchargent le plus</h3>\n    <div id=\"zone-lecteurs\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Contenu</h2>\n    <div id=\"zone-contenu\" class=\"grille-stats\"></div>\n    <h3>Par matière</h3>\n    <div id=\"zone-matieres\"></div>\n    <h3>Par classe</h3>\n    <div id=\"zone-classes\"></div>\n    <h3>Par type de fichier</h3>\n    <div id=\"zone-extensions\"></div>\n    <h3>Plus gros fichiers</h3>\n    <div id=\"zone-gros\"></div>\n    <h3>Fiches les plus récentes</h3>\n    <div id=\"zone-recentes\"></div>\n    <h3>Cours sans fiche</h3>\n    <div id=\"zone-vides\"></div>\n    <h3>Fichiers orphelins</h3>\n    <p class=\"note\">Présents dans uploads/ mais rattachés à aucune fiche valide.</p>\n    <div id=\"zone-orphelins\"></div>\n    <p id=\"zone-types\" class=\"note\"></p>\n  </section>\n  </div>\n\n  <div id=\"onglet-etoiles\" class=\"onglet\" hidden>\n  <section class=\"panneau\">\n    <h2>Étoiles</h2>\n    <p class=\"note\">La fiche la plus étoilée du site, puis la ou les fiches en tête de chaque matière.</p>\n    <div id=\"zone-etoiles\" class=\"grille-stats\"></div>\n    <h3>La plus étoilée</h3>\n    <div id=\"zone-etoile-globale\"></div>\n    <h3>En tête par matière</h3>\n    <div id=\"zone-etoiles-matiere\"></div>\n  </section>\n  </div>\n\n  <div id=\"onglet-securite\" class=\"onglet\" hidden>\n  <section class=\"panneau\">\n    <h2>Sécurité</h2>\n    <div id=\"zone-securite\" class=\"grille-stats\"></div>\n    <h3>Identifiants bloqués après trop d'échecs</h3>\n    <div id=\"zone-bloques\"></div>\n    <h3>Comptes suspendus</h3>\n    <div id=\"zone-bannis\"></div>\n  </section>\n  </div>\n\n  <script id=\"audit-data\" type=\"application/json\">{{ audit|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='graphiques.js') }}\"></script>\n  <script src=\"{{ url_for('static', filename='audit.js') }}\"></script>\n{% endblock %}\n");
source("templates/staff_dashboard.html", "Espace modération ou administration", "html", "{% extends \"base.html\" %}\n{% block titre %}{{ titre }} — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"intro\">\n    <h1>{{ titre }}</h1>\n    <p>Bonjour {{ profil.name }} {{ profil.surname }}.</p>\n    <details class=\"menu-liste\">\n      <summary>Menu</summary>\n      <div class=\"menu-panneau\">\n        <a href=\"{{ comptes_url }}\">Gérer les comptes</a>\n        <a href=\"/accueil\">Voir l'accueil</a>\n      </div>\n    </details>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Rechercher une fiche</h2>\n    <p class=\"note\">Titre, description, auteur, fichier ou nombre d'étoiles. La liste suit la saisie. Le cours se choisit dans le menu.</p>\n    <form id=\"form-recherche\" class=\"recherche\">\n      <label class=\"champ\">Texte\n        <input type=\"search\" name=\"q\" maxlength=\"120\" autocomplete=\"off\">\n      </label>\n      <label class=\"champ\">Auteur\n        <input type=\"text\" name=\"auteur\" maxlength=\"80\" autocomplete=\"off\">\n      </label>\n      <label class=\"champ\">Étoiles minimum\n        <input type=\"number\" name=\"etoiles_min\" min=\"0\" max=\"1000000\" inputmode=\"numeric\">\n      </label>\n    </form>\n    <div id=\"resultats\" class=\"liste\"></div>\n  </section>\n\n  <section class=\"panneau\">\n    <h2>Choisir un cours</h2>\n    <div id=\"selecteur\" class=\"selecteur\"></div>\n  </section>\n  <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n  <section class=\"panneau\">\n    <h2>Fiches</h2>\n    <div id=\"fichiers\" class=\"liste\"></div>\n  </section>\n  <div id=\"staff-config\" data-prefix=\"{{ prefix }}\" hidden></div>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='staff.js') }}\"></script>\n{% endblock %}\n");
source("templates/comptes.html", "Gestion des comptes", "html", "{% extends \"base.html\" %}\n{% block titre %}{{ titre }} — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"intro\">\n    <h1>{{ titre }}</h1>\n    <p>Les actions impossibles pour ton rôle ne sont pas proposées. Le serveur les refuse aussi.</p>\n    <p><a class=\"bouton bouton-secondaire\" href=\"{{ prefix }}/dashboard\">Retour aux fiches</a></p>\n  </section>\n  <section class=\"panneau\">\n    <h2>Rechercher un compte</h2>\n    <p class=\"note\">Nom, prénom, identifiant, rôle ou état. Le tableau suit la saisie et les listes. Le mot de passe n'est jamais affiché.</p>\n    <form id=\"form-recherche\" class=\"recherche\">\n      <label class=\"champ\">Nom, prénom ou identifiant\n        <input type=\"search\" name=\"q\" maxlength=\"80\" autocomplete=\"off\">\n      </label>\n      <label class=\"champ\">Rôle\n        <select name=\"role\">\n          <option value=\"\">Tous</option>\n          <option value=\"user\">Élève</option>\n          <option value=\"moderator\">Modérateur</option>\n          <option value=\"admin\">Administrateur</option>\n          <option value=\"owner\">Propriétaire</option>\n        </select>\n      </label>\n      <label class=\"champ\">État\n        <select name=\"etat\">\n          <option value=\"\">Tous</option>\n          <option value=\"actif\">Actif</option>\n          <option value=\"suspendu\">Suspendu</option>\n        </select>\n      </label>\n      <button id=\"bouton-tous\" class=\"bouton bouton-secondaire\" type=\"button\">Tout afficher</button>\n    </form>\n  </section>\n  <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n  <div class=\"table-scroll\">\n    <table class=\"comptes\">\n      <thead>\n        <tr>\n          <th>Nom</th>\n          <th>Identifiant</th>\n          <th>Rôle</th>\n          <th>État</th>\n          <th>Actions</th>\n        </tr>\n      </thead>\n      <tbody id=\"corps-comptes\"></tbody>\n    </table>\n  </div>\n  <div id=\"comptes-config\" data-prefix=\"{{ prefix }}\" data-roles=\"{{ '1' if peut_roles else '0' }}\" data-moi=\"{{ profil.id }}\" hidden></div>\n  <script id=\"comptes-data\" type=\"application/json\">{{ comptes|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='comptes.js') }}\"></script>\n{% endblock %}\n");
source("templates/modifier.html", "Modifier une fiche", "html", "{% extends \"base.html\" %}\n{% block titre %}{{ titre }} — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"panneau etroit\">\n    <h1>{{ titre }}</h1>\n    <p>Auteur enregistré : {{ metadata.author }}</p>\n    <form id=\"form-modifier\" data-save-url=\"{{ save_url }}\" data-retour-url=\"{{ retour_url }}\">\n      <div id=\"selecteur\" class=\"selecteur\"></div>\n      <label class=\"champ\">Titre\n        <input type=\"text\" name=\"title\" required maxlength=\"120\" value=\"{{ metadata.title }}\">\n      </label>\n      <label class=\"champ\">Description\n        <textarea name=\"desc\" required maxlength=\"2000\" rows=\"5\">{{ metadata.desc }}</textarea>\n      </label>\n      <label class=\"champ\">Remplacer le fichier (facultatif)\n        <input type=\"file\" name=\"file\"\n          accept=\".pdf,.txt,.md,.csv,.png,.jpg,.jpeg,.gif,.webp,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.odt,.odp,.ods,.zip\">\n      </label>\n      <p class=\"note\">Fichier actuel : {{ metadata.original_filename }}</p>\n      <div class=\"actions\">\n        <button class=\"bouton\" type=\"submit\">Enregistrer</button>\n        <a class=\"bouton bouton-secondaire\" href=\"{{ retour_url }}\">Annuler</a>\n      </div>\n    </form>\n    <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n  </section>\n  <script id=\"fiche-data\" type=\"application/json\">{{ metadata|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='modifier.js') }}\"></script>\n{% endblock %}\n");
source("templates/erreur.html", "Page d'erreur", "html", "{% extends \"base.html\" %}\n{% block titre %}Erreur — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"panneau etroit\">\n    <h1>Oups</h1>\n    <p>{{ message }}</p>\n    <p><a class=\"bouton\" href=\"/accueil\">Retour à l'accueil</a></p>\n  </section>\n{% endblock %}\n");
source("templates/suspendu.html", "Site suspendu", "html", "{% extends \"base.html\" %}\n{% block titre %}Site suspendu — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"panneau etroit\">\n    <h1>Site suspendu</h1>\n    <p>Le propriétaire a mis le site en pause. Les fiches, les envois et les téléchargements sont indisponibles.</p>\n    {% if depuis %}\n      <p class=\"note\">Depuis le {{ depuis }}.</p>\n    {% endif %}\n    <p>Si tu es le propriétaire, connecte-toi pour réactiver le site.</p>\n    <p><a class=\"bouton\" href=\"/auth/login-page\">Connexion</a></p>\n  </section>\n{% endblock %}\n");
source("auth/login/login.html", "Connexion", "html", "{% extends \"base.html\" %}\n{% block titre %}Connexion — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"panneau etroit\">\n    <h1>Connexion</h1>\n    {% if site_suspendu %}\n      <p class=\"statut erreur\">Le site est suspendu. Seul le propriétaire peut se connecter pour le réactiver.</p>\n    {% endif %}\n    <p>Utilise le compte créé par <code>init_users.py</code>.</p>\n    <form id=\"form-login\">\n      <label class=\"champ\">Identifiant\n        <input type=\"text\" name=\"username\" required maxlength=\"80\" autocomplete=\"username\" autofocus>\n      </label>\n      <label class=\"champ\">Mot de passe\n        <input type=\"password\" name=\"password\" required maxlength=\"200\" autocomplete=\"current-password\">\n      </label>\n      <button class=\"bouton\" type=\"submit\">Entrer</button>\n    </form>\n    <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n    <p><a href=\"/accueil\">Retour à l'accueil</a></p>\n  </section>\n  <script id=\"login-config\" type=\"application/json\">{{ {\"next\": next_url}|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('auth.static', filename='login.js') }}\"></script>\n{% endblock %}\n");
source("auth/logout/logout.html", "Déconnexion", "html", "{% extends \"base.html\" %}\n{% block titre %}Déconnexion — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"panneau etroit\">\n    <h1>Déconnexion</h1>\n    <p>À bientôt, {{ user.name }} {{ user.surname }}.</p>\n    <form id=\"form-sortie\">\n      <button class=\"bouton\" type=\"submit\">Se déconnecter</button>\n    </form>\n    <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n    <p><a href=\"{{ retour }}\">Rester connecté</a></p>\n  </section>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('auth.static', filename='logout.js') }}\"></script>\n{% endblock %}\n");
source("auth/mot-de-passe/mot-de-passe.html", "Mot de passe", "html", "{% extends \"base.html\" %}\n{% block titre %}Mot de passe — Fiches de révision{% endblock %}\n{% block contenu %}\n  <section class=\"panneau etroit\">\n    {% if obligatoire %}\n      <h1>Choisis ton mot de passe</h1>\n      <p>C'est ta première connexion. Le mot de passe reçu au départ doit être remplacé avant d'ouvrir les fiches.</p>\n    {% else %}\n      <h1>Modifier mon mot de passe</h1>\n      <p>Tu peux le changer quand tu veux. L'ancien est demandé pour confirmer que c'est bien toi.</p>\n    {% endif %}\n    <form id=\"form-mot-de-passe\">\n      <label class=\"champ\">Mot de passe actuel\n        <input type=\"password\" name=\"actuel\" required maxlength=\"200\" autocomplete=\"current-password\" autofocus>\n      </label>\n      <label class=\"champ\">Nouveau mot de passe\n        <input type=\"password\" name=\"nouveau\" required minlength=\"10\" maxlength=\"200\" autocomplete=\"new-password\">\n      </label>\n      <label class=\"champ\">Confirmer le nouveau\n        <input type=\"password\" name=\"confirmation\" required minlength=\"10\" maxlength=\"200\" autocomplete=\"new-password\">\n      </label>\n      <p class=\"note\">Au moins 10 caractères, différent de l'actuel et de ton identifiant.</p>\n      <button class=\"bouton\" type=\"submit\">Enregistrer</button>\n    </form>\n    <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n    {% if obligatoire %}\n      <p><a href=\"/auth/logout-page\">Se déconnecter</a></p>\n    {% else %}\n      <p><a href=\"{{ retour }}\">Retour à mon espace</a></p>\n    {% endif %}\n  </section>\n  <script id=\"mot-de-passe-config\" type=\"application/json\">{{ {\"obligatoire\": obligatoire, \"retour\": retour}|tojson }}</script>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('auth.static', filename='mot-de-passe.js') }}\"></script>\n{% endblock %}\n");
source("templates/legal/mentions.html", "Mentions légales", "html", "{% extends \"base.html\" %}\n{% block titre %}Mentions légales — Fiches de révision{% endblock %}\n{% block contenu %}\n  <article class=\"panneau etroit\">\n    <h1>Mentions légales</h1>\n    <p>Ce site sert à partager des fiches de révision entre élèves. Il n'est pas un réseau social et ne diffuse pas de publicité.</p>\n    <h2>Éditeur</h2>\n    <p>Le site est édité par son propriétaire, le compte dont le rôle est « owner ». C'est la seule personne qui peut suspendre le service. Il n'y a pas d'autre éditeur.</p>\n    <h2>Hébergement</h2>\n    <p>Le site est hébergé sur la machine qui exécute l'application. Les fiches restent dans les dossiers <code>matiere/</code> et <code>uploads/</code> de cette machine. Les comptes sont dans une base SQLite locale.</p>\n    <h2>Contact</h2>\n    <p>Pour une question sur un contenu ou un compte, écris au propriétaire du site par le moyen qu'il a indiqué à l'établissement. Le site lui-même n'envoie pas d'e-mail.</p>\n    <h2>Contenu publié</h2>\n    <p>Chaque fiche est publiée par un compte. L'auteur affiché est l'identifiant de ce compte. Un élève ne modifie que ses propres fiches. Les modérateurs, les administrateurs et le propriétaire peuvent retirer un contenu.</p>\n  </article>\n{% endblock %}\n");
source("templates/legal/confidentialite.html", "Politique de confidentialité", "html", "{% extends \"base.html\" %}\n{% block titre %}Politique de confidentialité — Fiches de révision{% endblock %}\n{% block contenu %}\n  <article class=\"panneau etroit\">\n    <h1>Politique de confidentialité</h1>\n    <p>Cette page décrit les données réellement enregistrées. Rien n'est vendu, rien n'est envoyé à un service publicitaire.</p>\n    <h2>Compte</h2>\n    <p>Un compte garde le prénom, le nom, l'identifiant, le rôle, l'état suspendu ou non, et la date de création. Le mot de passe est stocké sous forme de hash. Le texte saisi n'est pas conservé.</p>\n    <h2>Fiches</h2>\n    <p>Le fichier envoyé, son titre, sa description, le cours et le nom d'origine du document sont gardés tant que la fiche n'est pas supprimée. La suppression retire le fichier, sa description, les étoiles et les commentaires liés.</p>\n    <h2>Activité</h2>\n    <p>Le compte retient les identifiants des fiches qu'il a envoyées et téléchargées. Une étoile relie un compte à une fiche. Un commentaire garde le texte, l'auteur, la visibilité choisie et, s'il est suivi, le compte qui s'en occupe.</p>\n    <h2>Session</h2>\n    <p>À la connexion, une session est ouverte jusqu'à expiration du jeton, huit heures, ou jusqu'à la déconnexion. Elle retient l'identifiant du compte, les dates d'ouverture et de dernière activité, et le nom du navigateur, raccourci. L'adresse IP n'est pas enregistrée dans cette table.</p>\n    <h2>Qui peut lire quoi</h2>\n    <p>L'élève voit ses fiches et les commentaires qui lui sont destinés. L'équipe voit les commentaires qui lui sont adressés. Le propriétaire voit les chiffres du site et les sessions. Le mot de passe n'est montré à personne.</p>\n    <h2>Durée</h2>\n    <p>Les données restent tant que le compte et les fiches existent. La déconnexion ferme la session. Un compte suspendu ne peut plus se connecter, mais ses fiches déjà publiées restent jusqu'à suppression.</p>\n  </article>\n{% endblock %}\n");
source("templates/legal/cookies.html", "Gestion des cookies", "html", "{% extends \"base.html\" %}\n{% block titre %}Gestion des cookies — Fiches de révision{% endblock %}\n{% block contenu %}\n  <article class=\"panneau etroit\">\n    <h1>Gestion des cookies</h1>\n    <p>Le site ne dépose que des cookies nécessaires à la connexion et à la protection des formulaires. Il n'y a pas de cookie de mesure d'audience ni de publicité.</p>\n    <h2>Cookies utilisés</h2>\n    <ul>\n      <li><strong>Cookie de session</strong>. Déposé à la connexion, HttpOnly : le JavaScript de la page ne peut pas le lire. Il identifie le compte pendant huit heures.</li>\n      <li><strong>Cookie CSRF</strong>. Déposé en même temps. Le script l'envoie avec les actions qui modifient quelque chose, pour qu'un autre site ne puisse pas agir à ta place.</li>\n    </ul>\n    <h2>Ce qui n'est pas un cookie</h2>\n    <p>Le bandeau d'information mémorise ton accusé dans le stockage local du navigateur, sous le nom <code>fiches-cookies</code>. Ce n'est pas envoyé au serveur.</p>\n    <h2>Refus</h2>\n    <p>Sans le cookie de session, la connexion ne tient pas. Le refuser revient à se déconnecter. Tu peux effacer les cookies du site dans le navigateur, ou utiliser le bouton ci-dessous pour revoir le bandeau.</p>\n    <button id=\"cookies-oublier\" class=\"bouton bouton-secondaire\" type=\"button\">Revoir le bandeau</button>\n    <p id=\"statut\" class=\"statut\" role=\"status\"></p>\n  </article>\n{% endblock %}\n{% block scripts %}\n  <script src=\"{{ url_for('static', filename='cookies.js') }}\"></script>\n{% endblock %}\n");
source("templates/legal/licences.html", "Licences", "html", "{% extends \"base.html\" %}\n{% block titre %}Licences — Fiches de révision{% endblock %}\n{% block contenu %}\n  <article class=\"panneau etroit\">\n    <h1>Licences</h1>\n    <p>Le code du site est celui de ce dépôt. Les bibliothèques ci-dessous gardent leur propre licence. Les fiches envoyées par les élèves restent la propriété de leurs auteurs.</p>\n    <ul>\n      <li>Flask, licence BSD à trois clauses.</li>\n      <li>Werkzeug, licence BSD à trois clauses.</li>\n      <li>Flask-SQLAlchemy, licence BSD à trois clauses.</li>\n      <li>SQLAlchemy, licence MIT.</li>\n      <li>Flask-JWT-Extended, licence MIT.</li>\n      <li>Gunicorn, licence MIT.</li>\n      <li>Requests, licence Apache 2.0.</li>\n    </ul>\n    <p>Les textes de ces licences sont ceux publiés avec chaque bibliothèque dans l'environnement Python du serveur.</p>\n  </article>\n{% endblock %}\n");
source("documentation/index.html", "Page de cette documentation", "html", "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Documentation — Fiches de révision</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <a class=\"passer\" href=\"#lecture\">Aller au texte</a>\n  <header class=\"entete\">\n    <div class=\"marque\">\n      <p class=\"sur\">Documentation locale</p>\n      <h1>Fiches de révision</h1>\n    </div>\n    <form id=\"form-recherche\" role=\"search\">\n      <label for=\"recherche\">Rechercher</label>\n      <input id=\"recherche\" type=\"search\" placeholder=\"Fonction, fichier, rôle, étoile, commentaire…\" autocomplete=\"off\">\n    </form>\n  </header>\n\n  <div class=\"filtres\" id=\"filtres\" aria-label=\"Filtrer par langage\"></div>\n\n  <div class=\"cadre\">\n    <nav class=\"menu\" id=\"menu\" aria-label=\"Sommaire\"></nav>\n    <article class=\"lecture\" id=\"lecture\" tabindex=\"-1\"></article>\n  </div>\n\n  <script src=\"donnees-guide.js\"></script>\n  <script src=\"donnees-python.js\"></script>\n  <script src=\"donnees-javascript.js\"></script>\n  <script src=\"donnees-html.js\"></script>\n  <script src=\"donnees-css.js\"></script>\n  <script src=\"precisions.js\"></script>\n  <script src=\"precisions-suite.js\"></script>\n  <script src=\"sources.js\"></script>\n  <script src=\"coloration.js\"></script>\n  <script src=\"menu.js\"></script>\n</body>\n</html>\n");
source("static/common.js", "preparerCookies", "javascript", "function preparerCookies() {\n  const bandeau = document.getElementById(\"banniere-cookies\");\n  const bouton = document.getElementById(\"cookies-ok\");\n  if (!bandeau || !bouton) return;\n  if (localStorage.getItem(\"fiches-cookies\") === \"compris\") return;\n  bandeau.hidden = false;\n  bouton.addEventListener(\"click\", function () {\n    localStorage.setItem(\"fiches-cookies\", \"compris\");\n    bandeau.hidden = true;\n  });\n}\n");
source("static/comptes.js", "criteres", "javascript", "  function criteres() {\n    const params = new URLSearchParams();\n    if (!formulaire) return params;\n    new FormData(formulaire).forEach(function (valeur, cle) {\n      const texte = String(valeur || \"\").trim();\n      if (texte) params.set(cle, texte);\n    });\n    return params;\n  }\n");
source("static/comptes.js", "lancer", "javascript", "  function lancer() {\n    const params = criteres();\n    const ticket = ++serie;\n    if (!params.toString()) {\n      dessiner(comptes);\n      afficherStatut(\"statut\", \"\", \"\");\n      return;\n    }\n    api(prefixe + \"/comptes/recherche?\" + params.toString()).then(function (reponse) {\n      if (ticket !== serie) return;\n      if (reponse.status === 401) {\n        window.location.assign(\"/auth/login-page?next=\" + encodeURIComponent(window.location.pathname));\n        return;\n      }\n      if (!reponse.ok) {\n        afficherStatut(\"statut\", reponse.data.error || \"Recherche impossible\", \"erreur\");\n        return;\n      }\n      dessiner(reponse.data.comptes || []);\n      afficherStatut(\n        \"statut\",\n        reponse.data.tronque ? \"Liste limitée aux 100 premiers comptes.\" : \"\",\n        reponse.data.tronque ? \"ok\" : \"\"\n      );\n    });\n  }\n");
source("static/comptes.js", "bientot", "javascript", "  function bientot() {\n    window.clearTimeout(delai);\n    delai = window.setTimeout(lancer, 250);\n  }\n");
source("static/audit.js", "etoilesDe", "javascript", "  function etoilesDe(releve) {\n    return releve.etoiles || {};\n  }\n");
source("static/audit.js", "dessinerGraphiques", "javascript", "  function dessinerGraphiques(site, stockage, comptes, roles, activite, contenu, etoiles) {\n    const zone = document.getElementById(\"graphiques\");\n    if (!zone || typeof anneau !== \"function\") return;\n    zone.replaceChildren();\n    const rolesParts = [\n      { libelle: \"Élèves\", valeur: roles.user || 0, couleur: \"#1d6b4f\" },\n      { libelle: \"Modérateurs\", valeur: roles.moderator || 0, couleur: \"#1d4e89\" },\n      { libelle: \"Administrateurs\", valeur: roles.admin || 0, couleur: \"#b86b12\" },\n      { libelle: \"Propriétaire\", valeur: roles.owner || 0, couleur: \"#6b3fa0\" }\n    ];\n    const blocRoles = document.createElement(\"div\");\n    const titreRoles = document.createElement(\"h3\");\n    titreRoles.textContent = \"Comptes\";\n    blocRoles.append(titreRoles, anneau(rolesParts));\n    const blocStock = document.createElement(\"div\");\n    const titreStock = document.createElement(\"h3\");\n    titreStock.textContent = \"Disque\";\n    blocStock.append(\n      titreStock,\n      barreAnimee(\"Utilisé\", stockage.disque_utilise_octets || 0, stockage.disque_total_octets || 0, octets(stockage.disque_utilise_octets)),\n      barreAnimee(\"Libre\", stockage.disque_libre_octets || 0, stockage.disque_total_octets || 0, octets(stockage.disque_libre_octets))\n    );\n    const blocMatiere = document.createElement(\"div\");\n    const titreMatiere = document.createElement(\"h3\");\n    titreMatiere.textContent = \"Fiches par matière\";\n    blocMatiere.append(titreMatiere);\n    const matieres = (contenu.par_matiere || []).slice(0, 8);\n    const maxFiches = matieres.reduce(function (max, ligne) {\n      return Math.max(max, ligne.fiches || 0);\n    }, 0);\n    matieres.forEach(function (ligne) {\n      blocMatiere.append(barreAnimee(ligne.nom, ligne.fiches || 0, maxFiches, nombre(ligne.fiches) + \" fiches\"));\n    });\n    const blocEtoiles = document.createElement(\"div\");\n    const titreEtoiles = document.createElement(\"h3\");\n    titreEtoiles.textContent = \"Étoiles\";\n    blocEtoiles.append(titreEtoiles);\n    if (etoiles.plus_etoilee) {\n      const phrase = document.createElement(\"p\");\n      phrase.textContent = etoiles.plus_etoilee.titre + \" · \" + nombre(etoiles.plus_etoilee.etoiles);\n      blocEtoiles.append(phrase);\n    }\n    (etoiles.par_matiere || []).slice(0, 6).forEach(function (groupe) {\n      const fiche = (groupe.fiches || [])[0];\n      if (!fiche) return;\n      blocEtoiles.append(barreAnimee(groupe.matiere, fiche.etoiles || 0, etoiles.plus_etoilee ? etoiles.plus_etoilee.etoiles : fiche.etoiles, fiche.titre));\n    });\n    zone.append(blocRoles, blocStock, blocMatiere, blocEtoiles);\n    if (site.suspendu) {\n      const pause = document.createElement(\"p\");\n      pause.className = \"note\";\n      pause.textContent = \"Le site est suspendu.\";\n      zone.prepend(pause);\n    }\n  }\n");
source("static/graphiques.js", "barreAnimee", "javascript", "function barreAnimee(etiquette, valeur, maximum, detail) {\n  const ligne = document.createElement(\"div\");\n  ligne.className = \"ligne-graphique\";\n  const legende = document.createElement(\"p\");\n  legende.textContent = etiquette + \" · \" + detail;\n  const piste = document.createElement(\"div\");\n  piste.className = \"piste\";\n  const remplissage = document.createElement(\"span\");\n  const part = maximum > 0 ? Math.max(valeur > 0 ? 6 : 0, Math.round(valeur / maximum * 100)) : 0;\n  remplissage.style.setProperty(\"--largeur\", part + \"%\");\n  piste.append(remplissage);\n  ligne.append(legende, piste);\n  return ligne;\n}\n");
source("static/graphiques.js", "anneau", "javascript", "function anneau(parts) {\n  const bloc = document.createElement(\"div\");\n  bloc.className = \"bloc-anneau\";\n  const svg = document.createElementNS(\"http://www.w3.org/2000/svg\", \"svg\");\n  svg.setAttribute(\"viewBox\", \"0 0 42 42\");\n  svg.setAttribute(\"class\", \"anneau\");\n  svg.setAttribute(\"role\", \"img\");\n  const total = parts.reduce(function (somme, part) { return somme + part.valeur; }, 0) || 1;\n  let depart = 0;\n  parts.forEach(function (part) {\n    const portion = part.valeur / total * 100;\n    if (portion <= 0) return;\n    const cercle = document.createElementNS(\"http://www.w3.org/2000/svg\", \"circle\");\n    cercle.setAttribute(\"cx\", \"21\");\n    cercle.setAttribute(\"cy\", \"21\");\n    cercle.setAttribute(\"r\", \"15.9\");\n    cercle.setAttribute(\"fill\", \"none\");\n    cercle.setAttribute(\"stroke\", part.couleur);\n    cercle.setAttribute(\"stroke-width\", \"6\");\n    cercle.setAttribute(\"pathLength\", \"100\");\n    cercle.style.strokeDashoffset = String(25 - depart);\n    cercle.style.setProperty(\"--part\", String(portion));\n    cercle.classList.add(\"segment\");\n    svg.append(cercle);\n    depart += portion;\n  });\n  const liste = document.createElement(\"ul\");\n  liste.className = \"legende-anneau\";\n  parts.forEach(function (part) {\n    const item = document.createElement(\"li\");\n    const puce = document.createElement(\"i\");\n    puce.style.background = part.couleur;\n    item.append(puce, document.createTextNode(part.libelle + \" · \" + part.valeur));\n    liste.append(item);\n  });\n  bloc.append(svg, liste);\n  return bloc;\n}\n");
source("static/cookies.js", "Revoir le bandeau", "javascript", "/* Retire seulement l'accusé du bandeau. Les cookies de session ne sont pas effacés ici. */\n\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  const bouton = document.getElementById(\"cookies-oublier\");\n  if (!bouton) return;\n  bouton.addEventListener(\"click\", function () {\n    localStorage.removeItem(\"fiches-cookies\");\n    afficherStatut(\"statut\", \"Le bandeau réapparaîtra au prochain affichage.\", \"ok\");\n  });\n});\n");
