source("static/style.css", ".menu-legal", "css", ".menu-legal {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 0.6rem 1rem;\n  margin-top: 0.4rem;\n}\n");
source("static/style.css", ".menu-liste", "css", ".menu-liste { position: relative; display: inline-block; }\n\n.menu-liste > summary {\n  list-style: none;\n  cursor: pointer;\n  border: 1px solid var(--foret);\n  color: var(--foret-fonce);\n  border-radius: 999px;\n  padding: 0.45rem 0.9rem;\n  background: white;\n}\n\n.menu-liste > summary::-webkit-details-marker { display: none; }\n\n.menu-panneau {\n  position: absolute;\n  z-index: 4;\n  min-width: 14rem;\n  margin-top: 0.35rem;\n  padding: 0.35rem;\n  background: white;\n  border: 1px solid var(--ligne);\n  border-radius: 12px;\n  box-shadow: var(--ombre);\n}\n\n.menu-panneau a, .menu-panneau button {\n  display: block;\n  width: 100%;\n  text-align: left;\n  background: transparent;\n  color: var(--encre);\n  border: 0;\n  border-radius: 8px;\n  padding: 0.5rem 0.65rem;\n  font: inherit;\n  text-decoration: none;\n  cursor: pointer;\n}\n\n.menu-panneau a:hover, .menu-panneau button:hover { background: #f7f1e6; }\n");
source("static/style.css", ".barre-fiche", "css", ".barre-fiche {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.6rem;\n  align-items: center;\n  margin-top: 0.8rem;\n}\n");
source("static/style.css", ".onglets", "css", ".onglets {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin: 0.6rem 0;\n}\n\n.onglets button {\n  border: 0;\n  background: transparent;\n  color: var(--encre-douce);\n  border-bottom: 2px solid transparent;\n  padding: 0.45rem 0.7rem;\n  font: inherit;\n  cursor: pointer;\n}\n\n.onglets button[aria-selected=\"true\"] {\n  color: var(--foret-fonce);\n  border-bottom-color: var(--foret);\n}\n");
source("static/style.css", ".piste", "css", ".graphiques {\n  display: grid;\n  gap: 1rem;\n}\n\n.ligne-graphique { margin: 0.55rem 0; }\n\n.piste {\n  height: 0.7rem;\n  background: #efe8da;\n  border-radius: 999px;\n  overflow: hidden;\n}\n\n.piste span {\n  display: block;\n  height: 100%;\n  width: 0;\n  background: var(--foret);\n  border-radius: 999px;\n  animation: remplir 0.8s ease forwards;\n}\n\n@keyframes remplir {\n  to { width: var(--largeur); }\n}\n");
source("static/style.css", ".anneau", "css", ".bloc-anneau {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n  align-items: center;\n}\n\n.anneau { width: 9rem; height: 9rem; }\n\n.segment {\n  stroke-dasharray: 0 100;\n  transform-origin: 50% 50%;\n  transform: rotate(-90deg);\n  animation: tracer 0.9s ease forwards;\n}\n\n@keyframes tracer {\n  to { stroke-dasharray: var(--part) calc(100 - var(--part)); }\n}\n\n.legende-anneau { list-style: none; padding: 0; margin: 0; }\n\n.legende-anneau li { display: flex; gap: 0.4rem; align-items: center; margin: 0.25rem 0; }\n\n.legende-anneau i {\n  width: 0.7rem;\n  height: 0.7rem;\n  border-radius: 50%;\n  display: inline-block;\n}\n");
source("static/style.css", ".banniere-cookies", "css", ".banniere-cookies {\n  position: fixed;\n  left: 1rem;\n  right: 1rem;\n  bottom: 1rem;\n  z-index: 5;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.7rem;\n  align-items: center;\n  background: var(--carte);\n  border: 1px solid var(--ligne);\n  border-radius: 16px;\n  padding: 0.8rem 1rem;\n  box-shadow: var(--ombre);\n}\n\n.banniere-cookies p { margin: 0; flex: 1 1 16rem; }\n");
